def _integrate_chronological_analyses(chronology_framework: Dict) -> Dict:
    """Integrate all chronological analyses for final age determination"""
    
    # Weight different types of evidence
    evidence_weights = {
        'stratigraphic_analysis': 0.20,
        'structural_analysis': 0.25,
        'crosscutting_analysis': 0.20,
        'metamorphic_analysis': 0.15,
        'kinematic_analysis': 0.10,
        'geochronological_analysis': 0.30
    }
    
    # Calculate weighted age determinations
    weighted_ages = {}
    for analysis_type, framework in chronology_framework.items():
        age_indicators = _extract_age_indicators_from_framework(framework)
        weighted_ages[analysis_type] = {
            'age_estimate': age_indicators['age_estimate'],
            'confidence': age_indicators['confidence'],
            'weight': evidence_weights.get(analysis_type, 0.1)
        }
    
    # Determine most likely age through Bayesian integration
    most_likely_age = _perform_bayesian_age_integration(weighted_ages)
    
    return {
        'most_likely_age': most_likely_age['age_category'],
        'confidence': most_likely_age['confidence'],
        'uncertainty': most_likely_age['uncertainty'],
        'supporting_evidence': most_likely_age['evidence_summary']
    }

