def _calculate_integrated_sequence_rank(temporal_framework: Dict) -> Dict:
    """Calculate integrated sequence rank from temporal framework"""
    
    # Weight different types of temporal evidence
    evidence_weights = {
        'relative_timing_analysis': 0.25,
        'deformation_sequence_analysis': 0.25,
        'structural_hierarchy_analysis': 0.20,
        'crosscutting_analysis': 0.15,
        'geometric_analysis': 0.10,
        'kinematic_analysis': 0.05
    }
    
    # Calculate rank contributions from each analysis
    rank_contributions = {}
    for analysis_type, framework in temporal_framework.items():
        rank_indicators = _extract_rank_indicators_from_framework(framework)
        rank_contributions[analysis_type] = {
            'rank_estimate': rank_indicators['rank_estimate'],
            'confidence': rank_indicators['confidence'],
            'weight': evidence_weights.get(analysis_type, 0.1)
        }
    
    # Calculate weighted sequence rank
    weighted_rank = _calculate_weighted_sequence_rank(rank_contributions)
    
    return {
        'rank': int(np.round(weighted_rank['rank_value'])),
        'confidence': weighted_rank['confidence'],
        'uncertainty': weighted_rank['uncertainty'],
        'supporting_evidence': weighted_rank['evidence_summary']
    }

