def _calculate_integrated_confidence_metrics(confidence_framework: Dict) -> Dict:
    """Calculate integrated confidence metrics from confidence framework"""
    
    # Weight different types of confidence assessment
    confidence_weights = {
        'data_quality_analysis': 0.25,
        'constraint_reliability_analysis': 0.25,
        'method_validation_analysis': 0.20,
        'uncertainty_propagation_analysis': 0.15,
        'sensitivity_analysis': 0.10,
        'robustness_analysis': 0.05
    }
    
    # Calculate confidence contributions from each analysis
    confidence_contributions = {}
    for analysis_type, framework in confidence_framework.items():
        confidence_indicators = _extract_confidence_indicators_from_framework(framework)
        confidence_contributions[analysis_type] = {
            'confidence_estimate': confidence_indicators['confidence_estimate'],
            'reliability': confidence_indicators['reliability'],
            'weight': confidence_weights.get(analysis_type, 0.1)
        }
    
    # Calculate weighted overall confidence
    overall_confidence = _calculate_weighted_overall_confidence(confidence_contributions)
    
    return {
        'overall_confidence': overall_confidence['confidence_value'],
        'reliability': overall_confidence['reliability'],
        'uncertainty': overall_confidence['uncertainty'],
        'confidence_breakdown': overall_confidence['breakdown']
    }

