def _identify_superposition_indicators(relative_chronology: Dict) -> List:
    """Identify stratigraphic superposition indicators"""
    indicators = []
    
    # Examine stratigraphic relationships
    if 'stratigraphic_data' in relative_chronology:
        stratigraphic_data = relative_chronology['stratigraphic_data']
        
        # Primary sedimentary structures
        if 'primary_structures' in stratigraphic_data:
            structures = stratigraphic_data['primary_structures']
            indicators.extend(_extract_way_up_indicators_from_structures(structures))
        
        # Bedding relationships
        if 'bedding_relationships' in stratigraphic_data:
            bedding = stratigraphic_data['bedding_relationships']
            indicators.extend(_extract_superposition_from_bedding(bedding))
        
        # Fossil relationships
        if 'fossil_data' in stratigraphic_data:
            fossils = stratigraphic_data['fossil_data']
            indicators.extend(_extract_biostratigraphic_indicators(fossils))
    
    return indicators

def _extract_age_indicators_from_framework(framework: Dict) -> Dict:
    """Extract age indicators from analysis framework"""
    age_estimates = []
    confidence_values = []
    
    for analysis_category, analysis_data in framework.items():
        if isinstance(analysis_data, dict):
            for analysis_type, results in analysis_data.items():
                if isinstance(results, dict) and 'age_estimate' in results:
                    age_estimates.append(results['age_estimate'])
                    confidence_values.append(results.get('confidence', 0.5))
    
    # Statistical combination of age estimates
    if age_estimates:
        weighted_age = np.average(age_estimates, weights=confidence_values)
        overall_confidence = np.mean(confidence_values)
    else:
        weighted_age = 'unknown'
        overall_confidence = 0.0
    
    return {
        'age_estimate': weighted_age,
        'confidence': overall_confidence,
        'number_of_indicators': len(age_estimates)
    }

def _extract_rank_indicators_from_framework(framework: Dict) -> Dict:
    """Extract rank indicators from temporal framework"""
    rank_estimates = []
    confidence_values = []
    
    for analysis_category, analysis_data in framework.items():
        if isinstance(analysis_data, dict):
            for analysis_type, results in analysis_data.items():
                if isinstance(results, dict) and 'rank_estimate' in results:
                    rank_estimates.append(results['rank_estimate'])
                    confidence_values.append(results.get('confidence', 0.5))
    
    # Statistical combination of rank estimates
    if rank_estimates:
        weighted_rank = np.average(rank_estimates, weights=confidence_values)
        overall_confidence = np.mean(confidence_values)
    else:
        weighted_rank = 1
        overall_confidence = 0.0
    
    return {
        'rank_estimate': weighted_rank,
        'confidence': overall_confidence,
        'number_of_indicators': len(rank_estimates)
    }

def _extract_confidence_indicators_from_framework(framework: Dict) -> Dict:
    """Extract confidence indicators from confidence framework"""
    confidence_estimates = []
    reliability_values = []
    
    for analysis_category, analysis_data in framework.items():
        if isinstance(analysis_data, dict):
            for analysis_type, results in analysis_data.items():
                if isinstance(results, dict) and 'confidence_estimate' in results:
                    confidence_estimates.append(results['confidence_estimate'])
                    reliability_values.append(results.get('reliability', 0.5))
    
    # Statistical combination of confidence estimates
    if confidence_estimates:
        weighted_confidence = np.average(confidence_estimates, weights=reliability_values)
        overall_reliability = np.mean(reliability_values)
    else:
        weighted_confidence = 0.5
        overall_reliability = 0.0
    
    return {
        'confidence_estimate': weighted_confidence,
        'reliability': overall_reliability,
        'number_of_indicators': len(confidence_estimates)
    }

def _calculate_weighted_sequence_rank(rank_contributions: Dict) -> Dict:
    """Calculate weighted sequence rank from contributions"""
    total_weight = sum(contrib['weight'] for contrib in rank_contributions.values())
    
    if total_weight > 0:
        weighted_rank = sum(
            contrib['rank_estimate'] * contrib['weight'] 
            for contrib in rank_contributions.values()
        ) / total_weight
        
        weighted_confidence = sum(
            contrib['confidence'] * contrib['weight'] 
            for contrib in rank_contributions.values()
        ) / total_weight
    else:
        weighted_rank = 1
        weighted_confidence = 0.0
    
    # Calculate uncertainty from confidence
    uncertainty = 1.0 - weighted_confidence
    
    return {
        'rank_value': weighted_rank,
        'confidence': weighted_confidence,
        'uncertainty': uncertainty,
        'evidence_summary': list(rank_contributions.keys())
    }

def _calculate_weighted_overall_confidence(confidence_contributions: Dict) -> Dict:
    """Calculate weighted overall confidence from contributions"""
    total_weight = sum(contrib['weight'] for contrib in confidence_contributions.values())
    
    if total_weight > 0:
        weighted_confidence = sum(
            contrib['confidence_estimate'] * contrib['weight'] 
            for contrib in confidence_contributions.values()
        ) / total_weight
        
        weighted_reliability = sum(
            contrib['reliability'] * contrib['weight'] 
            for contrib in confidence_contributions.values()
        ) / total_weight
    else:
        weighted_confidence = 0.5
        weighted_reliability = 0.0
    
    # Calculate uncertainty from confidence and reliability
    uncertainty = 1.0 - (weighted_confidence * weighted_reliability)
    
    return {
        'confidence_value': weighted_confidence,
        'reliability': weighted_reliability,
        'uncertainty': uncertainty,
        'breakdown': {k: v['confidence_estimate'] for k, v in confidence_contributions.items()}
    }

