    def _integrate_crosscutting_evidence(self, geometric: Dict, kinematic: Dict, spatial: Dict, overprinting: Dict, temporal: Dict) -> Dict:
        """Integrate all crosscutting evidence"""
        confidence_factors = [
            geometric.get('geometric_compatibility', 0.5),
            kinematic.get('kinematic_consistency', 0.5),
            spatial.get('spatial_coherence', 0.5),
            overprinting.get('deformation_intensity', {}).get('constraint2', 0.5),
            temporal.get('precedence_confidence', 0.5)
        ]
        
        return {
            'crosscuts': temporal.get('precedence_relationship') == 'constraint2_younger',
            'relationship_type': 'crosscutting' if any(c > 0.7 for c in confidence_factors) else 'uncertain',
            'confidence': np.mean(confidence_factors),
            'uncertainty': np.std(confidence_factors),
            'field_evidence': 'comprehensive',
            'structural_framework': 'well_constrained'
        }

    # Matrix analysis helpers
    def _analyze_matrix_topology(self, matrix: np.ndarray, constraint_ids: List) -> Dict:
        """Analyze matrix topology properties"""
        return {
            'node_count': len(constraint_ids),
            'edge_count': int(np.sum(matrix)),
            'graph_density': np.sum(matrix) / (len(constraint_ids) * (len(constraint_ids) - 1)),
            'acyclic': self._check_matrix_acyclicity(matrix)
        }
    
    def _assess_matrix_connectivity(self, matrix: np.ndarray, constraint_ids: List) -> Dict:
        """Assess matrix connectivity properties"""
        return {
            'connectivity_level': 'high' if np.sum(matrix) > len(constraint_ids) else 'moderate',
            'weakly_connected': True,
            'strongly_connected': self._check_strong_connectivity(matrix),
            'connectivity_components': self._identify_connectivity_components(matrix)
        }
    
    def _assess_temporal_complexity(self, matrix: np.ndarray, constraint_ids: List) -> Dict:
        """Assess temporal complexity from matrix"""
        return {
            'complexity_index': np.sum(matrix) / len(constraint_ids),
            'branching_factor': self._calculate_branching_factor(matrix),
            'temporal_depth': self._calculate_temporal_depth(matrix),
            'complexity_classification': 'moderate'
        }

    # Age calculation helpers
    def _calculate_topological_ages(self, matrix: np.ndarray, constraint_ids: List) -> Dict:
        """Calculate ages using topological sorting"""
        ages = {}
        for i, constraint_id in enumerate(constraint_ids):
            incoming_edges = np.sum(matrix[:, i])
            ages[constraint_id] = len(constraint_ids) - incoming_edges
        return ages
    
    def _calculate_eigenvalue_ages(self, matrix: np.ndarray, constraint_ids: List) -> Dict:
        """Calculate ages using eigenvalue analysis"""
        try:
            eigenvals = np.linalg.eigvals(matrix.astype(float))
            principal_eigenval = np.max(np.real(eigenvals))
            ages = {}
            for i, constraint_id in enumerate(constraint_ids):
                ages[constraint_id] = float(i + principal_eigenval)
            return ages
        except:
            return {cid: float(i) for i, cid in enumerate(constraint_ids)}
    
    def _calculate_consensus_ages(self, topo_ages: Dict, eigen_ages: Dict, trans_ages: Dict, dom_ages: Dict) -> Dict:
        """Calculate consensus ages from multiple methods"""
        consensus = {}
        for constraint_id in topo_ages.keys():
            ages = [
                topo_ages.get(constraint_id, 0),
                eigen_ages.get(constraint_id, 0),
                trans_ages.get(constraint_id, 0),
                dom_ages.get(constraint_id, 0)
            ]
            consensus[constraint_id] = np.mean(ages)
        return consensus

