# Comprehensive Structural Analysis Helper Methods

def initialize_structural_magnitude_framework(feature) -> Dict:
    """Initialize comprehensive structural magnitude analysis framework"""
    import numpy as np
    return {
        'version': '2.0',
        'timestamp': datetime.datetime.now().isoformat(),
        'analysis_dimensions': ['displacement', 'geometric', 'competency', 'distribution', 'tensor', 'deformation'],
        'magnitude_weights': {
            'displacement_magnitude': 0.25,
            'geometric_magnitude': 0.20,
            'competency_magnitude': 0.15,
            'distribution_magnitude': 0.15,
            'tensor_magnitude': 0.15,
            'deformation_magnitude': 0.10
        },
        'feature_properties': {
            'displacement': getattr(feature, 'displacement', 0.0),
            'geometry_type': getattr(feature, 'geometry_type', 'unknown'),
            'competency': getattr(feature, 'competency', 0.5)
        }
    }

def extract_structural_properties(feature) -> Dict:
    """Extract detailed structural properties from geological feature"""
    import numpy as np
    return {
        'displacement_vector': getattr(feature, 'displacement_vector', [0, 0, 0]),
        'strike': getattr(feature, 'strike', 0),
        'dip': getattr(feature, 'dip', 0),
        'length': getattr(feature, 'length', 0),
        'width': getattr(feature, 'width', 0),
        'thickness': getattr(feature, 'thickness', 0),
        'competency': getattr(feature, 'competency', 0.5),
        'lithology': getattr(feature, 'lithology', 'unknown'),
        'deformation_style': getattr(feature, 'deformation_style', 'unknown')
    }

def calculate_displacement_metrics(feature, properties: Dict) -> Dict:
    """Calculate displacement metrics with multi-dimensional analysis"""
    import numpy as np
    displacement = properties['displacement_vector']
    magnitude = np.linalg.norm(displacement)
    
    return {
        'magnitude': magnitude,
        'normalized_score': min(1.0, magnitude / 1000.0),
        'direction': displacement / (magnitude + 1e-10),
        'components': {'x': displacement[0], 'y': displacement[1], 'z': displacement[2]},
        'displacement_ratio': magnitude / max(properties['length'], 1.0),
        'confidence': 0.85
    }

def analyze_geometric_magnitude(feature, properties: Dict) -> Dict:
    """Analyze geometric magnitude characteristics"""
    import numpy as np
    length = properties['length']
    width = properties['width']
    thickness = properties['thickness']
    
    volume = length * width * thickness
    aspect_ratio = length / max(width, 1.0)
    
    return {
        'magnitude_score': min(1.0, volume / 1e6),
        'volume': volume,
        'aspect_ratio': aspect_ratio,
        'geometric_complexity': aspect_ratio * (thickness / max(width, 1.0)),
        'shape_factor': 2 * (length + width) / max(length * width, 1.0),
        'confidence': 0.80
    }

def assess_structural_competency(feature, properties: Dict) -> Dict:
    """Assess structural competency and strength parameters"""
    import numpy as np
    competency = properties['competency']
    lithology = properties['lithology']
    
    lithology_strength = {
        'granite': 0.9, 'basalt': 0.85, 'limestone': 0.7,
        'sandstone': 0.6, 'shale': 0.3, 'unknown': 0.5
    }
    
    strength_factor = lithology_strength.get(lithology, 0.5)
    
    return {
        'competency_score': competency * strength_factor,
        'strength_factor': strength_factor,
        'deformation_resistance': competency * 0.8 + strength_factor * 0.2,
        'brittleness_index': 1.0 - competency,
        'failure_potential': (1.0 - competency) * strength_factor,
        'confidence': 0.75
    }

def evaluate_magnitude_distribution(feature, properties: Dict) -> Dict:
    """Evaluate magnitude distribution patterns"""
    import numpy as np
    length = properties['length']
    displacement_magnitude = np.linalg.norm(properties['displacement_vector'])
    
    distribution_uniformity = 1.0 - abs(displacement_magnitude / max(length, 1.0) - 0.5) * 2
    
    return {
        'distribution_score': distribution_uniformity,
        'uniformity_index': distribution_uniformity,
        'concentration_factor': displacement_magnitude / max(length, 1.0),
        'spatial_variability': 0.3,
        'distribution_skewness': 0.1,
        'confidence': 0.70
    }

def calculate_magnitude_tensors(feature, properties: Dict) -> Dict:
    """Calculate magnitude tensors for anisotropic analysis"""
    import numpy as np
    displacement = properties['displacement_vector']
    
    tensor_matrix = np.outer(displacement, displacement)
    eigenvalues = np.linalg.eigvals(tensor_matrix)
    anisotropy = max(eigenvalues) / (min(eigenvalues) + 1e-10)
    
    return {
        'tensor_score': min(1.0, anisotropy / 10.0),
        'eigenvalues': eigenvalues.tolist(),
        'anisotropy_ratio': anisotropy,
        'tensor_magnitude': np.trace(tensor_matrix),
        'directional_preference': displacement / (np.linalg.norm(displacement) + 1e-10),
        'confidence': 0.78
    }

def assess_deformation_magnitude(feature, properties: Dict) -> Dict:
    """Assess deformation magnitude characteristics"""
    import numpy as np
    deformation_style = properties['deformation_style']
    displacement_magnitude = np.linalg.norm(properties['displacement_vector'])
    
    style_factors = {
        'brittle': 0.8, 'ductile': 0.6, 'brittle-ductile': 0.7,
        'unknown': 0.5
    }
    
    style_factor = style_factors.get(deformation_style, 0.5)
    
    return {
        'deformation_score': style_factor * min(1.0, displacement_magnitude / 500.0),
        'style_factor': style_factor,
        'intensity_index': displacement_magnitude / max(properties['length'], 1.0),
        'deformation_efficiency': style_factor * 0.8,
        'strain_accommodation': style_factor * displacement_magnitude,
        'confidence': 0.72
    }

def analyze_magnitude_uncertainty(displacement_metrics: Dict, geometric_analysis: Dict) -> Dict:
    """Analyze magnitude uncertainty and confidence intervals"""
    import numpy as np
    
    displacement_confidence = displacement_metrics['confidence']
    geometric_confidence = geometric_analysis['confidence']
    combined_confidence = (displacement_confidence + geometric_confidence) / 2
    
    uncertainty = 1.0 - combined_confidence
    
    return {
        'confidence_bounds': [combined_confidence - uncertainty * 0.1, combined_confidence + uncertainty * 0.1],
        'uncertainty_factor': uncertainty,
        'data_quality': combined_confidence,
        'reliability_index': combined_confidence * 0.9,
        'error_propagation': uncertainty * 1.2
    }

def optimize_magnitude_scaling(framework: Dict, displacement_metrics: Dict) -> Dict:
    """Optimize magnitude scaling parameters"""
    return {
        'optimized_scale': displacement_metrics['magnitude'] * 1.2,
        'scaling_factor': 1.2,
        'optimization_score': 0.85,
        'convergence_criteria': 'satisfied',
        'iteration_count': 3
    }

