def _integrate_growth_rate_components(growth_rate_components):
    """Integrate growth rate components"""
    import numpy as np
    weights = np.random.uniform(0.1, 1.0, len(growth_rate_components))
    weights = weights / np.sum(weights)
    return np.sum([weights[i] * list(growth_rate_components.values())[i] for i in range(len(weights))])

