# Anderson regime analysis helper methods
def _analyze_principal_stresses(eigenvals: np.ndarray) -> Dict:
    """Analyze principal stress characteristics"""
    sorted_eigenvals = np.sort(eigenvals)[::-1]  # σ1 >= σ2 >= σ3
    sigma1, sigma2, sigma3 = sorted_eigenvals
    
    return {
        'principal_stresses': sorted_eigenvals,
        'maximum_principal': sigma1,
        'intermediate_principal': sigma2,
        'minimum_principal': sigma3,
        'differential_stress': sigma1 - sigma3,
        'mean_stress': np.mean(sorted_eigenvals),
        'stress_invariants': _calculate_stress_invariants(sorted_eigenvals),
        'stress_ellipsoid': _calculate_stress_ellipsoid_parameters(sorted_eigenvals)
    }

