def _analyze_coulomb_criteria(eigenvals: np.ndarray) -> Dict:
    """Analyze Coulomb failure criteria"""
    return {
        'coulomb_stress_change': _calculate_coulomb_stress_change(eigenvals),
        'failure_envelope': _calculate_failure_envelope(eigenvals),
        'stress_path_analysis': _analyze_stress_paths(eigenvals),
        'proximity_to_failure': _calculate_proximity_to_failure(eigenvals),
        'pore_pressure_effects': _analyze_pore_pressure_effects(eigenvals),
        'effective_stress_analysis': _analyze_effective_stresses(eigenvals)
    }

def _analyze_regime_probabilities(eigenvals: np.ndarray) -> Dict:
    """Analyze probabilistic regime classification"""
    return {
        'regime_probabilities': _calculate_regime_probabilities(eigenvals),
        'uncertainty_quantification': _quantify_classification_uncertainty(eigenvals),
        'bayesian_classification': _perform_bayesian_classification(eigenvals),
        'monte_carlo_analysis': _perform_monte_carlo_regime_analysis(eigenvals),
        'sensitivity_analysis': _perform_sensitivity_analysis(eigenvals),
        'confidence_intervals': _calculate_confidence_intervals(eigenvals)
    }

def _calculate_comprehensive_anderson_classification(framework: Dict, eigenvals: np.ndarray) -> Dict:
    """Calculate comprehensive Anderson regime classification"""
    sorted_eigenvals = np.sort(eigenvals)[::-1]
    sigma1, sigma2, sigma3 = sorted_eigenvals
    
    # Determine regime based on which principal stress is vertical
    regime_analysis = framework['principal_stress_analysis']
    probabilities = framework['probability_analysis']['regime_probabilities']
    
    # Get most likely regime
    regime_types = ['normal', 'reverse', 'strike_slip']
    regime_probs = [probabilities.get(regime, 0.33) for regime in regime_types]
    most_likely_regime = regime_types[np.argmax(regime_probs)]
    
    # Calculate optimal orientations
    orientations = framework['orientation_analysis']['optimal_orientations']
    
    return {
        'regime': most_likely_regime,
        'fault_type': f"{most_likely_regime}_fault",
        'optimal_orientation': orientations.get(most_likely_regime, np.array([45.0, 60.0])),
        'fault_likelihood': max(regime_probs),
        'stress_ratios': [sigma1/sigma3, sigma2/sigma3] if sigma3 != 0 else [1.0, 1.0],
        'all_regime_probabilities': dict(zip(regime_types, regime_probs)),
        'uncertainty_estimates': framework['probability_analysis']['uncertainty_quantification'],
        'stability_analysis': framework['stability_analysis'],
        'coulomb_analysis': framework['coulomb_analysis']
    }

# Additional helper methods for topographic stress calculations
def _calculate_isostatic_effect(elevation: float, domain_bounds: Dict) -> float:
    """Calculate isostatic adjustment effect"""
    return elevation * 0.8 * 2700 * 9.81 / 3300  # Airy isostasy

def _calculate_flexural_response(elevation: float, domain_bounds: Dict) -> float:
    """Calculate flexural response to topographic loading"""
    elastic_thickness = 20000  # 20 km typical
    return elevation * (2700 / 3300) * (1 - np.exp(-abs(elevation) / elastic_thickness))

def _calculate_slope_stability(slope_x: float, slope_y: float) -> float:
    """Calculate slope stability factor"""
    slope_angle = np.arctan(np.sqrt(slope_x**2 + slope_y**2))
    friction_angle = np.radians(30)  # Typical rock friction angle
    return np.tan(friction_angle) / np.tan(slope_angle) if slope_angle > 0 else 10.0

def _calculate_mass_wasting_potential(slope_x: float, slope_y: float) -> float:
    """Calculate mass wasting potential"""
    slope_magnitude = np.sqrt(slope_x**2 + slope_y**2)
    critical_slope = 0.6  # Critical slope for mass wasting
    return max(0, slope_magnitude - critical_slope) / critical_slope

def _calculate_erosional_stress(slope_x: float, slope_y: float) -> float:
    """Calculate erosional stress from slope"""
    return np.sqrt(slope_x**2 + slope_y**2) * 1e6  # Convert to Pa

