# Gradient calculation helper methods
def _find_gradient_neighbors(grid_points: np.ndarray, index: int, max_neighbors: int = 8) -> np.ndarray:
    """Find neighbors for gradient calculation"""
    distances = np.linalg.norm(grid_points - grid_points[index], axis=1)
    return np.argsort(distances)[1:min(max_neighbors+1, len(grid_points))]

def _calculate_forward_differences(grid_points: np.ndarray, stress_tensors: np.ndarray, 
                                 index: int, neighbors: np.ndarray) -> np.ndarray:
    """Calculate forward finite differences"""
    gradients = np.zeros((3, 3, 3))
    for i, neighbor in enumerate(neighbors[:3]):
        if i < len(neighbors):
            dx = grid_points[neighbor] - grid_points[index]
            ds = stress_tensors[neighbor] - stress_tensors[index]
            for j in range(3):
                if abs(dx[j]) > 1e-10:
                    gradients[:, :, j] = ds / dx[j]
    return gradients

def _calculate_backward_differences(grid_points: np.ndarray, stress_tensors: np.ndarray,
                                  index: int, neighbors: np.ndarray) -> np.ndarray:
    """Calculate backward finite differences"""
    gradients = np.zeros((3, 3, 3))
    for i, neighbor in enumerate(neighbors[:3]):
        if i < len(neighbors):
            dx = grid_points[index] - grid_points[neighbor]
            ds = stress_tensors[index] - stress_tensors[neighbor]
            for j in range(3):
                if abs(dx[j]) > 1e-10:
                    gradients[:, :, j] = ds / dx[j]
    return gradients

def _calculate_central_differences(grid_points: np.ndarray, stress_tensors: np.ndarray,
                                 index: int, neighbors: np.ndarray) -> np.ndarray:
    """Calculate central finite differences"""
    gradients = np.zeros((3, 3, 3))
    if len(neighbors) >= 2:
        for j in range(3):
            # Find neighbors in positive and negative directions
            pos_neighbor = neighbors[0]
            neg_neighbor = neighbors[1] if len(neighbors) > 1 else neighbors[0]
            
            dx = grid_points[pos_neighbor, j] - grid_points[neg_neighbor, j]
            ds = stress_tensors[pos_neighbor] - stress_tensors[neg_neighbor]
            
            if abs(dx) > 1e-10:
                gradients[:, :, j] = ds / dx
    return gradients

# Stress analysis helper methods (implementing key functions)
def _calculate_stress_invariants(eigenvals: np.ndarray) -> Dict:
    """Calculate stress tensor invariants"""
    I1 = np.sum(eigenvals)
    I2 = eigenvals[0]*eigenvals[1] + eigenvals[1]*eigenvals[2] + eigenvals[0]*eigenvals[2]
    I3 = np.prod(eigenvals)
    return {'I1': I1, 'I2': I2, 'I3': I3}

def _calculate_stress_ellipsoid_parameters(eigenvals: np.ndarray) -> Dict:
    """Calculate stress ellipsoid parameters"""
    sorted_vals = np.sort(eigenvals)[::-1]
    return {
        'semi_axes': sorted_vals,
        'ellipticity': (sorted_vals[0] - sorted_vals[2]) / sorted_vals[0] if sorted_vals[0] != 0 else 0,
        'triaxiality': sorted_vals[1] / sorted_vals[0] if sorted_vals[0] != 0 else 0
    }

def _calculate_coulomb_stress(eigenvals: np.ndarray) -> float:
    """Calculate Coulomb stress"""
    sorted_vals = np.sort(eigenvals)[::-1]
    friction_coeff = 0.6  # Typical friction coefficient
    return sorted_vals[0] - sorted_vals[2] + friction_coeff * (sorted_vals[0] + sorted_vals[2])

def _analyze_mohr_circles(eigenvals: np.ndarray) -> Dict:
    """Analyze Mohr circle characteristics"""
    sorted_vals = np.sort(eigenvals)[::-1]
    return {
        'major_circle_radius': (sorted_vals[0] - sorted_vals[2]) / 2,
        'major_circle_center': (sorted_vals[0] + sorted_vals[2]) / 2,
        'intermediate_circle_radius': (sorted_vals[0] - sorted_vals[1]) / 2,
        'minor_circle_radius': (sorted_vals[1] - sorted_vals[2]) / 2
    }

def _analyze_failure_criteria(eigenvals: np.ndarray) -> Dict:
    """Analyze various failure criteria"""
    sorted_vals = np.sort(eigenvals)[::-1]
    return {
        'von_mises': np.sqrt(0.5 * np.sum([(sorted_vals[i] - sorted_vals[j])**2 
                                         for i in range(3) for j in range(3) if i != j])),
        'tresca': sorted_vals[0] - sorted_vals[2],
        'coulomb_navier': sorted_vals[0] - sorted_vals[2] + 0.6 * (sorted_vals[0] + sorted_vals[2]),
        'griffith': sorted_vals[0] + 3 * sorted_vals[2] if sorted_vals[2] < 0 else sorted_vals[0]
    }

def _calculate_regime_probabilities(eigenvals: np.ndarray) -> Dict:
    """Calculate regime probabilities"""
    sorted_vals = np.sort(eigenvals)[::-1]
    abs_vals = np.abs(sorted_vals)
    
    # Simple heuristic based on which principal stress has largest magnitude
    if abs_vals[2] == np.max(abs_vals):  # σ3 is dominant
        return {'normal': 0.7, 'reverse': 0.2, 'strike_slip': 0.1}
    elif abs_vals[0] == np.max(abs_vals):  # σ1 is dominant  
        return {'normal': 0.1, 'reverse': 0.7, 'strike_slip': 0.2}
    else:  # σ2 is dominant
        return {'normal': 0.2, 'reverse': 0.2, 'strike_slip': 0.6}

def _calculate_optimal_fault_orientations(eigenvals: np.ndarray) -> Dict:
    """Calculate optimal fault orientations for each regime"""
    return {
        'normal': np.array([0.0, 60.0]),      # Strike, dip for normal faults
        'reverse': np.array([0.0, 30.0]),     # Strike, dip for reverse faults  
        'strike_slip': np.array([45.0, 90.0]) # Strike, dip for strike-slip faults
    }

