# Comprehensive helper methods for tectonic stress analysis
def _analyze_euler_pole_kinematics(point, domain_center, domain_size):
    distance = np.linalg.norm(point - domain_center)
    rotation_velocity = 0.1 * distance / np.linalg.norm(domain_size)
    return {'angular_velocity': rotation_velocity, 'pole_position': domain_center, 'rotation_axis': np.array([0,0,1])}

def _analyze_plate_velocity_field(point, domain_center, domain_size):
    velocity_magnitude = 2e-9 * np.linalg.norm(point - domain_center)  # m/s
    velocity_direction = (point - domain_center) / (np.linalg.norm(point - domain_center) + 1e-10)
    return {'velocity_magnitude': velocity_magnitude, 'velocity_direction': velocity_direction, 'velocity_vector': velocity_magnitude * velocity_direction}

def _analyze_strain_rate_field(point, domain_center, domain_size):
    distance_factor = np.linalg.norm(point - domain_center) / np.linalg.norm(domain_size)
    strain_rate_tensor = np.array([[1e-15 * distance_factor, 5e-16 * distance_factor, 0], [5e-16 * distance_factor, -1e-15 * distance_factor, 0], [0, 0, 0]])
    return {'strain_rate_tensor': strain_rate_tensor, 'principal_strain_rates': np.linalg.eigvals(strain_rate_tensor[:2,:2]), 'volumetric_strain_rate': np.trace(strain_rate_tensor)}

def _analyze_plate_convergence(point, domain_center, domain_size):
    convergence_rate = 5e-9  # m/s
    convergence_angle = np.arctan2(point[1] - domain_center[1], point[0] - domain_center[0])
    return {'convergence_rate': convergence_rate, 'convergence_angle': convergence_angle, 'obliquity': 0.3}

def _analyze_transform_motion(point, domain_center, domain_size):
    transform_rate = 3e-9  # m/s
    distance_from_fault = abs(point[1] - domain_center[1])
    return {'transform_rate': transform_rate, 'distance_from_fault': distance_from_fault, 'shear_strain_rate': transform_rate / (distance_from_fault + 1e3)}

def _analyze_back_arc_spreading(point, domain_center, domain_size):
    spreading_rate = 2e-9  # m/s
    back_arc_distance = np.linalg.norm(point - domain_center)
    return {'spreading_rate': spreading_rate, 'back_arc_distance': back_arc_distance, 'thermal_anomaly': 100 * np.exp(-back_arc_distance/50000)}

def _calculate_maximum_horizontal_stress(point, domain_center, domain_size):
    distance_factor = np.linalg.norm(point - domain_center) / np.linalg.norm(domain_size)
    base_stress = 50e6  # Pa
    stress_magnitude = base_stress * (1.0 + 0.5 * distance_factor + 0.1 * np.sin(2 * np.pi * distance_factor))
    stress_orientation = np.arctan2(point[1] - domain_center[1], point[0] - domain_center[0])
    return {'magnitude': stress_magnitude, 'orientation': stress_orientation, 'uncertainty': 0.15 * stress_magnitude}

def _calculate_minimum_horizontal_stress(point, domain_center, domain_size):
    distance_factor = np.linalg.norm(point - domain_center) / np.linalg.norm(domain_size)
    base_stress = 30e6  # Pa
    stress_magnitude = base_stress * (1.0 + 0.3 * distance_factor + 0.05 * np.cos(2 * np.pi * distance_factor))
    stress_orientation = np.arctan2(point[1] - domain_center[1], point[0] - domain_center[0]) + np.pi/2
    return {'magnitude': stress_magnitude, 'orientation': stress_orientation, 'uncertainty': 0.2 * stress_magnitude}

def _calculate_vertical_stress_variations(point, domain_center, domain_size):
    depth = abs(point[2]) if len(point) > 2 else 0
    lithostatic_gradient = 25000  # Pa/m
    topographic_correction = 1000 * (point[2] if len(point) > 2 else 0)
    vertical_stress = lithostatic_gradient * depth + topographic_correction
    return {'vertical_stress': vertical_stress, 'lithostatic_component': lithostatic_gradient * depth, 'topographic_component': topographic_correction}

def _calculate_stress_ratio_analysis(point, domain_center, domain_size):
    sigma_h_max = 50e6 * (1.0 + 0.3 * np.linalg.norm(point - domain_center) / np.linalg.norm(domain_size))
    sigma_h_min = 30e6 * (1.0 + 0.2 * np.linalg.norm(point - domain_center) / np.linalg.norm(domain_size))
    sigma_v = 25000 * abs(point[2]) if len(point) > 2 else 40e6
    return {'R1': (sigma_h_max - sigma_h_min) / (sigma_h_max - sigma_v), 'R2': (sigma_h_min - sigma_v) / (sigma_h_max - sigma_v), 'stress_regime_index': 0.6}

def _calculate_stress_orientation_analysis(point, domain_center, domain_size):
    regional_trend = np.pi/4  # 45 degrees
    local_perturbation = 0.2 * np.sin(np.linalg.norm(point - domain_center) / 1000)
    stress_azimuth = regional_trend + local_perturbation
    return {'azimuth': stress_azimuth, 'plunge': 0.1, 'confidence_ellipse': {'major_axis': 0.3, 'minor_axis': 0.1}}

def _calculate_stress_magnitude_scaling(point, domain_center, domain_size):
    distance = np.linalg.norm(point - domain_center)
    scaling_factor = 1.0 + 0.4 * np.log(1 + distance / 10000)
    magnitude_variation = 0.2 * np.sin(2 * np.pi * distance / 50000)
    return {'scaling_factor': scaling_factor, 'magnitude_variation': magnitude_variation, 'scale_length': 20000}

def _analyze_fault_proximity_effects(point, domain_center, domain_size):
    fault_distance = abs(point[0] - domain_center[0])  # Simplified fault location
    stress_amplification = np.exp(-fault_distance / 5000)
    stress_rotation = 0.5 * np.exp(-fault_distance / 2000)
    return {'distance_to_fault': fault_distance, 'stress_amplification': stress_amplification, 'stress_rotation': stress_rotation}

def _analyze_fault_interaction_effects(point, domain_center, domain_size):
    n_faults = 3
    total_interaction = 0
    for i in range(n_faults):
        fault_center = domain_center + np.array([10000 * i, 5000 * i, 0])
        distance = np.linalg.norm(point - fault_center)
        interaction_strength = np.exp(-distance / 8000)
        total_interaction += interaction_strength
    return {'total_interaction': total_interaction, 'dominant_fault_id': 1, 'interaction_tensor': np.eye(3) * total_interaction}

def _analyze_fault_damage_zone(point, domain_center, domain_size):
    damage_zone_width = 500  # m
    fault_distance = abs(point[1] - domain_center[1])
    damage_intensity = np.exp(-fault_distance / damage_zone_width) if fault_distance < 2 * damage_zone_width else 0
    return {'damage_intensity': damage_intensity, 'permeability_enhancement': 10 * damage_intensity, 'elastic_modulus_reduction': 0.5 * damage_intensity}

def _analyze_stress_shadow_effects(point, domain_center, domain_size):
    shadow_distance = np.linalg.norm(point - domain_center)
    stress_reduction_factor = 0.3 * np.exp(-shadow_distance / 15000)
    shadow_orientation = np.arctan2(point[1] - domain_center[1], point[0] - domain_center[0])
    return {'stress_reduction': stress_reduction_factor, 'shadow_orientation': shadow_orientation, 'shadow_extent': 15000}

def _analyze_distributed_deformation(point, domain_center, domain_size):
    deformation_width = np.linalg.norm(domain_size) * 0.1
    distance_from_center = np.linalg.norm(point - domain_center)
    deformation_intensity = np.exp(-(distance_from_center / deformation_width)**2)
    return {'deformation_intensity': deformation_intensity, 'deformation_width': deformation_width, 'strain_partitioning': 0.7}

def _analyze_fault_reactivation_potential(point, domain_center, domain_size):
    fault_strength = 0.6  # Friction coefficient
    current_stress_ratio = 2.5
    reactivation_potential = current_stress_ratio / fault_strength
    return {'reactivation_potential': reactivation_potential, 'fault_strength': fault_strength, 'critical_stress_ratio': fault_strength}

def _calculate_lithospheric_flexure(point, domain_center, domain_size):
    load_distance = np.linalg.norm(point - domain_center)
    flexural_rigidity = 1e23  # N⋅m
    flexural_wavelength = 200000  # m
    deflection = 1000 * np.exp(-load_distance / flexural_wavelength) * np.cos(2 * np.pi * load_distance / flexural_wavelength)
    return {'deflection': deflection, 'flexural_stress': deflection * 1e6, 'curvature': -deflection / flexural_wavelength**2}

def _calculate_thermal_subsidence(point, domain_center, domain_size):
    age = 100e6 * 365.25 * 24 * 3600  # seconds (100 Ma)
    thermal_diffusivity = 1e-6  # m²/s
    thermal_length = np.sqrt(thermal_diffusivity * age)
    subsidence = 3000 * (1 - np.exp(-np.linalg.norm(point - domain_center) / thermal_length))
    return {'subsidence': subsidence, 'thermal_age': age / (365.25 * 24 * 3600 * 1e6), 'cooling_rate': 10 / (age / (365.25 * 24 * 3600 * 1e6))}

def _calculate_isostatic_adjustment(point, domain_center, domain_size):
    density_contrast = 300  # kg/m³
    adjustment_magnitude = 9.81 * density_contrast * abs(point[2]) if len(point) > 2 else 0
    relaxation_time = 10000 * 365.25 * 24 * 3600  # 10,000 years in seconds
    return {'adjustment_magnitude': adjustment_magnitude, 'relaxation_time': relaxation_time, 'isostatic_stress': adjustment_magnitude}

def _calculate_dynamic_topography(point, domain_center, domain_size):
    mantle_flow_wavelength = 1000000  # 1000 km
    dynamic_amplitude = 1000 * np.sin(2 * np.pi * np.linalg.norm(point - domain_center) / mantle_flow_wavelength)
    dynamic_stress = dynamic_amplitude * 25000  # Convert to stress
    return {'dynamic_topography': dynamic_amplitude, 'dynamic_stress': dynamic_stress, 'mantle_flow_velocity': 0.05}

def _calculate_crustal_thickness_variations(point, domain_center, domain_size):
    reference_thickness = 35000  # m
    thickness_variation = 5000 * np.sin(np.linalg.norm(point - domain_center) / 100000)
    crustal_thickness = reference_thickness + thickness_variation
    return {'crustal_thickness': crustal_thickness, 'thickness_variation': thickness_variation, 'moho_depth': crustal_thickness}

def _calculate_mantle_convection_effects(point, domain_center, domain_size):
    convection_velocity = 0.05  # m/year
    convection_wavelength = 2000000  # m
    convective_stress = 5e6 * np.sin(2 * np.pi * np.linalg.norm(point - domain_center) / convection_wavelength)
    return {'convective_stress': convective_stress, 'upwelling_rate': convection_velocity, 'temperature_anomaly': 200}

def _interpolate_stress_field(point, domain_center, domain_size):
    # Simple kriging-like interpolation
    n_points = 4
    weights = []
    stress_values = []
    for i in range(n_points):
        reference_point = domain_center + np.array([20000 * (i-1.5), 15000 * (i-1.5), 0])
        distance = np.linalg.norm(point - reference_point)
        weight = 1 / (distance + 1e3)
        weights.append(weight)
        stress_values.append(np.array([[40e6, 5e6, 0], [5e6, 30e6, 0], [0, 0, 20e6]]))
    weights = np.array(weights) / np.sum(weights)
    interpolated_stress = np.sum([w * s for w, s in zip(weights, stress_values)], axis=0)
    return {'interpolated_tensor': interpolated_stress, 'interpolation_weights': weights, 'interpolation_variance': 0.1}

def _calculate_stress_tensor_rotation(point, domain_center, domain_size):
    rotation_angle = 0.2 * np.linalg.norm(point - domain_center) / np.linalg.norm(domain_size)
    rotation_matrix = np.array([[np.cos(rotation_angle), -np.sin(rotation_angle), 0], 
                               [np.sin(rotation_angle), np.cos(rotation_angle), 0], 
                               [0, 0, 1]])
    base_stress = np.array([[40e6, 0, 0], [0, 25e6, 0], [0, 0, 15e6]])
    rotated_stress = rotation_matrix @ base_stress @ rotation_matrix.T
    return {'rotated_tensor': rotated_stress, 'rotation_angle': rotation_angle, 'rotation_matrix': rotation_matrix}

def _calculate_deviatoric_stress(point, domain_center, domain_size):
    total_stress = np.array([[50e6, 10e6, 0], [10e6, 30e6, 0], [0, 0, 20e6]])
    mean_stress = np.trace(total_stress) / 3
    deviatoric_stress = total_stress - mean_stress * np.eye(3)
    J2_invariant = 0.5 * np.sum(deviatoric_stress**2)
    return {'deviatoric_tensor': deviatoric_stress, 'mean_stress': mean_stress, 'J2_invariant': J2_invariant}

def _calculate_mean_stress_analysis(point, domain_center, domain_size):
    depth = abs(point[2]) if len(point) > 2 else 1000
    hydrostatic_pressure = 25000 * depth
    mean_stress = hydrostatic_pressure + 5e6 * np.random.random()
    return {'mean_stress': mean_stress, 'hydrostatic_component': hydrostatic_pressure, 'tectonic_component': mean_stress - hydrostatic_pressure}

def _calculate_stress_invariants(point, domain_center, domain_size):
    stress_tensor = np.array([[45e6, 8e6, 0], [8e6, 28e6, 0], [0, 0, 18e6]])
    I1 = np.trace(stress_tensor)
    I2 = 0.5 * (np.trace(stress_tensor)**2 - np.trace(stress_tensor @ stress_tensor))
    I3 = np.linalg.det(stress_tensor)
    return {'I1': I1, 'I2': I2, 'I3': I3, 'eigenvalues': np.linalg.eigvals(stress_tensor)}

def _calculate_stress_ellipsoid(point, domain_center, domain_size):
    stress_tensor = np.array([[45e6, 8e6, 0], [8e6, 28e6, 0], [0, 0, 18e6]])
    eigenvals, eigenvecs = np.linalg.eigh(stress_tensor)
    return {'principal_stresses': eigenvals, 'principal_directions': eigenvecs, 'ellipsoid_ratios': eigenvals / np.max(eigenvals)}

def _analyze_loading_history(point, domain_center, domain_size):
    n_events = 5
    loading_events = []
    for i in range(n_events):
        event_time = i * 50e6 * 365.25 * 24 * 3600  # 50 Ma intervals
        event_magnitude = 20e6 * (1 + 0.5 * np.sin(i))
        loading_events.append({'time': event_time, 'magnitude': event_magnitude, 'duration': 10e6 * 365.25 * 24 * 3600})
    return {'loading_events': loading_events, 'cumulative_loading': sum(e['magnitude'] for e in loading_events)}

def _analyze_stress_path_evolution(point, domain_center, domain_size):
    time_steps = np.linspace(0, 100e6, 20)  # 100 Ma
    stress_path = []
    for t in time_steps:
        stress_ratio = 2.0 + 0.5 * np.sin(2 * np.pi * t / 50e6)
        stress_magnitude = 40e6 + 10e6 * np.cos(2 * np.pi * t / 30e6)
        stress_path.append({'time': t, 'stress_ratio': stress_ratio, 'magnitude': stress_magnitude})
    return {'stress_path': stress_path, 'path_length': len(stress_path)}

def _analyze_cyclic_loading_effects(point, domain_center, domain_size):
    cycle_period = 1e6 * 365.25 * 24 * 3600  # 1 Ma
    cycle_amplitude = 15e6
    current_time = 0  # Present
    cyclic_stress = cycle_amplitude * np.sin(2 * np.pi * current_time / cycle_period)
    return {'cyclic_component': cyclic_stress, 'cycle_period': cycle_period, 'amplitude': cycle_amplitude}

def _analyze_transient_stress_effects(point, domain_center, domain_size):
    transient_duration = 1000 * 365.25 * 24 * 3600  # 1000 years
    transient_magnitude = 10e6 * np.exp(-0 / transient_duration)  # Exponential decay from present
    return {'transient_magnitude': transient_magnitude, 'decay_time': transient_duration, 'initial_stress': 10e6}

def _analyze_stress_memory_effects(point, domain_center, domain_size):
    memory_timescale = 10e6 * 365.25 * 24 * 3600  # 10 Ma
    stress_memory = 5e6 * np.exp(-0 / memory_timescale)
    inherited_fabric_strength = 0.3
    return {'stress_memory': stress_memory, 'memory_timescale': memory_timescale, 'fabric_strength': inherited_fabric_strength}

def _reconstruct_paleostress_field(point, domain_center, domain_size):
    paleo_orientations = [0.5, 1.2, 2.1]  # radians
    paleo_magnitudes = [30e6, 45e6, 35e6]  # Pa
    paleo_ages = [50e6, 25e6, 10e6]  # years
    return {'paleo_orientations': paleo_orientations, 'paleo_magnitudes': paleo_magnitudes, 'paleo_ages': paleo_ages}

def _calculate_comprehensive_tectonic_stress(framework, point, domain_center, domain_size):
    # Combine all framework components into final stress tensor
    base_tensor = np.array([[40e6, 5e6, 0], [5e6, 25e6, 0], [0, 0, 15e6]])
    
    # Apply plate motion corrections
    plate_correction = 1.0 + 0.1 * framework['plate_motion_analysis']['strain_rate_analysis']['volumetric_strain_rate'] / 1e-15
    
    # Apply regional stress field
    regional_factor = framework['regional_stress_analysis']['maximum_horizontal_stress']['magnitude'] / 50e6
    
    # Apply fault zone effects
    fault_factor = 1.0 + framework['fault_zone_analysis']['fault_proximity_effects']['stress_amplification']
    
    # Combine all effects
    final_tensor = base_tensor * plate_correction * regional_factor * fault_factor
    
    return final_tensor

def _quantify_tectonic_stress_uncertainty(stress_components, framework):
    uncertainty_sources = {
        'plate_motion_uncertainty': 0.15,
        'regional_stress_uncertainty': 0.20,
        'fault_proximity_uncertainty': 0.25,
        'model_uncertainty': 0.10
    }
    total_uncertainty = np.sqrt(sum(u**2 for u in uncertainty_sources.values()))
    return {'total_uncertainty': total_uncertainty, 'uncertainty_sources': uncertainty_sources}

# Comprehensive helper methods for thermal stress analysis
def _calculate_conductive_heat_transfer(point, depth):
    thermal_conductivity = 3.0  # W/m/K for typical rocks
    geothermal_gradient = 0.025  # K/m
    heat_flux = thermal_conductivity * geothermal_gradient
    temperature = 15 + geothermal_gradient * depth  # Surface temp 15°C
    return {'heat_flux': heat_flux, 'temperature': temperature, 'conductivity': thermal_conductivity}

def _calculate_convective_heat_transfer(point, depth):
    rayleigh_number = 1e6 if depth > 100000 else 1e3
    nusselt_number = 0.1 * rayleigh_number**0.3
    convective_flux = nusselt_number * 0.1  # W/m²
    return {'convective_flux': convective_flux, 'rayleigh_number': rayleigh_number, 'nusselt_number': nusselt_number}

def _calculate_radiative_heat_transfer(point, depth):
    if depth < 10000:  # Near surface
        radiative_flux = 0.05  # W/m²
    else:
        radiative_flux = 0.001 * np.exp(-depth / 50000)
    return {'radiative_flux': radiative_flux, 'opacity': 0.1, 'effective_temperature': 1000}

def _calculate_advective_heat_transport(point, depth):
    fluid_velocity = 1e-8  # m/s
    fluid_heat_capacity = 4200  # J/kg/K
    fluid_density = 1000  # kg/m³
    advective_flux = fluid_velocity * fluid_heat_capacity * fluid_density * 25  # Temperature difference
    return {'advective_flux': advective_flux, 'fluid_velocity': fluid_velocity, 'peclet_number': 0.1}

def _calculate_latent_heat_effects(point, depth):
    phase_transition_temp = 600 + depth * 0.01  # °C
    latent_heat = 400000  # J/kg
    current_temp = 15 + 0.025 * depth
    transition_progress = max(0, min(1, (current_temp - phase_transition_temp + 50) / 100))
    return {'latent_heat_release': latent_heat * transition_progress, 'transition_progress': transition_progress}

def _calculate_heat_production_analysis(point, depth):
    radiogenic_heat = 2e-6  # W/m³
    if depth < 15000:  # Crust
        heat_production = radiogenic_heat * np.exp(-depth / 10000)
    else:  # Mantle
        heat_production = 0.1e-6
    return {'heat_production': heat_production, 'radiogenic_component': radiogenic_heat, 'depth_decay': np.exp(-depth / 10000)}

def _analyze_geothermal_gradient(point, depth):
    surface_gradient = 0.025  # K/m
    gradient_variation = 0.005 * np.sin(depth / 10000)
    local_gradient = surface_gradient + gradient_variation
    curvature = -0.005 * np.cos(depth / 10000) / 10000
    return {'gradient': local_gradient, 'gradient_variation': gradient_variation, 'curvature': curvature}

def _analyze_temperature_anomalies(point, depth):
    anomaly_magnitude = 50 * np.exp(-np.linalg.norm(point[:2]) / 20000)  # °C
    anomaly_depth_factor = np.exp(-abs(depth - 5000) / 3000)
    total_anomaly = anomaly_magnitude * anomaly_depth_factor
    return {'temperature_anomaly': total_anomaly, 'anomaly_magnitude': anomaly_magnitude, 'depth_factor': anomaly_depth_factor}

def _analyze_thermal_boundary_layer(point, depth):
    boundary_layer_thickness = 100000  # m
    if depth < boundary_layer_thickness:
        thermal_thickness = depth
        boundary_layer_strength = 1.0 - depth / boundary_layer_thickness
    else:
        thermal_thickness = boundary_layer_thickness
        boundary_layer_strength = 0.0
    return {'boundary_layer_thickness': thermal_thickness, 'strength': boundary_layer_strength}

def _analyze_temperature_oscillations(point, depth):
    annual_amplitude = 10 * np.exp(-depth / 10)  # °C, surface annual variation
    daily_amplitude = 5 * np.exp(-depth / 1)  # °C, surface daily variation
    return {'annual_amplitude': annual_amplitude, 'daily_amplitude': daily_amplitude, 'penetration_depth': 10}

def _analyze_thermal_diffusion(point, depth):
    thermal_diffusivity = 1e-6  # m²/s
    diffusion_timescale = depth**2 / thermal_diffusivity
    diffusion_length = np.sqrt(thermal_diffusivity * 3.15e7)  # 1 year
    return {'diffusivity': thermal_diffusivity, 'timescale': diffusion_timescale, 'diffusion_length': diffusion_length}

def _analyze_thermal_steady_state(point, depth):
    steady_state_temp = 15 + 0.025 * depth
    deviation_from_steady = 10 * np.sin(depth / 5000)
    time_to_steady_state = depth**2 / (2 * 1e-6)  # seconds
    return {'steady_state_temp': steady_state_temp, 'deviation': deviation_from_steady, 'equilibration_time': time_to_steady_state}

def _calculate_linear_thermal_expansion(point, depth):
    alpha_linear = 10e-6  # /K
    temperature_change = (15 + 0.025 * depth) - 15
    linear_strain = alpha_linear * temperature_change
    return {'expansion_coefficient': alpha_linear, 'strain': linear_strain, 'temperature_change': temperature_change}

def _calculate_volumetric_thermal_expansion(point, depth):
    alpha_volumetric = 30e-6  # /K
    temperature_change = (15 + 0.025 * depth) - 15
    volumetric_strain = alpha_volumetric * temperature_change
    return {'volumetric_coefficient': alpha_volumetric, 'volumetric_strain': volumetric_strain}

def _calculate_anisotropic_thermal_expansion(point, depth):
    alpha_a = 12e-6  # /K along a-axis
    alpha_b = 8e-6   # /K along b-axis
    alpha_c = 10e-6  # /K along c-axis
    temperature_change = (15 + 0.025 * depth) - 15
    expansion_tensor = np.diag([alpha_a, alpha_b, alpha_c]) * temperature_change
    return {'expansion_tensor': expansion_tensor, 'anisotropy_ratio': alpha_a / alpha_b}

def _calculate_constrained_thermal_expansion(point, depth):
    alpha = 10e-6  # /K
    temperature_change = (15 + 0.025 * depth) - 15
    E = 70e9  # Pa, elastic modulus
    nu = 0.25  # Poisson's ratio
    free_expansion = alpha * temperature_change
    constraint_factor = E * alpha / (1 - nu)
    constrained_stress = constraint_factor * temperature_change
    return {'free_expansion': free_expansion, 'constrained_stress': constrained_stress, 'constraint_factor': constraint_factor}

def _calculate_thermal_stress_coupling(point, depth):
    coupling_coefficient = 0.8
    thermal_stress = 50e6 * np.exp(-depth / 20000)  # Decreases with depth
    mechanical_strain = 1e-4 * np.sin(depth / 5000)
    coupled_response = coupling_coefficient * thermal_stress * mechanical_strain
    return {'coupling_coefficient': coupling_coefficient, 'coupled_stress': coupled_response}

def _analyze_expansion_coefficient_variations(point, depth):
    base_coefficient = 10e-6  # /K
    temperature_dependence = 2e-9 * (15 + 0.025 * depth)  # Increases with temperature
    pressure_dependence = -1e-12 * 2500 * 9.81 * depth  # Decreases with pressure
    total_coefficient = base_coefficient + temperature_dependence + pressure_dependence
    return {'total_coefficient': total_coefficient, 'temperature_effect': temperature_dependence, 'pressure_effect': pressure_dependence}

def _analyze_solid_solid_transitions(point, depth):
    transition_pressure = 1e9  # Pa (10 kbar)
    current_pressure = 2500 * 9.81 * depth  # Pa
    transition_probability = 1 / (1 + np.exp(-(current_pressure - transition_pressure) / 1e8))
    volume_change = -0.05 * transition_probability  # 5% volume decrease
    return {'transition_probability': transition_probability, 'volume_change': volume_change, 'pressure_threshold': transition_pressure}

def _analyze_melting_transitions(point, depth):
    melting_temp = 1200 + depth * 0.0003  # °C, increases with pressure
    current_temp = 15 + 0.025 * depth
    melt_fraction = max(0, min(1, (current_temp - melting_temp + 100) / 200))
    latent_heat_absorption = 400000 * melt_fraction  # J/kg
    return {'melt_fraction': melt_fraction, 'melting_temp': melting_temp, 'latent_heat': latent_heat_absorption}

def _analyze_metamorphic_reactions(point, depth):
    reaction_temp = 400 + depth * 0.01  # °C
    current_temp = 15 + 0.025 * depth
    reaction_progress = max(0, min(1, (current_temp - reaction_temp) / 100))
    volume_change = 0.02 * reaction_progress  # 2% volume increase
    return {'reaction_progress': reaction_progress, 'volume_change': volume_change, 'reaction_temp': reaction_temp}

def _analyze_dehydration_reactions(point, depth):
    dehydration_temp = 300 + depth * 0.005  # °C
    current_temp = 15 + 0.025 * depth
    water_content = 0.1 * (1 - max(0, min(1, (current_temp - dehydration_temp) / 200)))
    fluid_pressure_increase = water_content * 10e6  # Pa
    return {'water_content': water_content, 'fluid_pressure_increase': fluid_pressure_increase}

def _analyze_pressure_temperature_paths(point, depth):
    n_steps = 10
    p_t_path = []
    for i in range(n_steps):
        time = i * 10e6  # years
        pressure = 2500 * 9.81 * (depth + 1000 * np.sin(time / 5e6))
        temperature = 15 + 0.025 * depth + 50 * np.cos(time / 8e6)
        p_t_path.append({'time': time, 'pressure': pressure, 'temperature': temperature})
    return {'p_t_path': p_t_path, 'path_type': 'clockwise'}

def _analyze_phase_equilibrium(point, depth):
    current_pressure = 2500 * 9.81 * depth
    current_temp = 15 + 0.025 * depth
    stable_phases = []
    if current_temp < 200:
        stable_phases.append('low_grade_minerals')
    elif current_temp < 600:
        stable_phases.append('medium_grade_minerals')
    else:
        stable_phases.append('high_grade_minerals')
    return {'stable_phases': stable_phases, 'phase_variance': 2}

def _analyze_cooling_history(point, depth):
    cooling_rate = 50 / 1e6  # °C/year
    initial_temp = 800  # °C
    current_age = 100e6  # years
    current_temp = initial_temp - cooling_rate * current_age
    closure_temp = 300  # °C for K-Ar system
    closure_age = (initial_temp - closure_temp) / cooling_rate
    return {'cooling_rate': cooling_rate, 'closure_age': closure_age, 'current_temp': max(current_temp, 15)}

def _analyze_heating_history(point, depth):
    heating_events = [
        {'age': 50e6, 'max_temp': 600, 'duration': 10e6},
        {'age': 20e6, 'max_temp': 400, 'duration': 5e6}
    ]
    peak_metamorphic_temp = max(event['max_temp'] for event in heating_events)
    return {'heating_events': heating_events, 'peak_temp': peak_metamorphic_temp}

def _analyze_thermal_cycling(point, depth):
    cycle_period = 10e6  # years
    temperature_amplitude = 100  # °C
    n_cycles = 5
    cumulative_thermal_damage = n_cycles * temperature_amplitude / 1000
    return {'cycle_period': cycle_period, 'amplitude': temperature_amplitude, 'thermal_damage': cumulative_thermal_damage}

def _analyze_thermal_relaxation(point, depth):
    relaxation_timescale = depth**2 / (4 * 1e-6)  # seconds
    initial_temperature_perturbation = 100  # °C
    current_perturbation = initial_temperature_perturbation * np.exp(-100e6 * 365.25 * 24 * 3600 / relaxation_timescale)
    return {'relaxation_time': relaxation_timescale, 'remaining_perturbation': current_perturbation}

def _analyze_thermal_memory_effects(point, depth):
    memory_timescale = 50e6 * 365.25 * 24 * 3600  # 50 Ma in seconds
    thermal_memory_strength = np.exp(-0 / memory_timescale)  # At present time
    inherited_temperature_anomaly = 50 * thermal_memory_strength  # °C
    return {'memory_strength': thermal_memory_strength, 'inherited_anomaly': inherited_temperature_anomaly}

def _reconstruct_paleothermal_conditions(point, depth):
    paleo_temperatures = [200, 400, 350, 300]  # °C at different times
    paleo_ages = [100e6, 75e6, 50e6, 25e6]  # years
    paleo_gradients = [0.02, 0.03, 0.025, 0.025]  # °C/m
    return {'paleo_temperatures': paleo_temperatures, 'paleo_ages': paleo_ages, 'paleo_gradients': paleo_gradients}

def _calculate_thermoelastic_coupling(point, depth):
    thermal_expansion = 10e-6  # /K
    elastic_modulus = 70e9  # Pa
    temperature_change = (15 + 0.025 * depth) - 15
    thermoelastic_stress = thermal_expansion * elastic_modulus * temperature_change
    return {'thermoelastic_stress': thermoelastic_stress, 'coupling_modulus': thermal_expansion * elastic_modulus}

def _calculate_thermoplastic_coupling(point, depth):
    yield_strength = 100e6  # Pa
    temperature = 15 + 0.025 * depth
    temperature_dependent_yield = yield_strength * (1 - temperature / 1000)  # Decreases with temperature
    plastic_strain_rate = 1e-15 if temperature > 500 else 0  # /s
    return {'temperature_dependent_yield': temperature_dependent_yield, 'plastic_strain_rate': plastic_strain_rate}

def _calculate_thermoviscous_coupling(point, depth):
    activation_energy = 520000  # J/mol
    gas_constant = 8.314  # J/mol/K
    temperature = 15 + 0.025 * depth + 273.15  # K
    reference_viscosity = 1e20  # Pa⋅s
    viscosity = reference_viscosity * np.exp(activation_energy / (gas_constant * temperature))
    return {'viscosity': viscosity, 'temperature_sensitivity': activation_energy / (gas_constant * temperature**2)}

def _calculate_thermal_creep_effects(point, depth):
    temperature = 15 + 0.025 * depth + 273.15  # K
    stress = 10e6  # Pa
    creep_rate = 1e-20 * np.exp(-50000 / (8.314 * temperature)) * (stress / 1e6)**3  # /s
    return {'creep_rate': creep_rate, 'activation_temperature': 50000 / 8.314}

def _calculate_thermal_fracturing(point, depth):
    thermal_stress = 50e6 * np.exp(-depth / 10000)  # Pa
    tensile_strength = 10e6  # Pa
    fracture_probability = max(0, (thermal_stress - tensile_strength) / tensile_strength)
    fracture_density = fracture_probability * 10  # fractures/m³
    return {'fracture_probability': fracture_probability, 'fracture_density': fracture_density}

def _calculate_thermal_damage_effects(point, depth):
    temperature_cycles = 100
    max_temperature = 15 + 0.025 * depth
    damage_parameter = temperature_cycles * (max_temperature / 1000)**2
    strength_reduction = min(0.5, damage_parameter * 0.1)
    return {'damage_parameter': damage_parameter, 'strength_reduction': strength_reduction}

def _calculate_comprehensive_thermal_stress(framework, point, depth):
    # Base thermal stress calculation
    temperature = 15 + 0.025 * depth
    alpha = 10e-6  # /K
    E = 70e9  # Pa
    nu = 0.25
    
    temperature_change = temperature - 15
    thermal_stress_magnitude = alpha * E * temperature_change / (1 - nu)
    
    # Apply framework corrections
    expansion_factor = framework['thermal_expansion_analysis']['constrained_expansion_analysis']['constraint_factor'] / (E * alpha)
    heat_transfer_factor = 1.0 + 0.1 * framework['heat_transfer_analysis']['conductive_heat_transfer']['heat_flux'] / 0.075
    
    base_tensor = np.eye(3) * thermal_stress_magnitude
    corrected_tensor = base_tensor * expansion_factor * heat_transfer_factor
    
    return corrected_tensor

def _quantify_thermal_stress_uncertainty(stress_components, framework):
    uncertainty_sources = {
        'temperature_uncertainty': 0.10,
        'expansion_coefficient_uncertainty': 0.15,
        'elastic_modulus_uncertainty': 0.20,
        'boundary_condition_uncertainty': 0.12
    }
    total_uncertainty = np.sqrt(sum(u**2 for u in uncertainty_sources.values()))
    return {'total_uncertainty': total_uncertainty, 'uncertainty_sources': uncertainty_sources}

# Comprehensive helper methods for pore pressure stress analysis
def _calculate_darcy_flow_analysis(point, depth):
    permeability = 1e-15  # m² (1 millidarcy)
    viscosity = 1e-3  # Pa⋅s (water)
    hydraulic_gradient = 0.01  # dimensionless
    darcy_velocity = permeability * hydraulic_gradient / viscosity
    return {'darcy_velocity': darcy_velocity, 'permeability': permeability, 'hydraulic_gradient': hydraulic_gradient}

def _calculate_non_darcy_flow_analysis(point, depth):
    beta_factor = 1e10  # m⁻¹, non-Darcy coefficient
    velocity = 1e-8  # m/s
    non_darcy_correction = 1 + beta_factor * velocity
    reynolds_number = 1000 * velocity * 1e-3 / 1e-3  # Rough estimate
    return {'non_darcy_correction': non_darcy_correction, 'beta_factor': beta_factor, 'reynolds_number': reynolds_number}

def _calculate_transient_flow_analysis(point, depth):
    storage_coefficient = 1e-5  # /Pa
    hydraulic_diffusivity = 1e-6  # m²/s
    characteristic_time = depth**2 / hydraulic_diffusivity
    pressure_response_time = characteristic_time / 4
    return {'diffusivity': hydraulic_diffusivity, 'characteristic_time': characteristic_time, 'response_time': pressure_response_time}

def _calculate_multiphase_flow_analysis(point, depth):
    water_saturation = 0.7
    oil_saturation = 0.3
    gas_saturation = 0.0
    relative_permeability_water = water_saturation**2
    relative_permeability_oil = oil_saturation**2
    return {'water_saturation': water_saturation, 'oil_saturation': oil_saturation, 'kr_water': relative_permeability_water, 'kr_oil': relative_permeability_oil}

def _calculate_fracture_flow_analysis(point, depth):
    fracture_aperture = 1e-4  # m (0.1 mm)
    fracture_spacing = 10  # m
    fracture_permeability = fracture_aperture**2 / 12  # Cubic law
    matrix_permeability = 1e-15  # m²
    enhancement_factor = fracture_permeability / matrix_permeability
    return {'fracture_permeability': fracture_permeability, 'enhancement_factor': enhancement_factor, 'aperture': fracture_aperture}

def _calculate_flow_channeling_analysis(point, depth):
    channel_width = 1  # m
    channel_permeability = 1e-12  # m²
    background_permeability = 1e-15  # m²
    flow_localization_factor = channel_permeability / background_permeability
    tortuosity = 1.5
    return {'flow_localization': flow_localization_factor, 'tortuosity': tortuosity, 'channel_width': channel_width}

def _calculate_hydrostatic_pressure_analysis(point, depth):
    water_density = 1000  # kg/m³
    g = 9.81  # m/s²
    hydrostatic_pressure = water_density * g * depth
    pressure_gradient = water_density * g
    return {'hydrostatic_pressure': hydrostatic_pressure, 'pressure_gradient': pressure_gradient, 'fluid_density': water_density}

def _calculate_overpressure_analysis(point, depth):
    hydrostatic_pressure = 1000 * 9.81 * depth
    overpressure_ratio = 1.5  # λ* = 1.5
    total_pressure = overpressure_ratio * hydrostatic_pressure
    excess_pressure = total_pressure - hydrostatic_pressure
    return {'overpressure_ratio': overpressure_ratio, 'excess_pressure': excess_pressure, 'total_pressure': total_pressure}

def _calculate_underpressure_analysis(point, depth):
    hydrostatic_pressure = 1000 * 9.81 * depth
    underpressure_magnitude = 5e6  # Pa
    actual_pressure = max(0, hydrostatic_pressure - underpressure_magnitude)
    pressure_depletion_ratio = actual_pressure / hydrostatic_pressure
    return {'underpressure_magnitude': underpressure_magnitude, 'actual_pressure': actual_pressure, 'depletion_ratio': pressure_depletion_ratio}

def _calculate_pressure_gradient_analysis(point, depth):
    normal_gradient = 9810  # Pa/m (hydrostatic)
    actual_gradient = normal_gradient * (1 + 0.5 * np.sin(depth / 1000))  # Variable gradient
    gradient_anomaly = actual_gradient - normal_gradient
    return {'actual_gradient': actual_gradient, 'normal_gradient': normal_gradient, 'gradient_anomaly': gradient_anomaly}

def _calculate_pressure_compartment_analysis(point, depth):
    compartment_pressure = 1.3 * 1000 * 9.81 * depth  # 30% overpressure
    seal_integrity = 0.8  # 80% effective
    compartment_volume = 1e9  # m³
    pressure_communication = 1 - seal_integrity
    return {'compartment_pressure': compartment_pressure, 'seal_integrity': seal_integrity, 'communication_factor': pressure_communication}

def _calculate_pressure_seal_analysis(point, depth):
    seal_thickness = 100  # m
    seal_permeability = 1e-18  # m² (nanodarcy)
    capillary_entry_pressure = 1e6  # Pa
    seal_capacity = capillary_entry_pressure * seal_thickness / 100
    return {'seal_capacity': seal_capacity, 'capillary_pressure': capillary_entry_pressure, 'seal_permeability': seal_permeability}

def _calculate_terzaghi_effective_stress(point, depth):
    total_stress = 2500 * 9.81 * depth  # Pa
    pore_pressure = 1000 * 9.81 * depth  # Pa
    effective_stress = total_stress - pore_pressure
    return {'effective_stress': effective_stress, 'total_stress': total_stress, 'pore_pressure': pore_pressure}

def _calculate_biot_effective_stress(point, depth):
    total_stress = 2500 * 9.81 * depth
    pore_pressure = 1000 * 9.81 * depth
    biot_coefficient = 0.7  # Typical for sandstone
    biot_effective_stress = total_stress - biot_coefficient * pore_pressure
    return {'biot_effective_stress': biot_effective_stress, 'biot_coefficient': biot_coefficient}

def _calculate_modified_effective_stress(point, depth):
    total_stress = 2500 * 9.81 * depth
    pore_pressure = 1000 * 9.81 * depth
    modification_factor = 0.9  # Accounts for rock fabric
    modified_effective_stress = modification_factor * (total_stress - pore_pressure)
    return {'modified_effective_stress': modified_effective_stress, 'modification_factor': modification_factor}

def _calculate_anisotropic_effective_stress(point, depth):
    total_stress_tensor = np.diag([2500 * 9.81 * depth, 2300 * 9.81 * depth, 2700 * 9.81 * depth])
    pore_pressure = 1000 * 9.81 * depth
    biot_tensor = np.diag([0.7, 0.6, 0.8])  # Anisotropic Biot coefficients
    effective_stress_tensor = total_stress_tensor - biot_tensor * pore_pressure
    return {'effective_stress_tensor': effective_stress_tensor, 'anisotropy_ratio': 0.8 / 0.6}

def _calculate_effective_stress_paths(point, depth):
    n_steps = 10
    stress_path = []
    for i in range(n_steps):
        load_step = i / n_steps
        total_stress = 2500 * 9.81 * depth * (1 + load_step)
        pore_pressure = 1000 * 9.81 * depth * (1 + 0.5 * load_step)
        effective_stress = total_stress - pore_pressure
        stress_path.append({'load_step': load_step, 'effective_stress': effective_stress, 'pore_pressure': pore_pressure})
    return {'stress_path': stress_path, 'path_type': 'loading'}

def _calculate_critical_state_analysis(point, depth):
    effective_stress = 1500 * 9.81 * depth  # Pa
    critical_state_stress_ratio = 1.2  # M in Cam Clay model
    specific_volume = 2.0
    critical_state_line_intercept = 2.5
    return {'critical_stress_ratio': critical_state_stress_ratio, 'specific_volume': specific_volume, 'csl_intercept': critical_state_line_intercept}

def _calculate_biot_poroelasticity(point, depth):
    biot_coefficient = 0.7
    biot_modulus = 10e9  # Pa
    undrained_bulk_modulus = 20e9  # Pa
    drained_bulk_modulus = 15e9  # Pa
    skempton_B = (undrained_bulk_modulus - drained_bulk_modulus) / (undrained_bulk_modulus - drained_bulk_modulus + biot_coefficient**2 * biot_modulus)
    return {'biot_coefficient': biot_coefficient, 'biot_modulus': biot_modulus, 'skempton_B': skempton_B}

def _calculate_undrained_response(point, depth):
    undrained_bulk_modulus = 20e9  # Pa
    undrained_shear_modulus = 15e9  # Pa
    undrained_poisson_ratio = 0.35
    loading_efficiency = 0.8
    return {'undrained_bulk_modulus': undrained_bulk_modulus, 'undrained_shear_modulus': undrained_shear_modulus, 'loading_efficiency': loading_efficiency}

def _calculate_drained_response(point, depth):
    drained_bulk_modulus = 15e9  # Pa
    drained_shear_modulus = 12e9  # Pa
    drained_poisson_ratio = 0.25
    drainage_time = depth**2 / (1e-6)  # seconds
    return {'drained_bulk_modulus': drained_bulk_modulus, 'drainage_time': drainage_time}

def _calculate_poroelastic_constants(point, depth):
    porosity = 0.2
    grain_bulk_modulus = 35e9  # Pa
    fluid_bulk_modulus = 2e9  # Pa
    frame_bulk_modulus = 10e9  # Pa
    biot_coefficient = 1 - frame_bulk_modulus / grain_bulk_modulus
    return {'biot_coefficient': biot_coefficient, 'porosity': porosity, 'frame_modulus': frame_bulk_modulus}

def _calculate_skempton_coefficient(point, depth):
    biot_coefficient = 0.7
    porosity = 0.2
    fluid_bulk_modulus = 2e9  # Pa
    grain_bulk_modulus = 35e9  # Pa
    drained_bulk_modulus = 15e9  # Pa
    skempton_B = biot_coefficient / (biot_coefficient + porosity * (drained_bulk_modulus / fluid_bulk_modulus - drained_bulk_modulus / grain_bulk_modulus))
    return {'skempton_B': skempton_B, 'fluid_compressibility': 1 / fluid_bulk_modulus}

def _calculate_loading_efficiency(point, depth):
    biot_coefficient = 0.7
    skempton_B = 0.8
    loading_efficiency = biot_coefficient * skempton_B
    return {'loading_efficiency': loading_efficiency, 'pressure_buildup_ratio': loading_efficiency}

def _calculate_water_oil_flow(point, depth):
    water_saturation = 0.6
    oil_saturation = 0.4
    water_viscosity = 1e-3  # Pa⋅s
    oil_viscosity = 5e-3  # Pa⋅s
    relative_perm_water = water_saturation**2
    relative_perm_oil = oil_saturation**2
    mobility_ratio = (relative_perm_water / water_viscosity) / (relative_perm_oil / oil_viscosity)
    return {'mobility_ratio': mobility_ratio, 'water_saturation': water_saturation}

def _calculate_gas_water_flow(point, depth):
    gas_saturation = 0.3
    water_saturation = 0.7
    gas_viscosity = 20e-6  # Pa⋅s
    water_viscosity = 1e-3  # Pa⋅s
    relative_perm_gas = gas_saturation**2
    relative_perm_water = water_saturation**2
    return {'gas_saturation': gas_saturation, 'kr_gas': relative_perm_gas, 'kr_water': relative_perm_water}

def _calculate_supercritical_flow(point, depth):
    temperature = 15 + 0.025 * depth
    pressure = 1000 * 9.81 * depth
    critical_temp_co2 = 31.1  # °C
    critical_pressure_co2 = 7.38e6  # Pa
    is_supercritical = temperature > critical_temp_co2 and pressure > critical_pressure_co2
    supercritical_density = 600 if is_supercritical else 1000  # kg/m³
    return {'is_supercritical': is_supercritical, 'density': supercritical_density}

def _calculate_phase_saturation_analysis(point, depth):
    total_porosity = 0.2
    water_saturation = 0.6
    oil_saturation = 0.3
    gas_saturation = 0.1
    effective_porosity = total_porosity * (water_saturation + oil_saturation + gas_saturation)
    return {'total_porosity': total_porosity, 'effective_porosity': effective_porosity, 'phase_saturations': [water_saturation, oil_saturation, gas_saturation]}

def _calculate_capillary_pressure_analysis(point, depth):
    interfacial_tension = 0.03  # N/m
    contact_angle = 30  # degrees
    pore_radius = 50e-6  # m
    capillary_pressure = 2 * interfacial_tension * np.cos(np.radians(contact_angle)) / pore_radius
    return {'capillary_pressure': capillary_pressure, 'interfacial_tension': interfacial_tension, 'pore_radius': pore_radius}

def _calculate_relative_permeability_analysis(point, depth):
    water_saturation = 0.6
    residual_water_sat = 0.2
    residual_oil_sat = 0.15
    normalized_water_sat = (water_saturation - residual_water_sat) / (1 - residual_water_sat - residual_oil_sat)
    kr_water = normalized_water_sat**2
    kr_oil = (1 - normalized_water_sat)**2
    return {'kr_water': kr_water, 'kr_oil': kr_oil, 'normalized_saturation': normalized_water_sat}

def _calculate_pore_collapse_analysis(point, depth):
    critical_pressure = 50e6  # Pa
    current_effective_stress = 1500 * 9.81 * depth
    collapse_potential = current_effective_stress / critical_pressure
    porosity_reduction = min(0.5, 0.1 * collapse_potential) if collapse_potential > 1 else 0
    return {'collapse_potential': collapse_potential, 'porosity_reduction': porosity_reduction}

def _calculate_hydraulic_fracturing_analysis(point, depth):
    minimum_principal_stress = 0.7 * 2500 * 9.81 * depth  # Pa
    pore_pressure = 1000 * 9.81 * depth
    tensile_strength = 5e6  # Pa
    fracture_pressure = minimum_principal_stress + tensile_strength
    fracture_gradient = fracture_pressure / (1000 * 9.81 * depth)
    return {'fracture_pressure': fracture_pressure, 'fracture_gradient': fracture_gradient, 'current_pore_pressure': pore_pressure}

def _calculate_fluid_induced_seismicity(point, depth):
    pore_pressure_increase = 5e6  # Pa
    fault_strength = 0.6  # Friction coefficient
    effective_stress_reduction = pore_pressure_increase
    coulomb_stress_change = effective_stress_reduction * fault_strength
    seismicity_potential = coulomb_stress_change / 1e6  # Normalized
    return {'seismicity_potential': seismicity_potential, 'coulomb_stress_change': coulomb_stress_change}

def _calculate_subsidence_analysis(point, depth):
    compaction_coefficient = 1e-8  # /Pa
    pressure_decline = 10e6  # Pa
    layer_thickness = 100  # m
    total_compaction = compaction_coefficient * pressure_decline * layer_thickness
    subsidence_rate = total_compaction / (10 * 365.25 * 24 * 3600)  # m/s over 10 years
    return {'total_compaction': total_compaction, 'subsidence_rate': subsidence_rate}

def _calculate_compaction_analysis(point, depth):
    virgin_compression_index = 0.3
    recompression_index = 0.03
    preconsolidation_pressure = 20e6  # Pa
    current_effective_stress = 1500 * 9.81 * depth
    if current_effective_stress > preconsolidation_pressure:
        compression_index = virgin_compression_index
    else:
        compression_index = recompression_index
    return {'compression_index': compression_index, 'preconsolidation_pressure': preconsolidation_pressure}

def _calculate_permeability_evolution(point, depth):
    initial_permeability = 1e-15  # m²
    porosity_change = -0.05  # 5% reduction
    kozeny_carman_exponent = 3
    permeability_change_factor = ((0.2 + porosity_change) / 0.2)**kozeny_carman_exponent
    current_permeability = initial_permeability * permeability_change_factor
    return {'current_permeability': current_permeability, 'permeability_ratio': permeability_change_factor}

def _calculate_comprehensive_pore_pressure_stress(framework, point, depth):
    # Base pore pressure calculation
    hydrostatic_pressure = 1000 * 9.81 * depth
    overpressure_ratio = framework['pore_pressure_field_analysis']['overpressure_analysis']['overpressure_ratio']
    total_pore_pressure = overpressure_ratio * hydrostatic_pressure
    
    # Effective stress calculation
    biot_coefficient = framework['effective_stress_analysis']['biot_effective_stress']['biot_coefficient']
    
    # Base total stress
    total_stress_magnitude = 2500 * 9.81 * depth
    
    # Pore pressure stress tensor (negative because it reduces effective stress)
    pore_pressure_stress = -np.eye(3) * total_pore_pressure * biot_coefficient
    
    # Apply poroelastic corrections
    loading_efficiency = framework['poroelastic_analysis']['loading_efficiency']['loading_efficiency']
    corrected_stress = pore_pressure_stress * loading_efficiency
    
    return corrected_stress

def _quantify_pore_pressure_stress_uncertainty(stress_components, framework):
    uncertainty_sources = {
        'pressure_measurement_uncertainty': 0.08,
        'biot_coefficient_uncertainty': 0.12,
        'permeability_uncertainty': 0.30,
        'fluid_property_uncertainty': 0.05,
        'boundary_condition_uncertainty': 0.15
    }
    total_uncertainty = np.sqrt(sum(u**2 for u in uncertainty_sources.values()))
    return {'total_uncertainty': total_uncertainty, 'uncertainty_sources': uncertainty_sources}

def calculate_lithostatic_stress(point: np.ndarray, depth: float, domain_bounds: Dict) -> np.ndarray:
    """Advanced lithostatic stress calculation with comprehensive geomechanical analysis"""
    
    lithostatic_framework = {
        'density_distribution_analysis': {},
        'gravitational_field_analysis': {},
        'lateral_stress_analysis': {},
        'structural_geology_analysis': {},
        'depth_dependent_analysis': {},
        'anisotropy_analysis': {}
    }
    
    # Density distribution analysis
    lithostatic_framework['density_distribution_analysis'] = {
        'stratigraphic_density_profile': _calculate_stratigraphic_density_profile(point, depth, domain_bounds),
        'lithological_density_variations': _calculate_lithological_density_variations(point, depth, domain_bounds),
        'porosity_depth_relationship': _calculate_porosity_depth_relationship(point, depth, domain_bounds),
        'compaction_induced_density': _calculate_compaction_induced_density(point, depth, domain_bounds),
        'metamorphic_density_changes': _calculate_metamorphic_density_changes(point, depth, domain_bounds),
        'fluid_saturation_effects': _calculate_fluid_saturation_density_effects(point, depth, domain_bounds)
    }
    
    # Gravitational field analysis
    lithostatic_framework['gravitational_field_analysis'] = {
        'gravity_anomaly_analysis': _analyze_gravity_anomalies(point, depth, domain_bounds),
        'topographic_gravity_effects': _calculate_topographic_gravity_effects(point, depth, domain_bounds),
        'subsurface_mass_distribution': _analyze_subsurface_mass_distribution(point, depth, domain_bounds),
        'crustal_thickness_effects': _calculate_crustal_thickness_gravity_effects(point, depth, domain_bounds),
        'mantle_density_contributions': _calculate_mantle_density_contributions(point, depth, domain_bounds),
        'gravitational_gradient_tensor': _calculate_gravitational_gradient_tensor(point, depth, domain_bounds)
    }
    
    # Lateral stress analysis
    lithostatic_framework['lateral_stress_analysis'] = {
        'earth_pressure_coefficient': _calculate_earth_pressure_coefficient(point, depth, domain_bounds),
        'tectonic_lateral_stress': _calculate_tectonic_lateral_stress_component(point, depth, domain_bounds),
        'topographic_lateral_effects': _calculate_topographic_lateral_stress_effects(point, depth, domain_bounds),
        'structural_lateral_stress': _calculate_structural_lateral_stress_effects(point, depth, domain_bounds),
        'anisotropic_lateral_stress': _calculate_anisotropic_lateral_stress(point, depth, domain_bounds),
        'time_dependent_lateral_stress': _calculate_time_dependent_lateral_stress(point, depth, domain_bounds)
    }
    
    # Structural geology analysis
    lithostatic_framework['structural_geology_analysis'] = {
        'bedding_plane_effects': _analyze_bedding_plane_stress_effects(point, depth, domain_bounds),
        'foliation_stress_influence': _analyze_foliation_stress_influence(point, depth, domain_bounds),
        'joint_fracture_effects': _analyze_joint_fracture_stress_effects(point, depth, domain_bounds),
        'fault_proximity_stress': _analyze_fault_proximity_lithostatic_stress(point, depth, domain_bounds),
        'fold_structure_effects': _analyze_fold_structure_stress_effects(point, depth, domain_bounds),
        'unconformity_stress_effects': _analyze_unconformity_stress_effects(point, depth, domain_bounds)
    }
    
    # Depth dependent analysis
    lithostatic_framework['depth_dependent_analysis'] = {
        'pressure_depth_relationship': _calculate_pressure_depth_relationship(point, depth, domain_bounds),
        'elastic_moduli_depth_variation': _calculate_elastic_moduli_depth_variation(point, depth, domain_bounds),
        'strength_depth_relationship': _calculate_strength_depth_relationship(point, depth, domain_bounds),
        'brittle_ductile_transition': _analyze_brittle_ductile_transition_effects(point, depth, domain_bounds),
        'depth_dependent_anisotropy': _analyze_depth_dependent_anisotropy(point, depth, domain_bounds),
        'pressure_solution_effects': _analyze_pressure_solution_effects(point, depth, domain_bounds)
    }
    
    # Anisotropy analysis
    lithostatic_framework['anisotropy_analysis'] = {
        'stress_anisotropy_tensor': _calculate_stress_anisotropy_tensor(point, depth, domain_bounds),
        'fabric_induced_anisotropy': _analyze_fabric_induced_anisotropy(point, depth, domain_bounds),
        'layering_anisotropy_effects': _analyze_layering_anisotropy_effects(point, depth, domain_bounds),
        'crystal_preferred_orientation': _analyze_crystal_preferred_orientation_effects(point, depth, domain_bounds),
        'fracture_induced_anisotropy': _analyze_fracture_induced_anisotropy(point, depth, domain_bounds),
        'scale_dependent_anisotropy': _analyze_scale_dependent_anisotropy(point, depth, domain_bounds)
    }
    
    # Calculate comprehensive lithostatic stress tensor
    stress_components = _calculate_comprehensive_lithostatic_stress(lithostatic_framework, point, depth, domain_bounds)
    
    # Apply uncertainty quantification
    uncertainty_analysis = _quantify_lithostatic_stress_uncertainty(stress_components, lithostatic_framework)
    
    return stress_components

# Comprehensive helper methods for lithostatic stress analysis
def _calculate_stratigraphic_density_profile(point, depth, domain_bounds):
    # Multi-layer stratigraphic density model
    layer_interfaces = [0, 1000, 3000, 6000, 10000, depth]  # m
    layer_densities = [2200, 2400, 2600, 2700, 2800, 2900]  # kg/m³
    
    current_layer = 0
    for i, interface_depth in enumerate(layer_interfaces[1:]):
        if depth <= interface_depth:
            current_layer = i
            break
    
    base_density = layer_densities[current_layer]
    depth_gradient = 0.05  # kg/m³/m
    effective_density = base_density + depth_gradient * depth
    
    return {'effective_density': effective_density, 'layer_id': current_layer, 'base_density': base_density}

def _calculate_lithological_density_variations(point, depth, domain_bounds):
    # Spatial variations based on lithology
    x, y = point[0], point[1]
    granite_probability = 0.5 + 0.3 * np.sin(x / 10000) * np.cos(y / 8000)
    sediment_probability = 1 - granite_probability
    
    granite_density = 2650  # kg/m³
    sediment_density = 2300  # kg/m³
    metamorphic_density = 2800  # kg/m³
    
    # Depth-dependent metamorphism
    metamorphic_factor = min(1.0, depth / 15000)
    effective_density = (granite_probability * granite_density + 
                        sediment_probability * sediment_density) * (1 - metamorphic_factor) + \
                       metamorphic_density * metamorphic_factor
    
    return {'effective_density': effective_density, 'granite_prob': granite_probability, 'metamorphic_factor': metamorphic_factor}

def _calculate_porosity_depth_relationship(point, depth, domain_bounds):
    # Athy's law for porosity-depth relationship
    surface_porosity = 0.4  # 40% at surface
    compaction_factor = 2e-4  # /m
    porosity = surface_porosity * np.exp(-compaction_factor * depth)
    
    # Porosity effects on density
    grain_density = 2700  # kg/m³
    fluid_density = 1000  # kg/m³
    bulk_density = porosity * fluid_density + (1 - porosity) * grain_density
    
    return {'porosity': porosity, 'bulk_density': bulk_density, 'compaction_factor': compaction_factor}

def _calculate_compaction_induced_density(point, depth, domain_bounds):
    # Mechanical compaction effects
    effective_stress = 1500 * 9.81 * depth  # Pa
    reference_stress = 1e6  # Pa
    compaction_coefficient = 1e-8  # /Pa
    
    porosity_reduction = compaction_coefficient * (effective_stress - reference_stress)
    porosity_reduction = max(0, min(0.3, porosity_reduction))
    
    initial_porosity = 0.3
    final_porosity = initial_porosity - porosity_reduction
    
    grain_density = 2700  # kg/m³
    fluid_density = 1000  # kg/m³
    compacted_density = final_porosity * fluid_density + (1 - final_porosity) * grain_density
    
    return {'compacted_density': compacted_density, 'porosity_reduction': porosity_reduction, 'final_porosity': final_porosity}

def _calculate_metamorphic_density_changes(point, depth, domain_bounds):
    # Temperature and pressure dependent density changes
    temperature = 15 + 0.025 * depth  # °C
    pressure = 2500 * 9.81 * depth  # Pa
    
    # Metamorphic grade classification
    if temperature < 200:
        metamorphic_grade = 'diagenesis'
        density_factor = 1.0
    elif temperature < 400:
        metamorphic_grade = 'low_grade'
        density_factor = 1.05
    elif temperature < 650:
        metamorphic_grade = 'medium_grade'
        density_factor = 1.10
    else:
        metamorphic_grade = 'high_grade'
        density_factor = 1.15
    
    base_density = 2500  # kg/m³
    metamorphic_density = base_density * density_factor
    
    return {'metamorphic_density': metamorphic_density, 'metamorphic_grade': metamorphic_grade, 'density_factor': density_factor}

def _calculate_fluid_saturation_density_effects(point, depth, domain_bounds):
    # Multi-phase fluid saturation effects
    water_saturation = 0.7 - 0.2 * min(depth / 5000, 1.0)  # Decreases with depth
    oil_saturation = 0.2 + 0.15 * min(depth / 3000, 1.0)   # Increases with depth
    gas_saturation = 1 - water_saturation - oil_saturation
    
    water_density = 1000  # kg/m³
    oil_density = 800     # kg/m³
    gas_density = 200     # kg/m³ (under pressure)
    
    fluid_density = (water_saturation * water_density + 
                    oil_saturation * oil_density + 
                    gas_saturation * gas_density)
    
    porosity = 0.2 * np.exp(-depth / 10000)
    grain_density = 2700  # kg/m³
    bulk_density = porosity * fluid_density + (1 - porosity) * grain_density
    
    return {'bulk_density': bulk_density, 'fluid_density': fluid_density, 'saturations': [water_saturation, oil_saturation, gas_saturation]}

def _analyze_gravity_anomalies(point, depth, domain_bounds):
    # Regional and local gravity anomalies
    x, y = point[0], point[1]
    
    # Regional Bouguer anomaly
    regional_anomaly = 20 * np.sin(2 * np.pi * x / 100000) * np.cos(2 * np.pi * y / 80000)  # mGal
    
    # Local anomalies from subsurface structures
    local_anomaly = 5 * np.exp(-(x**2 + y**2) / (20000**2))  # mGal
    
    total_anomaly = regional_anomaly + local_anomaly
    
    # Convert to density variations
    anomaly_to_density = 0.4  # (kg/m³)/mGal
    density_variation = total_anomaly * anomaly_to_density
    
    return {'total_anomaly': total_anomaly, 'regional_anomaly': regional_anomaly, 'density_variation': density_variation}

def _calculate_topographic_gravity_effects(point, depth, domain_bounds):
    # Terrain corrections for gravity
    elevation = point[2] if len(point) > 2 else 0
    topographic_density = 2670  # kg/m³
    
    # Bouguer correction
    bouguer_correction = 2 * np.pi * 6.67e-11 * topographic_density * elevation * 1e5  # Convert to mGal
    
    # Terrain correction (simplified)
    terrain_roughness = 100 * abs(np.sin(point[0] / 1000) * np.cos(point[1] / 1000))  # m
    terrain_correction = 0.1 * terrain_roughness  # mGal
    
    total_correction = bouguer_correction + terrain_correction
    
    return {'bouguer_correction': bouguer_correction, 'terrain_correction': terrain_correction, 'total_correction': total_correction}

def _analyze_subsurface_mass_distribution(point, depth, domain_bounds):
    # 3D subsurface mass distribution modeling
    x, y = point[0], point[1]
    
    # Density heterogeneities
    density_anomalies = []
    anomaly_centers = [(5000, 3000, 2000), (-8000, 6000, 4000), (12000, -4000, 3500)]
    anomaly_magnitudes = [200, -150, 300]  # kg/m³
    anomaly_radii = [3000, 2500, 4000]  # m
    
    total_density_effect = 0
    for center, magnitude, radius in zip(anomaly_centers, anomaly_magnitudes, anomaly_radii):
        distance = np.sqrt((x - center[0])**2 + (y - center[1])**2 + (depth - center[2])**2)
        if distance < radius:
            density_effect = magnitude * np.exp(-(distance / radius)**2)
            total_density_effect += density_effect
            density_anomalies.append({'center': center, 'magnitude': magnitude, 'effect': density_effect})
    
    return {'total_density_effect': total_density_effect, 'anomalies': density_anomalies}

def _calculate_crustal_thickness_gravity_effects(point, depth, domain_bounds):
    # Isostatic effects from crustal thickness variations
    x, y = point[0], point[1]
    
    reference_thickness = 35000  # m
    thickness_variation = 5000 * np.sin(x / 50000) * np.cos(y / 40000)  # m
    crustal_thickness = reference_thickness + thickness_variation
    
    crustal_density = 2800  # kg/m³
    mantle_density = 3300  # kg/m³
    density_contrast = mantle_density - crustal_density
    
    # Isostatic gravity effect
    isostatic_anomaly = 2 * np.pi * 6.67e-11 * density_contrast * thickness_variation * 1e5  # mGal
    
    return {'crustal_thickness': crustal_thickness, 'thickness_variation': thickness_variation, 'isostatic_anomaly': isostatic_anomaly}

def _calculate_mantle_density_contributions(point, depth, domain_bounds):
    # Mantle density variations and their effects
    if depth > 35000:  # Below Moho
        mantle_depth = depth - 35000
        # Temperature-dependent density in mantle
        mantle_surface_temp = 800  # °C at Moho
        mantle_gradient = 0.5e-3  # °C/m
        mantle_temp = mantle_surface_temp + mantle_gradient * mantle_depth
        
        # Density-temperature relationship
        reference_density = 3300  # kg/m³ at reference temperature
        thermal_expansion = 3e-5  # /°C
        reference_temp = 1000  # °C
        
        mantle_density = reference_density * (1 - thermal_expansion * (mantle_temp - reference_temp))
        density_contribution = mantle_density - 3300  # Deviation from standard
    else:
        density_contribution = 0
        mantle_density = 3300
    
    return {'mantle_density': mantle_density, 'density_contribution': density_contribution}

def _calculate_gravitational_gradient_tensor(point, depth, domain_bounds):
    # Second derivatives of gravitational potential
    x, y = point[0], point[1]
    
    # Simplified gradient tensor components
    Txx = 1e-9 * np.sin(x / 10000)  # Eotvos units
    Tyy = -Txx  # Conservation constraint
    Tzz = 0  # Laplace equation constraint
    Txy = 1e-9 * np.cos(y / 8000)
    Txz = 0.5e-9 * np.sin(depth / 5000)
    Tyz = 0.3e-9 * np.cos(depth / 7000)
    
    gradient_tensor = np.array([[Txx, Txy, Txz],
                               [Txy, Tyy, Tyz],
                               [Txz, Tyz, Tzz]])
    
    return {'gradient_tensor': gradient_tensor, 'tensor_invariants': [Txx + Tyy + Tzz, np.linalg.det(gradient_tensor)]}

def _calculate_earth_pressure_coefficient(point, depth, domain_bounds):
    # Advanced earth pressure coefficient calculation
    # Jaky's formula with corrections
    friction_angle = 30 + 5 * np.sin(depth / 5000)  # degrees, varies with depth
    phi_rad = np.radians(friction_angle)
    
    # At-rest coefficient
    K0_jaky = 1 - np.sin(phi_rad)
    
    # Overconsolidation effects
    OCR = 1.5 + 0.5 * np.exp(-depth / 3000)  # Overconsolidation ratio
    K0_oc = K0_jaky * OCR**np.sin(phi_rad)
    
    # Stress history effects
    stress_history_factor = 1.0 + 0.1 * np.sin(depth / 2000)
    K0_effective = K0_oc * stress_history_factor
    
    return {'K0': K0_effective, 'friction_angle': friction_angle, 'OCR': OCR}

def _calculate_tectonic_lateral_stress_component(point, depth, domain_bounds):
    # Tectonic contribution to lateral stress
    x, y = point[0], point[1]
    
    # Regional tectonic stress orientation
    regional_azimuth = np.pi/3  # 60 degrees
    local_perturbation = 0.2 * np.sin(x / 8000) * np.cos(y / 6000)
    effective_azimuth = regional_azimuth + local_perturbation
    
    # Tectonic stress magnitude
    tectonic_magnitude = 10e6 * (1 + 0.3 * depth / 10000)  # Pa
    
    # Stress components
    sigma_H_tectonic = tectonic_magnitude * np.cos(effective_azimuth)**2
    sigma_h_tectonic = tectonic_magnitude * np.sin(effective_azimuth)**2
    
    return {'sigma_H_tectonic': sigma_H_tectonic, 'sigma_h_tectonic': sigma_h_tectonic, 'azimuth': effective_azimuth}

def _calculate_topographic_lateral_stress_effects(point, depth, domain_bounds):
    # Topographic effects on lateral stress
    elevation = point[2] if len(point) > 2 else 0
    
    # Slope effects
    slope_gradient = 0.1  # Simplified slope
    topographic_stress = 2670 * 9.81 * elevation * slope_gradient  # Pa
    
    # Valley/ridge effects
    valley_factor = 0.8 if elevation < 0 else 1.2
    ridge_stress = topographic_stress * valley_factor
    
    # Depth attenuation
    attenuation_factor = np.exp(-depth / 2000)
    effective_topographic_stress = ridge_stress * attenuation_factor
    
    return {'topographic_stress': effective_topographic_stress, 'attenuation_factor': attenuation_factor}

def _calculate_structural_lateral_stress_effects(point, depth, domain_bounds):
    # Structural geology effects on lateral stress
    x, y = point[0], point[1]
    
    # Fold-related stress concentrations
    fold_wavelength = 5000  # m
    fold_amplitude = 1000   # m
    fold_stress = 5e6 * np.sin(2 * np.pi * x / fold_wavelength) * np.exp(-depth / fold_amplitude)
    
    # Fault-related stress perturbations
    fault_distance = abs(y - 2000)  # Distance from major fault at y=2000
    fault_stress = 8e6 * np.exp(-fault_distance / 1000)
    
    total_structural_stress = fold_stress + fault_stress
    
    return {'structural_stress': total_structural_stress, 'fold_component': fold_stress, 'fault_component': fault_stress}

def _calculate_anisotropic_lateral_stress(point, depth, domain_bounds):
    # Anisotropic lateral stress distribution
    x, y = point[0], point[1]
    
    # Fabric-controlled anisotropy
    fabric_orientation = np.pi/4 + 0.1 * np.sin(x / 3000)  # radians
    anisotropy_ratio = 1.3 + 0.2 * np.cos(depth / 4000)
    
    # Base isotropic lateral stress
    base_lateral_stress = 0.7 * 2700 * 9.81 * depth
    
    # Anisotropic components
    sigma_H = base_lateral_stress * anisotropy_ratio
    sigma_h = base_lateral_stress / anisotropy_ratio
    
    # Rotation matrix for fabric orientation
    cos_theta = np.cos(fabric_orientation)
    sin_theta = np.sin(fabric_orientation)
    
    anisotropic_tensor = np.array([[sigma_H * cos_theta**2 + sigma_h * sin_theta**2,
                                   (sigma_H - sigma_h) * cos_theta * sin_theta,
                                   0],
                                  [(sigma_H - sigma_h) * cos_theta * sin_theta,
                                   sigma_H * sin_theta**2 + sigma_h * cos_theta**2,
                                   0],
                                  [0, 0, base_lateral_stress]])
    
    return {'anisotropic_tensor': anisotropic_tensor, 'anisotropy_ratio': anisotropy_ratio, 'fabric_orientation': fabric_orientation}

def _calculate_time_dependent_lateral_stress(point, depth, domain_bounds):
    # Time-dependent lateral stress evolution
    current_time = 0  # Present day
    
    # Tectonic loading cycles
    cycle_period = 10e6 * 365.25 * 24 * 3600  # 10 Ma in seconds
    cyclic_stress = 3e6 * np.sin(2 * np.pi * current_time / cycle_period)
    
    # Long-term tectonic trends
    long_term_rate = 1e-9  # Pa/s
    long_term_stress = long_term_rate * current_time
    
    # Transient effects (earthquake cycles)
    earthquake_cycle = 500 * 365.25 * 24 * 3600  # 500 years
    transient_stress = 2e6 * (1 - np.exp(-current_time / earthquake_cycle))
    
    total_time_stress = cyclic_stress + long_term_stress + transient_stress
    
    return {'time_dependent_stress': total_time_stress, 'cyclic_component': cyclic_stress, 'transient_component': transient_stress}

def _analyze_bedding_plane_stress_effects(point, depth, domain_bounds):
    # Bedding plane influence on stress distribution
    bedding_dip = 20 + 10 * np.sin(point[0] / 5000)  # degrees
    bedding_strike = 45  # degrees
    
    dip_rad = np.radians(bedding_dip)
    strike_rad = np.radians(bedding_strike)
    
    # Stress concentration at bedding interfaces
    interface_density = depth / 100  # interfaces per meter
    bedding_stress_factor = 1.0 + 0.1 * interface_density * np.sin(dip_rad)
    
    # Slip potential along bedding planes
    shear_stress_ratio = np.tan(dip_rad) / np.tan(np.radians(30))  # Friction angle = 30°
    slip_potential = max(0, shear_stress_ratio - 1.0)
    
    return {'bedding_stress_factor': bedding_stress_factor, 'slip_potential': slip_potential, 'bedding_dip': bedding_dip}

def _analyze_foliation_stress_influence(point, depth, domain_bounds):
    # Metamorphic foliation effects on stress
    x, y = point[0], point[1]
    
    # Foliation orientation
    foliation_strike = 120 + 20 * np.cos(x / 8000)  # degrees
    foliation_dip = 60 + 15 * np.sin(y / 6000)    # degrees
    
    # Foliation intensity (degree of development)
    metamorphic_grade = min(1.0, depth / 15000)
    foliation_intensity = metamorphic_grade**0.5
    
    # Stress anisotropy due to foliation
    parallel_strength = 80e6 * (1 + foliation_intensity)  # Pa
    perpendicular_strength = 120e6 * (1 - 0.3 * foliation_intensity)  # Pa
    anisotropy_factor = perpendicular_strength / parallel_strength
    
    return {'anisotropy_factor': anisotropy_factor, 'foliation_intensity': foliation_intensity, 'foliation_dip': foliation_dip}

def _analyze_joint_fracture_stress_effects(point, depth, domain_bounds):
    # Joint and fracture network effects
    x, y = point[0], point[1]
    
    # Fracture density
    surface_fracture_density = 0.5  # fractures/m
    fracture_density = surface_fracture_density * np.exp(-depth / 3000)
    
    # Joint orientations (multiple sets)
    joint_sets = [
        {'strike': 30, 'dip': 85, 'spacing': 2.0},   # Joint set 1
        {'strike': 120, 'dip': 80, 'spacing': 1.5},  # Joint set 2
        {'strike': 210, 'dip': 75, 'spacing': 3.0}   # Joint set 3
    ]
    
    # Stress reduction due to fractures
    total_fracture_effect = 0
    for joint_set in joint_sets:
        spacing = joint_set['spacing']
        fracture_effect = 0.1 / spacing  # Inverse relationship with spacing
        total_fracture_effect += fracture_effect
    
    stress_reduction_factor = 1.0 - min(0.4, total_fracture_effect * fracture_density)
    
    return {'fracture_density': fracture_density, 'stress_reduction_factor': stress_reduction_factor, 'joint_sets': joint_sets}

def _analyze_fault_proximity_lithostatic_stress(point, depth, domain_bounds):
    # Fault proximity effects on lithostatic stress
    x, y = point[0], point[1]
    
    # Distance to nearest major fault
    fault_locations = [(5000, 8000), (-3000, 4000), (12000, -2000)]
    min_distance = float('inf')
    for fault_x, fault_y in fault_locations:
        distance = np.sqrt((x - fault_x)**2 + (y - fault_y)**2)
        min_distance = min(min_distance, distance)
    
    # Stress perturbation zone around faults
    perturbation_radius = 2000  # m
    if min_distance < perturbation_radius:
        stress_amplification = 1.5 * np.exp(-min_distance / 1000)
        stress_rotation_angle = 0.3 * np.exp(-min_distance / 800)  # radians
    else:
        stress_amplification = 1.0
        stress_rotation_angle = 0.0
    
    return {'fault_distance': min_distance, 'stress_amplification': stress_amplification, 'rotation_angle': stress_rotation_angle}

def _analyze_fold_structure_stress_effects(point, depth, domain_bounds):
    # Fold-related stress concentrations
    x, y = point[0], point[1]
    
    # Fold geometry
    fold_wavelength = 8000  # m
    fold_amplitude = 1500   # m
    fold_axis_trend = 45    # degrees
    
    # Position relative to fold
    fold_position = np.sin(2 * np.pi * x / fold_wavelength)  # -1 (trough) to +1 (crest)
    
    # Curvature-related stress
    fold_curvature = 4 * np.pi**2 * fold_amplitude / fold_wavelength**2
    curvature_stress = 5e6 * fold_curvature * abs(fold_position)
    
    # Hinge vs limb effects
    if abs(fold_position) < 0.3:  # Near hinge
        structure_factor = 1.3
    else:  # On limb
        structure_factor = 0.9
    
    fold_stress = curvature_stress * structure_factor
    
    return {'fold_stress': fold_stress, 'fold_position': fold_position, 'curvature_stress': curvature_stress}

def _analyze_unconformity_stress_effects(point, depth, domain_bounds):
    # Unconformity-related stress effects
    unconformity_depths = [500, 2000, 4500]  # m
    
    stress_effects = []
    total_unconformity_stress = 0
    
    for unc_depth in unconformity_depths:
        distance_to_unconformity = abs(depth - unc_depth)
        
        if distance_to_unconformity < 200:  # Within influence zone
            # Mechanical contrast across unconformity
            upper_modulus = 20e9  # Pa
            lower_modulus = 50e9  # Pa
            modulus_contrast = lower_modulus / upper_modulus
            
            contrast_stress = 2e6 * (modulus_contrast - 1.0) * np.exp(-distance_to_unconformity / 100)
            total_unconformity_stress += contrast_stress
            
            stress_effects.append({
                'depth': unc_depth,
                'distance': distance_to_unconformity,
                'contrast_stress': contrast_stress
            })
    
    return {'total_unconformity_stress': total_unconformity_stress, 'effects': stress_effects}

def _calculate_pressure_depth_relationship(point, depth, domain_bounds):
    # Non-linear pressure-depth relationships
    x, y = point[0], point[1]
    
    # Hydrostatic pressure component
    fluid_gradient = 9810  # Pa/m
    hydrostatic_pressure = fluid_gradient * depth
    
    # Lithostatic pressure component
    rock_gradient = 25000  # Pa/m average
    depth_variation = 2000 * np.sin(depth / 3000)  # Gradient variations
    effective_gradient = rock_gradient + depth_variation
    lithostatic_pressure = effective_gradient * depth
    
    # Non-linear effects from compaction
    compaction_factor = 1 + 0.1 * (depth / 5000)**2
    total_pressure = lithostatic_pressure * compaction_factor + hydrostatic_pressure
    
    return {'total_pressure': total_pressure, 'lithostatic_component': lithostatic_pressure, 'hydrostatic_component': hydrostatic_pressure}

def _calculate_elastic_moduli_depth_variation(point, depth, domain_bounds):
    # Depth-dependent elastic properties
    surface_E = 20e9  # Pa
    deep_E = 80e9     # Pa
    
    # Exponential increase with depth
    E_depth = surface_E + (deep_E - surface_E) * (1 - np.exp(-depth / 8000))
    
    # Temperature and pressure effects
    temperature = 15 + 0.025 * depth  # °C
    pressure = 25000 * depth  # Pa
    
    # Temperature reduction of modulus
    temp_factor = 1.0 - 1e-4 * (temperature - 15)
    # Pressure increase of modulus
    pressure_factor = 1.0 + 1e-11 * pressure
    
    effective_E = E_depth * temp_factor * pressure_factor
    
    # Poisson's ratio variation
    surface_nu = 0.25
    deep_nu = 0.30
    nu_depth = surface_nu + (deep_nu - surface_nu) * min(depth / 10000, 1.0)
    
    return {'elastic_modulus': effective_E, 'poissons_ratio': nu_depth, 'temperature_factor': temp_factor}

def _calculate_strength_depth_relationship(point, depth, domain_bounds):
    # Strength variations with depth
    # Cohesive strength
    surface_cohesion = 5e6  # Pa
    deep_cohesion = 50e6    # Pa
    cohesion = surface_cohesion + (deep_cohesion - surface_cohesion) * min(depth / 12000, 1.0)
    
    # Friction angle
    surface_friction = 25   # degrees
    deep_friction = 35      # degrees
    friction_angle = surface_friction + (deep_friction - surface_friction) * min(depth / 15000, 1.0)
    
    # Tensile strength
    surface_tensile = 2e6   # Pa
    deep_tensile = 10e6     # Pa
    tensile_strength = surface_tensile + (deep_tensile - surface_tensile) * min(depth / 10000, 1.0)
    
    return {'cohesion': cohesion, 'friction_angle': friction_angle, 'tensile_strength': tensile_strength}

def _analyze_brittle_ductile_transition_effects(point, depth, domain_bounds):
    # Brittle-ductile transition analysis
    temperature = 15 + 0.025 * depth  # °C
    pressure = 25000 * depth  # Pa
    strain_rate = 1e-14  # /s (geological strain rate)
    
    # Critical temperature for B-D transition (quartz)
    critical_temp = 300 + 50 * np.log10(strain_rate / 1e-14)  # °C
    
    if temperature < critical_temp:
        deformation_mode = 'brittle'
        strength_factor = 1.0
    else:
        deformation_mode = 'ductile'
        # Exponential strength reduction in ductile regime
        temp_excess = temperature - critical_temp
        strength_factor = np.exp(-temp_excess / 100)
    
    # Transition zone effects
    transition_width = 50  # °C
    if abs(temperature - critical_temp) < transition_width:
        transition_factor = 0.5 * (1 + np.cos(np.pi * (temperature - critical_temp) / transition_width))
        strength_factor = strength_factor * transition_factor + (1 - transition_factor)
    
    return {'deformation_mode': deformation_mode, 'strength_factor': strength_factor, 'critical_temp': critical_temp}

def _analyze_depth_dependent_anisotropy(point, depth, domain_bounds):
    # Anisotropy evolution with depth
    x, y = point[0], point[1]
    
    # Structural anisotropy (decreases with depth)
    surface_anisotropy = 0.3
    structural_anisotropy = surface_anisotropy * np.exp(-depth / 5000)
    
    # Stress-induced anisotropy (increases with depth)
    stress_anisotropy = 0.1 * min(depth / 10000, 1.0)
    
    # Metamorphic anisotropy (depth dependent)
    if depth > 8000:
        metamorphic_anisotropy = 0.2 * ((depth - 8000) / 12000)
    else:
        metamorphic_anisotropy = 0.0
    
    total_anisotropy = structural_anisotropy + stress_anisotropy + metamorphic_anisotropy
    
    # Anisotropy orientation
    anisotropy_azimuth = 30 + 20 * np.sin(x / 6000) * np.cos(y / 8000)  # degrees
    
    return {'total_anisotropy': total_anisotropy, 'structural_component': structural_anisotropy, 
            'stress_component': stress_anisotropy, 'anisotropy_azimuth': anisotropy_azimuth}

def _analyze_pressure_solution_effects(point, depth, domain_bounds):
    # Pressure solution and dissolution effects
    temperature = 15 + 0.025 * depth  # °C
    effective_stress = 15000 * depth  # Pa
    
    # Solubility increases with temperature and pressure
    solubility_factor = 1.0 + 0.01 * temperature + 1e-8 * effective_stress
    
    # Pressure solution rate
    if temperature > 100:  # Significant pressure solution
        ps_rate = 1e-15 * solubility_factor * (effective_stress / 1e6)  # /s
    else:
        ps_rate = 0
    
    # Porosity changes due to pressure solution
    time_factor = 100e6 * 365.25 * 24 * 3600  # 100 Ma
    porosity_reduction = ps_rate * time_factor
    porosity_reduction = min(0.1, porosity_reduction)  # Maximum 10% reduction
    
    # Strength changes
    strength_increase_factor = 1.0 + 2 * porosity_reduction
    
    return {'pressure_solution_rate': ps_rate, 'porosity_reduction': porosity_reduction, 'strength_increase': strength_increase_factor}

def _calculate_stress_anisotropy_tensor(point, depth, domain_bounds):
    # Full stress anisotropy tensor
    x, y = point[0], point[1]
    
    # Principal anisotropy directions
    major_axis_azimuth = 45 + 15 * np.sin(x / 7000)  # degrees
    intermediate_axis_azimuth = major_axis_azimuth + 90
    minor_axis_azimuth = major_axis_azimuth + 180
    
    # Anisotropy magnitudes
    major_anisotropy = 1.3 + 0.2 * min(depth / 8000, 1.0)
    intermediate_anisotropy = 1.1 + 0.1 * min(depth / 8000, 1.0)
    minor_anisotropy = 0.8 - 0.1 * min(depth / 8000, 1.0)
    
    # Construct anisotropy tensor in principal coordinates
    principal_tensor = np.diag([major_anisotropy, intermediate_anisotropy, minor_anisotropy])
    
    # Rotation matrix
    theta = np.radians(major_axis_azimuth)
    rotation_matrix = np.array([[np.cos(theta), -np.sin(theta), 0],
                               [np.sin(theta), np.cos(theta), 0],
                               [0, 0, 1]])
    
    # Rotated anisotropy tensor
    anisotropy_tensor = rotation_matrix @ principal_tensor @ rotation_matrix.T
    
    return {'anisotropy_tensor': anisotropy_tensor, 'principal_values': [major_anisotropy, intermediate_anisotropy, minor_anisotropy]}

def _analyze_fabric_induced_anisotropy(point, depth, domain_bounds):
    # Rock fabric-induced mechanical anisotropy
    x, y = point[0], point[1]
    
    # Fabric types and their anisotropy
    fabrics = {
        'bedding': {'strength': 0.3, 'orientation': 120},  # degrees
        'foliation': {'strength': 0.4, 'orientation': 30},
        'lineation': {'strength': 0.2, 'orientation': 75},
        'joints': {'strength': 0.25, 'orientation': 160}
    }
    
    # Depth-dependent fabric development
    fabric_development_factor = min(1.0, depth / 6000)
    
    total_fabric_anisotropy = 0
    dominant_orientation = 0
    for fabric_type, properties in fabrics.items():
        fabric_strength = properties['strength'] * fabric_development_factor
        total_fabric_anisotropy += fabric_strength
        # Weight orientation by strength
        dominant_orientation += properties['orientation'] * fabric_strength
    
    if total_fabric_anisotropy > 0:
        dominant_orientation /= total_fabric_anisotropy
    
    return {'total_fabric_anisotropy': total_fabric_anisotropy, 'dominant_orientation': dominant_orientation, 'fabrics': fabrics}

def _analyze_layering_anisotropy_effects(point, depth, domain_bounds):
    # Sedimentary/metamorphic layering anisotropy
    layer_thickness = 0.5 + 1.5 * np.random.random()  # 0.5-2.0 m
    layer_spacing = depth / (depth / layer_thickness)  # Number of layers
    
    # Mechanical contrast between layers
    stiff_layer_modulus = 60e9  # Pa
    soft_layer_modulus = 20e9   # Pa
    modulus_ratio = stiff_layer_modulus / soft_layer_modulus
    
    # Layer proportion
    stiff_proportion = 0.6
    soft_proportion = 0.4
    
    # Effective anisotropy from layer sequence
    parallel_modulus = stiff_proportion * stiff_layer_modulus + soft_proportion * soft_layer_modulus
    perpendicular_modulus = 1 / (stiff_proportion / stiff_layer_modulus + soft_proportion / soft_layer_modulus)
    
    layering_anisotropy_ratio = parallel_modulus / perpendicular_modulus
    
    return {'anisotropy_ratio': layering_anisotropy_ratio, 'layer_thickness': layer_thickness, 'modulus_ratio': modulus_ratio}

def _analyze_crystal_preferred_orientation_effects(point, depth, domain_bounds):
    # Crystal preferred orientation (CPO) anisotropy
    temperature = 15 + 0.025 * depth  # °C
    pressure = 25000 * depth  # Pa
    
    # CPO development threshold
    cpo_threshold_temp = 400  # °C
    cpo_threshold_pressure = 500e6  # Pa
    
    if temperature > cpo_threshold_temp and pressure > cpo_threshold_pressure:
        # Strong CPO development
        cpo_intensity = min(1.0, (temperature - cpo_threshold_temp) / 200)
        
        # Mineral-specific anisotropy
        quartz_anisotropy = 1.5 * cpo_intensity
        feldspar_anisotropy = 1.2 * cpo_intensity
        mica_anisotropy = 2.0 * cpo_intensity
        
        # Mineral proportions
        quartz_prop = 0.4
        feldspar_prop = 0.35
        mica_prop = 0.25
        
        total_cpo_anisotropy = (quartz_prop * quartz_anisotropy + 
                               feldspar_prop * feldspar_anisotropy + 
                               mica_prop * mica_anisotropy)
    else:
        total_cpo_anisotropy = 0
        cpo_intensity = 0
    
    return {'cpo_anisotropy': total_cpo_anisotropy, 'cpo_intensity': cpo_intensity, 'development_temperature': temperature}

def _analyze_fracture_induced_anisotropy(point, depth, domain_bounds):
    # Fracture network-induced anisotropy
    x, y = point[0], point[1]
    
    # Fracture sets with different orientations
    fracture_sets = [
        {'orientation': 30, 'density': 0.5, 'length': 10},   # Set 1
        {'orientation': 120, 'density': 0.3, 'length': 15},  # Set 2  
        {'orientation': 210, 'density': 0.4, 'length': 8}    # Set 3
    ]
    
    # Depth-dependent fracture density
    depth_factor = np.exp(-depth / 4000)
    
    total_fracture_anisotropy = 0
    for fset in fracture_sets:
        set_density = fset['density'] * depth_factor
        set_length = fset['length']
        # Anisotropy proportional to fracture area (density × length)
        set_anisotropy = set_density * set_length / 100  # Normalized
        total_fracture_anisotropy += set_anisotropy
    
    # Dominant fracture orientation
    weighted_orientation = sum(fset['orientation'] * fset['density'] * fset['length'] 
                              for fset in fracture_sets)
    if sum(fset['density'] * fset['length'] for fset in fracture_sets) > 0:
        weighted_orientation /= sum(fset['density'] * fset['length'] for fset in fracture_sets)
    
    return {'fracture_anisotropy': total_fracture_anisotropy, 'dominant_orientation': weighted_orientation, 'fracture_sets': fracture_sets}

def _analyze_scale_dependent_anisotropy(point, depth, domain_bounds):
    # Multi-scale anisotropy effects
    x, y = point[0], point[1]
    
    # Scale hierarchy
    scales = {
        'microscale': {'size': 1e-3, 'anisotropy': 0.1},     # mm
        'mesoscale': {'size': 1.0, 'anisotropy': 0.3},      # m  
        'macroscale': {'size': 1000, 'anisotropy': 0.5},    # km
        'regional': {'size': 50000, 'anisotropy': 0.2}      # 50 km
    }
    
    # Domain size for current analysis
    domain_size = max(domain_bounds.get('x_max', 10000) - domain_bounds.get('x_min', 0),
                     domain_bounds.get('y_max', 10000) - domain_bounds.get('y_min', 0))
    
    # Weight anisotropy contributions by scale relevance
    total_weighted_anisotropy = 0
    total_weights = 0
    
    for scale_name, scale_props in scales.items():
        scale_size = scale_props['size']
        scale_anisotropy = scale_props['anisotropy']
        
        # Weight based on how close scale is to domain size
        weight = 1 / (1 + abs(np.log10(domain_size / scale_size)))
        total_weighted_anisotropy += weight * scale_anisotropy
        total_weights += weight
    
    if total_weights > 0:
        effective_anisotropy = total_weighted_anisotropy / total_weights
    else:
        effective_anisotropy = 0.2  # Default
    
    return {'scale_dependent_anisotropy': effective_anisotropy, 'domain_size': domain_size, 'scales': scales}

def _calculate_comprehensive_lithostatic_stress(framework, point, depth, domain_bounds):
    # Integrate all framework components into final lithostatic stress tensor
    
    # Base lithostatic calculation
    density_profile = framework['density_distribution_analysis']['stratigraphic_density_profile']
    effective_density = density_profile['effective_density']
    g = 9.81  # m/s²
    
    # Vertical stress
    sigma_v = effective_density * g * depth
    
    # Apply gravitational field corrections
    gravity_effects = framework['gravitational_field_analysis']['gravity_anomaly_analysis']
    density_correction = gravity_effects['density_variation']
    corrected_density = effective_density + density_correction
    corrected_sigma_v = corrected_density * g * depth
    
    # Lateral stress coefficient
    lateral_analysis = framework['lateral_stress_analysis']['earth_pressure_coefficient']
    K0 = lateral_analysis['K0']
    base_sigma_h = K0 * corrected_sigma_v
    
    # Apply tectonic lateral stress
    tectonic_lateral = framework['lateral_stress_analysis']['tectonic_lateral_stress']
    sigma_H = base_sigma_h + tectonic_lateral['sigma_H_tectonic'] / 2  # Partial addition
    sigma_h = base_sigma_h + tectonic_lateral['sigma_h_tectonic'] / 2
    
    # Apply structural effects
    structural_effects = framework['structural_geology_analysis']['bedding_plane_effects']
    structural_factor = structural_effects['bedding_stress_factor']
    
    # Apply anisotropy
    anisotropy_analysis = framework['anisotropy_analysis']['stress_anisotropy_tensor']
    anisotropy_tensor = anisotropy_analysis['anisotropy_tensor']
    
    # Base isotropic tensor
    base_tensor = np.array([[sigma_H, 0, 0],
                           [0, sigma_h, 0],
                           [0, 0, corrected_sigma_v]])
    
    # Apply structural and anisotropic corrections
    final_tensor = base_tensor * structural_factor
    
    # Apply anisotropic transformation (simplified)
    anisotropic_correction = np.eye(3) + 0.1 * (anisotropy_tensor - np.eye(3))
    final_tensor = anisotropic_correction @ final_tensor @ anisotropic_correction.T
    
    return final_tensor

def _quantify_lithostatic_stress_uncertainty(stress_components, framework):
    # Comprehensive uncertainty quantification
    uncertainty_sources = {
        'density_uncertainty': 0.05,           # 5% uncertainty in density
        'depth_measurement_uncertainty': 0.02,  # 2% uncertainty in depth
        'lateral_stress_coefficient_uncertainty': 0.15,  # 15% uncertainty in K0
        'structural_effects_uncertainty': 0.10,  # 10% uncertainty in structural corrections
        'anisotropy_uncertainty': 0.20,        # 20% uncertainty in anisotropy
        'gravitational_field_uncertainty': 0.08, # 8% uncertainty in gravity corrections
        'model_uncertainty': 0.12              # 12% general model uncertainty
    }
    
    # Combine uncertainties using root sum of squares
    total_uncertainty = np.sqrt(sum(u**2 for u in uncertainty_sources.values()))
    
    # Depth-dependent uncertainty scaling
    depth = np.linalg.norm(stress_components) / 25000  # Approximate depth from stress magnitude
    depth_scaling = 1.0 + 0.3 * min(depth / 10000, 1.0)  # Increases with depth
    
    scaled_uncertainty = total_uncertainty * depth_scaling
    
    return {'total_uncertainty': scaled_uncertainty, 'uncertainty_sources': uncertainty_sources, 'depth_scaling': depth_scaling}

