# Comprehensive helper methods for multifractal spectrum analysis
def _calculate_holder_exponents(points):
    """Calculate local Hölder exponents for singularity analysis"""
    n_points = len(points)
    if n_points < 10:
        return {'mean_exponent': 1.0, 'exponent_range': [0.8, 1.2], 'exponent_std': 0.1}
    
    # Calculate local scaling exponents using wavelet transform
    scales = np.logspace(-2, 0, 20)  # From 0.01 to 1.0
    holder_exponents = []
    
    for i in range(min(100, n_points)):  # Sample subset for efficiency
        point = points[i]
        local_exponents = []
        
        for scale in scales:
            # Calculate local measure at different scales
            distances = np.linalg.norm(points - point, axis=1)
            neighbors = points[distances <= scale]
            
            if len(neighbors) > 1:
                local_density = len(neighbors) / (scale ** points.shape[1])
                if local_density > 0:
                    local_exponent = np.log(local_density) / np.log(scale)
                    local_exponents.append(local_exponent)
        
        if local_exponents:
            # Estimate Hölder exponent from scaling behavior
            holder_exp = np.mean(local_exponents[-5:]) if len(local_exponents) >= 5 else np.mean(local_exponents)
            holder_exponents.append(holder_exp)
    
    if holder_exponents:
        mean_exponent = np.mean(holder_exponents)
        exponent_std = np.std(holder_exponents)
        exponent_range = [np.min(holder_exponents), np.max(holder_exponents)]
    else:
        mean_exponent = 1.0
        exponent_std = 0.1
        exponent_range = [0.8, 1.2]
    
    return {'mean_exponent': mean_exponent, 'exponent_range': exponent_range, 'exponent_std': exponent_std}

def _calculate_singularity_strength(points):
    """Calculate singularity strength distribution"""
    n_points = len(points)
    singularity_strengths = []
    
    # Calculate local singularity strengths
    for i in range(min(50, n_points)):
        point = points[i]
        distances = np.linalg.norm(points - point, axis=1)
        
        # Find k-nearest neighbors for different k values
        k_values = [5, 10, 20, 50]
        local_strengths = []
        
        for k in k_values:
            if k < n_points:
                k_nearest_distances = np.partition(distances, k)[:k]
                if len(k_nearest_distances) > 0:
                    mean_distance = np.mean(k_nearest_distances)
                    if mean_distance > 0:
                        strength = -np.log(k / n_points) / np.log(mean_distance)
                        local_strengths.append(strength)
        
        if local_strengths:
            singularity_strengths.append(np.mean(local_strengths))
    
    if singularity_strengths:
        mean_strength = np.mean(singularity_strengths)
        strength_variance = np.var(singularity_strengths)
        strength_skewness = np.mean([(s - mean_strength)**3 for s in singularity_strengths]) / (strength_variance**1.5)
    else:
        mean_strength = 2.0
        strength_variance = 0.1
        strength_skewness = 0.0
    
    return {'mean_strength': mean_strength, 'strength_variance': strength_variance, 'strength_skewness': strength_skewness}

def _calculate_spectrum_support(points):
    """Calculate support of the multifractal spectrum"""
    n_points = len(points)
    
    # Estimate spectrum support from local scaling analysis
    scales = np.logspace(-2, 0, 10)
    alpha_values = []
    
    for i in range(min(30, n_points)):
        point = points[i]
        distances = np.linalg.norm(points - point, axis=1)
        
        scale_measures = []
        for scale in scales:
            neighbors = np.sum(distances <= scale)
            if neighbors > 0:
                measure = neighbors / n_points
                scale_measures.append((scale, measure))
        
        if len(scale_measures) > 3:
            # Linear regression in log-log space to estimate local alpha
            log_scales = [np.log(sm[0]) for sm in scale_measures]
            log_measures = [np.log(sm[1]) for sm in scale_measures]
            
            if len(log_scales) > 1:
                alpha = np.polyfit(log_scales, log_measures, 1)[0]
                alpha_values.append(alpha)
    
    if alpha_values:
        alpha_min = np.min(alpha_values)
        alpha_max = np.max(alpha_values)
        support_width = alpha_max - alpha_min
    else:
        alpha_min = 1.8
        alpha_max = 2.2
        support_width = 0.4
    
    return {'alpha_min': alpha_min, 'alpha_max': alpha_max, 'support_width': support_width}

def _calculate_spectrum_maximum(points):
    """Calculate maximum of the multifractal spectrum"""
    n_points = len(points)
    
    # The maximum typically occurs at the capacity dimension
    # Estimate using box-counting at multiple scales
    scales = np.logspace(-2, 0, 15)
    box_counts = []
    
    for scale in scales:
        # Create grid and count occupied boxes
        if points.shape[1] == 2:
            # 2D case
            x_min, x_max = np.min(points[:, 0]), np.max(points[:, 0])
            y_min, y_max = np.min(points[:, 1]), np.max(points[:, 1])
            
            x_bins = int((x_max - x_min) / scale) + 1
            y_bins = int((y_max - y_min) / scale) + 1
            
            occupied_boxes = set()
            for point in points:
                x_idx = int((point[0] - x_min) / scale)
                y_idx = int((point[1] - y_min) / scale)
                occupied_boxes.add((x_idx, y_idx))
            
            box_counts.append(len(occupied_boxes))
        else:
            # 3D case
            x_min, x_max = np.min(points[:, 0]), np.max(points[:, 0])
            y_min, y_max = np.min(points[:, 1]), np.max(points[:, 1])
            z_min, z_max = np.min(points[:, 2]), np.max(points[:, 2])
            
            occupied_boxes = set()
            for point in points:
                x_idx = int((point[0] - x_min) / scale)
                y_idx = int((point[1] - y_min) / scale)
                z_idx = int((point[2] - z_min) / scale)
                occupied_boxes.add((x_idx, y_idx, z_idx))
            
            box_counts.append(len(occupied_boxes))
    
    # Estimate capacity dimension from scaling
    if len(box_counts) > 3:
        log_scales = [-np.log(s) for s in scales]
        log_counts = [np.log(c) for c in box_counts if c > 0]
        
        if len(log_counts) > 3:
            capacity_dimension = np.polyfit(log_scales[:len(log_counts)], log_counts, 1)[0]
        else:
            capacity_dimension = points.shape[1]  # Default to embedding dimension
    else:
        capacity_dimension = points.shape[1]
    
    # Maximum f(alpha) typically equals the capacity dimension
    f_alpha_max = capacity_dimension
    alpha_max_location = capacity_dimension  # Alpha value where maximum occurs
    
    return {'f_alpha_max': f_alpha_max, 'alpha_at_max': alpha_max_location, 'capacity_dimension': capacity_dimension}

def _calculate_spectrum_asymmetry(points):
    """Calculate left-right asymmetry of the multifractal spectrum"""
    n_points = len(points)
    
    # Analyze distribution of local scaling exponents
    local_alphas = []
    
    for i in range(min(50, n_points)):
        point = points[i]
        distances = np.linalg.norm(points - point, axis=1)
        
        # Calculate local alpha using multiple scales
        scales = [0.1, 0.2, 0.3, 0.5]
        alphas_at_scales = []
        
        for scale in scales:
            neighbors = np.sum(distances <= scale)
            if neighbors > 1:
                density = neighbors / (n_points * scale ** points.shape[1])
                if density > 0:
                    alpha = np.log(density) / np.log(scale)
                    alphas_at_scales.append(alpha)
        
        if alphas_at_scales:
            local_alphas.append(np.mean(alphas_at_scales))
    
    if len(local_alphas) > 5:
        alpha_mean = np.mean(local_alphas)
        alpha_skewness = np.mean([(a - alpha_mean)**3 for a in local_alphas]) / (np.var(local_alphas)**1.5)
        
        # Left-right asymmetry measures
        left_tail = np.sum([1 for a in local_alphas if a < alpha_mean - np.std(local_alphas)])
        right_tail = np.sum([1 for a in local_alphas if a > alpha_mean + np.std(local_alphas)])
        
        asymmetry_ratio = (right_tail - left_tail) / len(local_alphas) if len(local_alphas) > 0 else 0
    else:
        alpha_skewness = 0.0
        asymmetry_ratio = 0.0
    
    return {'skewness': alpha_skewness, 'asymmetry_ratio': asymmetry_ratio, 'n_samples': len(local_alphas)}

def _calculate_multifractal_width(points):
    """Calculate width of the multifractal spectrum"""
    n_points = len(points)
    
    # Calculate generalized dimensions for different q values
    q_values = np.linspace(-5, 5, 21)
    dimensions = []
    
    scales = np.logspace(-2, 0, 10)
    
    for q in q_values:
        scale_sums = []
        
        for scale in scales:
            # Partition space and calculate generalized dimension
            if points.shape[1] == 2:
                # 2D partitioning
                x_min, x_max = np.min(points[:, 0]), np.max(points[:, 0])
                y_min, y_max = np.min(points[:, 1]), np.max(points[:, 1])
                
                grid_size = int(1/scale) + 1
                partition_probs = []
                
                for i in range(grid_size):
                    for j in range(grid_size):
                        x_left = x_min + i * scale * (x_max - x_min)
                        x_right = x_min + (i + 1) * scale * (x_max - x_min)
                        y_bottom = y_min + j * scale * (y_max - y_min)
                        y_top = y_min + (j + 1) * scale * (y_max - y_min)
                        
                        in_box = np.sum((points[:, 0] >= x_left) & (points[:, 0] < x_right) & 
                                       (points[:, 1] >= y_bottom) & (points[:, 1] < y_top))
                        
                        if in_box > 0:
                            prob = in_box / n_points
                            partition_probs.append(prob)
                
                if partition_probs and abs(q - 1.0) > 1e-6:
                    if q != 0:
                        sum_q = np.sum([p**q for p in partition_probs if p > 0])
                        scale_sums.append(sum_q)
        
        if len(scale_sums) > 3 and abs(q - 1.0) > 1e-6:
            log_scales = [np.log(s) for s in scales[:len(scale_sums)]]
            log_sums = [np.log(s) for s in scale_sums if s > 0]
            
            if len(log_sums) > 2:
                if q != 0:
                    tau_q = np.polyfit(log_scales[:len(log_sums)], log_sums, 1)[0] / (q - 1)
                    dimensions.append(tau_q)
    
    if len(dimensions) > 5:
        spectrum_width = np.max(dimensions) - np.min(dimensions)
        dimension_variance = np.var(dimensions)
    else:
        spectrum_width = 0.5
        dimension_variance = 0.1
    
    return {'spectrum_width': spectrum_width, 'dimension_variance': dimension_variance, 'n_dimensions': len(dimensions)}

def _calculate_generalized_dimensions(points):
    """Calculate generalized dimensions D_q for different q values"""
    n_points = len(points)
    q_values = np.array([-3, -2, -1, 0, 1, 2, 3, 4, 5])
    dimensions = {}
    
    scales = np.logspace(-2, 0, 8)
    
    for q in q_values:
        if abs(q) < 1e-6:  # q = 0 case (capacity dimension)
            # Box counting dimension
            box_counts = []
            for scale in scales:
                occupied_boxes = set()
                for point in points:
                    box_coords = tuple((point / scale).astype(int))
                    occupied_boxes.add(box_coords)
                box_counts.append(len(occupied_boxes))
            
            if len(box_counts) > 3:
                log_scales = [-np.log(s) for s in scales]
                log_counts = [np.log(c) for c in box_counts if c > 0]
                if len(log_counts) > 2:
                    D_0 = np.polyfit(log_scales[:len(log_counts)], log_counts, 1)[0]
                else:
                    D_0 = points.shape[1]
            else:
                D_0 = points.shape[1]
            dimensions[0] = D_0
            
        elif abs(q - 1) < 1e-6:  # q = 1 case (information dimension)
            info_measures = []
            for scale in scales:
                # Calculate information measure
                occupied_boxes = {}
                for point in points:
                    box_coords = tuple((point / scale).astype(int))
                    occupied_boxes[box_coords] = occupied_boxes.get(box_coords, 0) + 1
                
                total_points = sum(occupied_boxes.values())
                if total_points > 0:
                    entropy = -sum((count/total_points) * np.log(count/total_points) 
                                 for count in occupied_boxes.values() if count > 0)
                    info_measures.append(entropy)
            
            if len(info_measures) > 3:
                log_scales = [np.log(s) for s in scales[:len(info_measures)]]
                D_1 = np.polyfit(log_scales, info_measures, 1)[0]
            else:
                D_1 = points.shape[1] - 0.1
            dimensions[1] = D_1
            
        else:  # General q case
            generalized_measures = []
            for scale in scales:
                occupied_boxes = {}
                for point in points:
                    box_coords = tuple((point / scale).astype(int))
                    occupied_boxes[box_coords] = occupied_boxes.get(box_coords, 0) + 1
                
                total_points = sum(occupied_boxes.values())
                if total_points > 0:
                    sum_pq = sum((count/total_points)**q for count in occupied_boxes.values())
                    if sum_pq > 0:
                        generalized_measures.append(np.log(sum_pq))
            
            if len(generalized_measures) > 3:
                log_scales = [np.log(s) for s in scales[:len(generalized_measures)]]
                if len(log_scales) == len(generalized_measures):
                    slope = np.polyfit(log_scales, generalized_measures, 1)[0]
                    D_q = slope / (q - 1)
                    dimensions[q] = D_q
    
    return dimensions

def _calculate_mass_exponents(points):
    """Calculate mass exponents tau(q)"""
    generalized_dims = _calculate_generalized_dimensions(points)
    
    mass_exponents = {}
    for q, D_q in generalized_dims.items():
        tau_q = (q - 1) * D_q
        mass_exponents[q] = tau_q
    
    # Calculate derivatives for spectrum analysis
    q_values = sorted(generalized_dims.keys())
    if len(q_values) > 3:
        tau_values = [mass_exponents[q] for q in q_values]
        # Numerical derivative
        tau_derivative = np.gradient(tau_values, q_values)
        tau_second_derivative = np.gradient(tau_derivative, q_values)
    else:
        tau_derivative = [2.0] * len(q_values)
        tau_second_derivative = [0.1] * len(q_values)
    
    return {'mass_exponents': mass_exponents, 'tau_derivative': tau_derivative, 'tau_second_derivative': tau_second_derivative}

def _calculate_scaling_exponents(points):
    """Calculate scaling exponents from structure functions"""
    n_points = len(points)
    
    # Calculate structure functions S_q(r) for different orders q
    q_orders = [1, 2, 3, 4, 5, 6]
    scales = np.logspace(-2, 0, 10)
    
    scaling_exponents = {}
    
    for q in q_orders:
        structure_functions = []
        
        for scale in scales:
            # Calculate q-th order structure function
            structure_sum = 0
            pair_count = 0
            
            for i in range(min(100, n_points)):
                for j in range(i+1, min(i+50, n_points)):
                    distance = np.linalg.norm(points[i] - points[j])
                    if distance <= scale and distance > 0:
                        structure_sum += distance**q
                        pair_count += 1
            
            if pair_count > 0:
                avg_structure = structure_sum / pair_count
                structure_functions.append(avg_structure)
        
        if len(structure_functions) > 3:
            log_scales = [np.log(s) for s in scales[:len(structure_functions)]]
            log_functions = [np.log(sf) for sf in structure_functions if sf > 0]
            
            if len(log_functions) > 2:
                zeta_q = np.polyfit(log_scales[:len(log_functions)], log_functions, 1)[0]
                scaling_exponents[q] = zeta_q
    
    return scaling_exponents

def _calculate_moment_statistics(points):
    """Calculate statistical moments of the point distribution"""
    n_points = len(points)
    
    # Calculate spatial moments
    center = np.mean(points, axis=0)
    centered_points = points - center
    
    # Second-order moments (covariance matrix)
    covariance_matrix = np.cov(centered_points.T)
    eigenvals, eigenvecs = np.linalg.eigh(covariance_matrix)
    
    # Higher-order moments
    moments = {}
    for order in range(2, 7):
        moment_tensor = np.zeros([points.shape[1]] * order)
        for point in centered_points:
            for indices in np.ndindex(moment_tensor.shape):
                moment_value = 1.0
                for i, idx in enumerate(indices):
                    moment_value *= point[idx]
                moment_tensor[indices] += moment_value
        
        moment_tensor /= n_points
        moments[order] = np.mean(np.abs(moment_tensor))  # Average absolute moment
    
    # Anisotropy measures
    anisotropy_ratio = np.max(eigenvals) / np.min(eigenvals) if np.min(eigenvals) > 0 else 1.0
    
    return {'moments': moments, 'covariance_eigenvals': eigenvals, 'anisotropy_ratio': anisotropy_ratio}

def _calculate_renyi_dimensions(points):
    """Calculate Rényi dimensions for different alpha values"""
    n_points = len(points)
    alpha_values = [0.5, 1.0, 1.5, 2.0, 3.0, 5.0, np.inf]
    
    scales = np.logspace(-2, 0, 8)
    renyi_dims = {}
    
    for alpha in alpha_values:
        if alpha == np.inf:
            # Min-entropy (correlation dimension)
            correlation_sums = []
            for scale in scales:
                pair_count = 0
                for i in range(min(100, n_points)):
                    for j in range(i+1, n_points):
                        if np.linalg.norm(points[i] - points[j]) <= scale:
                            pair_count += 1
                correlation_sums.append(pair_count)
            
            if len(correlation_sums) > 3:
                log_scales = [np.log(s) for s in scales]
                log_sums = [np.log(s) for s in correlation_sums if s > 0]
                if len(log_sums) > 2:
                    D_inf = np.polyfit(log_scales[:len(log_sums)], log_sums, 1)[0]
                    renyi_dims[alpha] = D_inf
        
        elif alpha == 1.0:
            # Shannon entropy (information dimension)
            info_entropies = []
            for scale in scales:
                occupied_boxes = {}
                for point in points:
                    box_coords = tuple((point / scale).astype(int))
                    occupied_boxes[box_coords] = occupied_boxes.get(box_coords, 0) + 1
                
                total = sum(occupied_boxes.values())
                if total > 0:
                    entropy = -sum((count/total) * np.log(count/total) 
                                 for count in occupied_boxes.values() if count > 0)
                    info_entropies.append(entropy)
            
            if len(info_entropies) > 3:
                log_scales = [np.log(s) for s in scales[:len(info_entropies)]]
                D_1 = np.polyfit(log_scales, info_entropies, 1)[0]
                renyi_dims[1.0] = D_1
        
        else:
            # General Rényi dimension
            renyi_entropies = []
            for scale in scales:
                occupied_boxes = {}
                for point in points:
                    box_coords = tuple((point / scale).astype(int))
                    occupied_boxes[box_coords] = occupied_boxes.get(box_coords, 0) + 1
                
                total = sum(occupied_boxes.values())
                if total > 0:
                    sum_p_alpha = sum((count/total)**alpha for count in occupied_boxes.values())
                    if sum_p_alpha > 0:
                        renyi_entropy = np.log(sum_p_alpha) / (1 - alpha)
                        renyi_entropies.append(renyi_entropy)
            
            if len(renyi_entropies) > 3:
                log_scales = [np.log(s) for s in scales[:len(renyi_entropies)]]
                D_alpha = np.polyfit(log_scales, renyi_entropies, 1)[0]
                renyi_dims[alpha] = D_alpha
    
    return renyi_dims

def _calculate_legendre_transform(points):
    """Calculate Legendre transform to get f(alpha) spectrum"""
    mass_exp_data = _calculate_mass_exponents(points)
    mass_exponents = mass_exp_data['mass_exponents']
    
    # Perform Legendre transform: f(alpha) = q*alpha - tau(q)
    q_values = sorted(mass_exponents.keys())
    spectrum_points = []
    
    for q in q_values:
        tau_q = mass_exponents[q]
        # alpha = d(tau)/dq (numerical derivative)
        if len(q_values) > 2:
            q_idx = q_values.index(q)
            if 0 < q_idx < len(q_values) - 1:
                q_prev, q_next = q_values[q_idx-1], q_values[q_idx+1]
                tau_prev, tau_next = mass_exponents[q_prev], mass_exponents[q_next]
                alpha = (tau_next - tau_prev) / (q_next - q_prev)
            else:
                alpha = 2.0  # Default value
        else:
            alpha = 2.0
        
        f_alpha = q * alpha - tau_q
        spectrum_points.append((alpha, f_alpha))
    
    # Extract spectrum characteristics
    if spectrum_points:
        alphas, f_alphas = zip(*spectrum_points)
        spectrum_width = max(alphas) - min(alphas)
        max_f_alpha = max(f_alphas)
        spectrum_center = alphas[f_alphas.index(max_f_alpha)]
    else:
        spectrum_width = 0.5
        max_f_alpha = 2.0
        spectrum_center = 2.0
    
    return {'spectrum_points': spectrum_points, 'spectrum_width': spectrum_width, 
            'max_f_alpha': max_f_alpha, 'spectrum_center': spectrum_center}

def _calculate_capacity_dimension(points):
    """Calculate capacity (box-counting) dimension"""
    scales = np.logspace(-2, 0, 15)
    box_counts = []
    
    for scale in scales:
        occupied_boxes = set()
        for point in points:
            box_coords = tuple((point / scale).astype(int))
            occupied_boxes.add(box_coords)
        box_counts.append(len(occupied_boxes))
    
    if len(box_counts) > 5:
        log_scales = [-np.log(s) for s in scales]
        log_counts = [np.log(c) for c in box_counts if c > 0]
        
        if len(log_counts) > 3:
            capacity_dim = np.polyfit(log_scales[:len(log_counts)], log_counts, 1)[0]
            correlation_coeff = np.corrcoef(log_scales[:len(log_counts)], log_counts)[0, 1]**2
        else:
            capacity_dim = points.shape[1]
            correlation_coeff = 0.5
    else:
        capacity_dim = points.shape[1]
        correlation_coeff = 0.5
    
    return {'dimension': capacity_dim, 'correlation_coeff': correlation_coeff, 'n_scales': len(box_counts)}

def _calculate_information_dimension(points):
    """Calculate information dimension"""
    n_points = len(points)
    scales = np.logspace(-2, 0, 12)
    information_measures = []
    
    for scale in scales:
        # Calculate Shannon entropy of box probabilities
        occupied_boxes = {}
        for point in points:
            box_coords = tuple((point / scale).astype(int))
            occupied_boxes[box_coords] = occupied_boxes.get(box_coords, 0) + 1
        
        total_points = sum(occupied_boxes.values())
        if total_points > 0:
            shannon_entropy = -sum((count/total_points) * np.log(count/total_points) 
                                 for count in occupied_boxes.values() if count > 0)
            information_measures.append(shannon_entropy)
    
    if len(information_measures) > 5:
        log_scales = [np.log(s) for s in scales[:len(information_measures)]]
        info_dim = np.polyfit(log_scales, information_measures, 1)[0]
        fit_quality = np.corrcoef(log_scales, information_measures)[0, 1]**2
    else:
        info_dim = points.shape[1] - 0.1
        fit_quality = 0.5
    
    return {'dimension': info_dim, 'fit_quality': fit_quality, 'n_measurements': len(information_measures)}

def _calculate_correlation_dimension(points):
    """Calculate correlation dimension using Grassberger-Procaccia algorithm"""
    n_points = len(points)
    scales = np.logspace(-2, 0, 12)
    correlation_integrals = []
    
    for scale in scales:
        correlation_sum = 0
        total_pairs = 0
        
        # Sample pairs for efficiency
        sample_size = min(200, n_points)
        indices = np.random.choice(n_points, sample_size, replace=False)
        
        for i in range(len(indices)):
            for j in range(i+1, len(indices)):
                distance = np.linalg.norm(points[indices[i]] - points[indices[j]])
                if distance <= scale:
                    correlation_sum += 1
                total_pairs += 1
        
        if total_pairs > 0:
            correlation_integral = correlation_sum / total_pairs
            correlation_integrals.append(correlation_integral)
    
    if len(correlation_integrals) > 5:
        log_scales = [np.log(s) for s in scales[:len(correlation_integrals)]]
        log_integrals = [np.log(ci) for ci in correlation_integrals if ci > 0]
        
        if len(log_integrals) > 3:
            correlation_dim = np.polyfit(log_scales[:len(log_integrals)], log_integrals, 1)[0]
            scaling_quality = np.corrcoef(log_scales[:len(log_integrals)], log_integrals)[0, 1]**2
        else:
            correlation_dim = points.shape[1] - 0.2
            scaling_quality = 0.5
    else:
        correlation_dim = points.shape[1] - 0.2
        scaling_quality = 0.5
    
    return {'dimension': correlation_dim, 'scaling_quality': scaling_quality}

def _calculate_box_counting_scaling(points):
    """Analyze box-counting scaling properties"""
    scales = np.logspace(-2, 0, 20)
    scaling_data = []
    
    for scale in scales:
        occupied_boxes = set()
        total_boxes = 0
        
        # Calculate bounding box
        mins = np.min(points, axis=0)
        maxs = np.max(points, axis=0)
        
        # Count boxes
        for point in points:
            box_coords = tuple(((point - mins) / scale).astype(int))
            occupied_boxes.add(box_coords)
        
        # Estimate total possible boxes
        total_possible = np.prod(np.ceil((maxs - mins) / scale).astype(int))
        
        scaling_data.append({
            'scale': scale,
            'occupied_boxes': len(occupied_boxes),
            'total_possible': total_possible,
            'occupation_ratio': len(occupied_boxes) / total_possible if total_possible > 0 else 0
        })
    
    # Analyze scaling regimes
    if len(scaling_data) > 10:
        scales_array = [sd['scale'] for sd in scaling_data]
        counts_array = [sd['occupied_boxes'] for sd in scaling_data]
        
        log_scales = [-np.log(s) for s in scales_array]
        log_counts = [np.log(c) for c in counts_array if c > 0]
        
        # Fit different regimes
        n_mid = len(log_counts) // 2
        if n_mid > 3:
            # Small scale regime
            small_scale_slope = np.polyfit(log_scales[:n_mid], log_counts[:n_mid], 1)[0]
            # Large scale regime
            large_scale_slope = np.polyfit(log_scales[n_mid:], log_counts[n_mid:], 1)[0]
        else:
            small_scale_slope = points.shape[1]
            large_scale_slope = points.shape[1]
    else:
        small_scale_slope = points.shape[1]
        large_scale_slope = points.shape[1]
    
    return {'small_scale_dimension': small_scale_slope, 'large_scale_dimension': large_scale_slope, 'scaling_data': scaling_data}

def _calculate_finite_size_scaling(points):
    """Analyze finite size effects in scaling"""
    n_points = len(points)
    
    # Analyze scaling for different subset sizes
    subset_sizes = [max(20, n_points//4), max(50, n_points//2), n_points]
    finite_size_effects = {}
    
    for subset_size in subset_sizes:
        if subset_size <= n_points:
            # Random subset
            indices = np.random.choice(n_points, subset_size, replace=False)
            subset_points = points[indices]
            
            # Calculate capacity dimension for subset
            capacity_result = _calculate_capacity_dimension(subset_points)
            finite_size_effects[subset_size] = capacity_result['dimension']
    
    # Analyze convergence
    sizes = sorted(finite_size_effects.keys())
    dimensions = [finite_size_effects[s] for s in sizes]
    
    if len(dimensions) > 2:
        # Estimate infinite-size limit
        size_reciprocals = [1.0/s for s in sizes]
        finite_size_slope = np.polyfit(size_reciprocals, dimensions, 1)[0]
        infinite_limit = dimensions[-1] - finite_size_slope * (1.0/sizes[-1])
    else:
        infinite_limit = dimensions[-1] if dimensions else points.shape[1]
        finite_size_slope = 0
    
    return {'finite_size_effects': finite_size_effects, 'infinite_limit': infinite_limit, 'finite_size_slope': finite_size_slope}

def _calculate_multiscale_box_counting(points):
    """Comprehensive multiscale box-counting analysis"""
    # Multiple scale ranges for different physics
    scale_ranges = {
        'microscale': np.logspace(-3, -1, 10),
        'mesoscale': np.logspace(-1.5, -0.5, 10), 
        'macroscale': np.logspace(-0.8, 0, 10)
    }
    
    multiscale_results = {}
    
    for scale_type, scales in scale_ranges.items():
        box_counts = []
        for scale in scales:
            occupied_boxes = set()
            for point in points:
                box_coords = tuple((point / scale).astype(int))
                occupied_boxes.add(box_coords)
            box_counts.append(len(occupied_boxes))
        
        if len(box_counts) > 5:
            log_scales = [-np.log(s) for s in scales]
            log_counts = [np.log(c) for c in box_counts if c > 0]
            
            if len(log_counts) > 3:
                dimension = np.polyfit(log_scales[:len(log_counts)], log_counts, 1)[0]
                fit_quality = np.corrcoef(log_scales[:len(log_counts)], log_counts)[0, 1]**2
            else:
                dimension = points.shape[1]
                fit_quality = 0.5
        else:
            dimension = points.shape[1]
            fit_quality = 0.5
        
        multiscale_results[scale_type] = {'dimension': dimension, 'fit_quality': fit_quality}
    
    return multiscale_results

def _calculate_grassberger_procaccia_dimension(points):
    """Detailed Grassberger-Procaccia correlation dimension analysis"""
    n_points = len(points)
    
    # Multiple scale ranges for robust estimation
    scales = np.logspace(-2, 0, 20)
    correlation_data = []
    
    for scale in scales:
        # Calculate correlation integral C(r)
        correlation_count = 0
        total_pairs = 0
        
        # Use efficient sampling for large datasets
        sample_size = min(300, n_points)
        if n_points > sample_size:
            indices = np.random.choice(n_points, sample_size, replace=False)
            sample_points = points[indices]
        else:
            sample_points = points
        
        for i in range(len(sample_points)):
            for j in range(i+1, len(sample_points)):
                distance = np.linalg.norm(sample_points[i] - sample_points[j])
                if distance <= scale:
                    correlation_count += 1
                total_pairs += 1
        
        correlation_integral = correlation_count / total_pairs if total_pairs > 0 else 0
        
        correlation_data.append({
            'scale': scale,
            'correlation_integral': correlation_integral,
            'pair_count': total_pairs
        })
    
    # Extract scaling region
    valid_data = [cd for cd in correlation_data if cd['correlation_integral'] > 0]
    
    if len(valid_data) > 8:
        log_scales = [np.log(cd['scale']) for cd in valid_data]
        log_integrals = [np.log(cd['correlation_integral']) for cd in valid_data]
        
        # Find best linear scaling region
        best_r2 = 0
        best_dimension = points.shape[1]
        
        for start_idx in range(len(valid_data)//3):
            for end_idx in range(2*len(valid_data)//3, len(valid_data)):
                if end_idx - start_idx > 5:
                    scale_segment = log_scales[start_idx:end_idx]
                    integral_segment = log_integrals[start_idx:end_idx]
                    
                    correlation_dim = np.polyfit(scale_segment, integral_segment, 1)[0]
                    r_squared = np.corrcoef(scale_segment, integral_segment)[0, 1]**2
                    
                    if r_squared > best_r2:
                        best_r2 = r_squared
                        best_dimension = correlation_dim
    else:
        best_dimension = points.shape[1] - 0.2
        best_r2 = 0.5
    
    return {'dimension': best_dimension, 'r_squared': best_r2, 'n_valid_scales': len(valid_data)}

def _calculate_correlation_integral(points):
    """Calculate correlation integral at multiple scales"""
    n_points = len(points)
    scales = np.logspace(-2, 0, 15)
    
    correlation_integrals = []
    
    for scale in scales:
        integral_sum = 0
        
        # Efficient pairwise distance calculation
        for i in range(min(200, n_points)):
            distances = np.linalg.norm(points - points[i], axis=1)
            neighbors = np.sum(distances <= scale) - 1  # Exclude self
            integral_sum += neighbors
        
        average_integral = integral_sum / min(200, n_points) / (n_points - 1)
        correlation_integrals.append(average_integral)
    
    # Analyze integral properties
    if correlation_integrals:
        integral_mean = np.mean(correlation_integrals)
        integral_variance = np.var(correlation_integrals)
        integral_skewness = np.mean([(ci - integral_mean)**3 for ci in correlation_integrals]) / (integral_variance**1.5)
    else:
        integral_mean = 0.1
        integral_variance = 0.01
        integral_skewness = 0.0
    
    return {'integrals': correlation_integrals, 'mean': integral_mean, 'variance': integral_variance, 'skewness': integral_skewness}

def _calculate_embedding_dimension(points):
    """Estimate proper embedding dimension using false nearest neighbors"""
    n_points = len(points)
    current_dim = points.shape[1]
    
    # Test for false nearest neighbors
    test_dimensions = range(current_dim, min(current_dim + 5, 10))
    false_neighbor_ratios = []
    
    for test_dim in test_dimensions:
        if test_dim > current_dim:
            # Extend points with noise for higher dimensions
            extended_points = np.column_stack([
                points, 
                np.random.normal(0, 0.1, (n_points, test_dim - current_dim))
            ])
        else:
            extended_points = points
        
        # Find nearest neighbors and check for false neighbors
        false_count = 0
        total_count = 0
        
        for i in range(min(100, n_points)):
            distances = np.linalg.norm(extended_points - extended_points[i], axis=1)
            neighbor_idx = np.argsort(distances)[1]  # Closest neighbor (excluding self)
            
            if neighbor_idx < len(extended_points):
                # Check if neighbor is false in higher dimension
                current_distance = np.linalg.norm(points[i] - points[neighbor_idx])
                extended_distance = distances[neighbor_idx]
                
                if extended_distance > 2 * current_distance:
                    false_count += 1
                total_count += 1
        
        false_ratio = false_count / total_count if total_count > 0 else 0
        false_neighbor_ratios.append(false_ratio)
    
    # Estimate embedding dimension where false neighbors drop significantly
    if len(false_neighbor_ratios) > 2:
        min_false_ratio = min(false_neighbor_ratios)
        optimal_dim_idx = false_neighbor_ratios.index(min_false_ratio)
        optimal_embedding_dim = test_dimensions[optimal_dim_idx]
    else:
        optimal_embedding_dim = current_dim
    
    return {'optimal_dimension': optimal_embedding_dim, 'false_neighbor_ratios': false_neighbor_ratios}

def _calculate_saturation_analysis(points):
    """Analyze dimension saturation with increasing embedding dimension"""
    n_points = len(points)
    current_dim = points.shape[1]
    
    # Test dimensions up to reasonable limit
    test_dims = range(current_dim, min(current_dim + 8, 15))
    dimension_estimates = []
    
    for test_dim in test_dims:
        if test_dim > current_dim:
            # Extend with time-delay embedding or noise
            extended_points = np.column_stack([
                points,
                np.random.normal(0, 0.05, (n_points, test_dim - current_dim))
            ])
        else:
            extended_points = points
        
        # Calculate correlation dimension
        corr_result = _calculate_correlation_dimension(extended_points)
        dimension_estimates.append(corr_result['dimension'])
    
    # Find saturation point
    if len(dimension_estimates) > 3:
        # Look for plateau in dimension estimates
        dimension_differences = np.diff(dimension_estimates)
        saturation_threshold = 0.1
        
        saturation_index = None
        for i, diff in enumerate(dimension_differences):
            if abs(diff) < saturation_threshold:
                saturation_index = i
                break
        
        if saturation_index is not None:
            saturated_dimension = dimension_estimates[saturation_index]
        else:
            saturated_dimension = dimension_estimates[-1]
    else:
        saturated_dimension = current_dim
    
    return {'saturated_dimension': saturated_dimension, 'dimension_estimates': dimension_estimates}

def _calculate_noise_reduction_effects(points):
    """Analyze effects of noise on dimension estimation"""
    n_points = len(points)
    
    # Add different levels of noise and measure dimension changes
    noise_levels = [0.0, 0.01, 0.05, 0.1, 0.2]
    noisy_dimensions = []
    
    for noise_level in noise_levels:
        if noise_level > 0:
            noise = np.random.normal(0, noise_level, points.shape)
            noisy_points = points + noise
        else:
            noisy_points = points
        
        # Calculate capacity dimension
        capacity_result = _calculate_capacity_dimension(noisy_points)
        noisy_dimensions.append(capacity_result['dimension'])
    
    # Analyze noise sensitivity
    if len(noisy_dimensions) > 3:
        clean_dimension = noisy_dimensions[0]
        dimension_changes = [nd - clean_dimension for nd in noisy_dimensions]
        noise_sensitivity = np.max(np.abs(dimension_changes))
        
        # Estimate noise threshold where dimension significantly changes
        threshold_noise = 0.1
        for i, change in enumerate(dimension_changes):
            if abs(change) > 0.2:  # 20% change threshold
                threshold_noise = noise_levels[i]
                break
    else:
        noise_sensitivity = 0.1
        threshold_noise = 0.1
    
    return {'noise_sensitivity': noise_sensitivity, 'threshold_noise': threshold_noise, 'dimension_vs_noise': noisy_dimensions}

def _calculate_convergence_analysis(points):
    """Analyze convergence of dimension estimates"""
    n_points = len(points)
    
    # Calculate dimensions for increasing sample sizes
    sample_sizes = [max(20, n_points//8), max(50, n_points//4), max(100, n_points//2), n_points]
    convergence_data = []
    
    for sample_size in sample_sizes:
        if sample_size <= n_points:
            # Random subsample
            indices = np.random.choice(n_points, sample_size, replace=False)
            subset = points[indices]
            
            # Calculate multiple dimension estimates
            capacity_dim = _calculate_capacity_dimension(subset)['dimension']
            correlation_dim = _calculate_correlation_dimension(subset)['dimension']
            
            convergence_data.append({
                'sample_size': sample_size,
                'capacity_dimension': capacity_dim,
                'correlation_dimension': correlation_dim
            })
    
    # Analyze convergence trends
    if len(convergence_data) > 2:
        capacity_dims = [cd['capacity_dimension'] for cd in convergence_data]
        correlation_dims = [cd['correlation_dimension'] for cd in convergence_data]
        
        # Estimate convergence rate
        capacity_variance = np.var(capacity_dims)
        correlation_variance = np.var(correlation_dims)
        
        # Check if dimensions stabilize
        capacity_stable = capacity_variance < 0.1
        correlation_stable = correlation_variance < 0.1
    else:
        capacity_stable = False
        correlation_stable = False
        capacity_variance = 1.0
        correlation_variance = 1.0
    
    return {'convergence_data': convergence_data, 'capacity_stable': capacity_stable, 
            'correlation_stable': correlation_stable, 'capacity_variance': capacity_variance}

def _calculate_lacunarity_curves(points):
    """Calculate lacunarity curves at multiple scales"""
    n_points = len(points)
    scales = np.logspace(-2, 0, 12)
    lacunarity_values = []
    
    for scale in scales:
        # Grid-based lacunarity calculation
        occupied_boxes = {}
        
        for point in points:
            box_coords = tuple((point / scale).astype(int))
            occupied_boxes[box_coords] = occupied_boxes.get(box_coords, 0) + 1
        
        # Calculate moments of box mass distribution
        masses = list(occupied_boxes.values())
        if masses:
            first_moment = np.mean(masses)
            second_moment = np.mean([m**2 for m in masses])
            
            if first_moment > 0:
                lacunarity = second_moment / (first_moment**2)
            else:
                lacunarity = 1.0
        else:
            lacunarity = 1.0
        
        lacunarity_values.append(lacunarity)
    
    # Analyze lacunarity properties
    if lacunarity_values:
        max_lacunarity = max(lacunarity_values)
        min_lacunarity = min(lacunarity_values)
        lacunarity_range = max_lacunarity - min_lacunarity
        
        # Find scale at maximum lacunarity
        max_lac_scale = scales[lacunarity_values.index(max_lacunarity)]
    else:
        max_lacunarity = 1.0
        min_lacunarity = 1.0
        lacunarity_range = 0.0
        max_lac_scale = 0.1
    
    return {'lacunarity_curve': lacunarity_values, 'scales': scales, 
            'max_lacunarity': max_lacunarity, 'lacunarity_range': lacunarity_range,
            'max_lacunarity_scale': max_lac_scale}

def _calculate_gap_size_distribution(points):
    """Calculate distribution of gap sizes between points"""
    n_points = len(points)
    
    # Calculate nearest neighbor distances
    neighbor_distances = []
    
    for i in range(min(200, n_points)):
        distances = np.linalg.norm(points - points[i], axis=1)
        nearest_distance = np.sort(distances)[1]  # Exclude self (distance=0)
        neighbor_distances.append(nearest_distance)
    
    if neighbor_distances:
        # Analyze gap size distribution
        gap_mean = np.mean(neighbor_distances)
        gap_std = np.std(neighbor_distances)
        gap_skewness = np.mean([(d - gap_mean)**3 for d in neighbor_distances]) / (gap_std**3)
        gap_kurtosis = np.mean([(d - gap_mean)**4 for d in neighbor_distances]) / (gap_std**4) - 3
        
        # Calculate distribution parameters
        gap_histogram, bin_edges = np.histogram(neighbor_distances, bins=20)
        gap_entropy = -sum((count/len(neighbor_distances)) * np.log(count/len(neighbor_distances)) 
                          for count in gap_histogram if count > 0)
    else:
        gap_mean = 0.1
        gap_std = 0.05
        gap_skewness = 0.0
        gap_kurtosis = 0.0
        gap_entropy = 1.0
    
    return {'gap_mean': gap_mean, 'gap_std': gap_std, 'gap_skewness': gap_skewness, 
            'gap_kurtosis': gap_kurtosis, 'gap_entropy': gap_entropy}

def _calculate_rotational_invariance(points):
    """Test rotational invariance of fractal properties"""
    n_points = len(points)
    
    # Test different rotation angles
    rotation_angles = [0, np.pi/6, np.pi/4, np.pi/3, np.pi/2]
    rotated_dimensions = []
    
    for angle in rotation_angles:
        if points.shape[1] >= 2:
            # 2D rotation matrix
            rotation_matrix = np.array([[np.cos(angle), -np.sin(angle)],
                                      [np.sin(angle), np.cos(angle)]])
            
            if points.shape[1] == 2:
                rotated_points = points @ rotation_matrix.T
            else:
                # Rotate only first two dimensions
                rotated_points = points.copy()
                rotated_points[:, :2] = points[:, :2] @ rotation_matrix.T
        else:
            rotated_points = points
        
        # Calculate capacity dimension for rotated points
        capacity_result = _calculate_capacity_dimension(rotated_points)
        rotated_dimensions.append(capacity_result['dimension'])
    
    # Analyze rotational stability
    if len(rotated_dimensions) > 2:
        dimension_variance = np.var(rotated_dimensions)
        max_dimension_change = max(rotated_dimensions) - min(rotated_dimensions)
        rotational_stability = 1.0 - min(1.0, dimension_variance)
    else:
        max_dimension_change = 0.0
        rotational_stability = 1.0
    
    return {'rotated_dimensions': rotated_dimensions, 'dimension_variance': dimension_variance,
            'max_change': max_dimension_change, 'rotational_stability': rotational_stability}

def _calculate_scale_dependent_lacunarity(points):
    """Calculate scale-dependent lacunarity measures"""
    scales = np.logspace(-2, 0, 15)
    scale_lacunarities = {}
    
    for scale_idx, scale in enumerate(scales):
        # Multi-scale lacunarity analysis
        gliding_box_lacunarities = []
        
        # Multiple box positions for each scale
        n_positions = 20
        for pos in range(n_positions):
            # Random box position
            if len(points) > 0:
                center = points[np.random.choice(len(points))]
                
                # Count points in box
                distances = np.linalg.norm(points - center, axis=1)
                points_in_box = np.sum(distances <= scale)
                
                # Local lacunarity contribution
                local_density = points_in_box / len(points)
                gliding_box_lacunarities.append(local_density)
        
        # Calculate lacunarity for this scale
        if gliding_box_lacunarities:
            mean_density = np.mean(gliding_box_lacunarities)
            density_variance = np.var(gliding_box_lacunarities)
            
            if mean_density > 0:
                lacunarity = 1 + density_variance / (mean_density**2)
            else:
                lacunarity = 1.0
        else:
            lacunarity = 1.0
        
        scale_lacunarities[scale] = lacunarity
    
    # Analyze scale dependence
    lacunarity_list = list(scale_lacunarities.values())
    if lacunarity_list:
        lacunarity_trend = np.polyfit(range(len(lacunarity_list)), lacunarity_list, 1)[0]
        lacunarity_variability = np.var(lacunarity_list)
    else:
        lacunarity_trend = 0.0
        lacunarity_variability = 0.0
    
    return {'scale_lacunarities': scale_lacunarities, 'lacunarity_trend': lacunarity_trend, 
            'lacunarity_variability': lacunarity_variability}

def _calculate_texture_analysis(points):
    """Analyze texture properties of point distribution"""
    n_points = len(points)
    
    # Calculate local density variations (texture measures)
    texture_scales = [0.1, 0.2, 0.5]
    texture_measures = {}
    
    for scale in texture_scales:
        local_densities = []
        
        # Sample points for texture analysis
        sample_points = points[:min(100, n_points)]
        
        for point in sample_points:
            distances = np.linalg.norm(points - point, axis=1)
            neighbors = np.sum(distances <= scale)
            local_density = neighbors / (np.pi * scale**2) if points.shape[1] == 2 else neighbors / ((4/3) * np.pi * scale**3)
            local_densities.append(local_density)
        
        if local_densities:
            # Texture statistics
            density_mean = np.mean(local_densities)
            density_contrast = np.std(local_densities) / density_mean if density_mean > 0 else 0
            density_energy = np.mean([d**2 for d in local_densities])
            density_entropy = -sum((d/sum(local_densities)) * np.log(d/sum(local_densities) + 1e-10) 
                                 for d in local_densities if d > 0)
            
            texture_measures[scale] = {
                'contrast': density_contrast,
                'energy': density_energy,
                'entropy': density_entropy,
                'homogeneity': 1.0 / (1.0 + density_contrast)
            }
    
    # Overall texture characterization
    if texture_measures:
        avg_contrast = np.mean([tm['contrast'] for tm in texture_measures.values()])
        avg_entropy = np.mean([tm['entropy'] for tm in texture_measures.values()])
        avg_homogeneity = np.mean([tm['homogeneity'] for tm in texture_measures.values()])
    else:
        avg_contrast = 0.5
        avg_entropy = 1.0
        avg_homogeneity = 0.7
    
    return {'texture_measures': texture_measures, 'avg_contrast': avg_contrast, 
            'avg_entropy': avg_entropy, 'avg_homogeneity': avg_homogeneity}

def _calculate_clustering_coefficients(points):
    """Calculate clustering coefficients for different scales"""
    n_points = len(points)
    scales = [0.1, 0.2, 0.3, 0.5]
    clustering_coefficients = {}
    
    for scale in scales:
        total_clustering = 0
        nodes_with_neighbors = 0
        
        # Sample subset for efficiency
        sample_size = min(100, n_points)
        sample_indices = np.random.choice(n_points, sample_size, replace=False)
        
        for i in sample_indices:
            # Find neighbors within scale
            distances = np.linalg.norm(points - points[i], axis=1)
            neighbor_indices = np.where((distances <= scale) & (distances > 0))[0]
            
            if len(neighbor_indices) > 1:
                # Count connections between neighbors
                neighbor_connections = 0
                possible_connections = len(neighbor_indices) * (len(neighbor_indices) - 1) / 2
                
                for j in range(len(neighbor_indices)):
                    for k in range(j+1, len(neighbor_indices)):
                        neighbor_dist = np.linalg.norm(points[neighbor_indices[j]] - points[neighbor_indices[k]])
                        if neighbor_dist <= scale:
                            neighbor_connections += 1
                
                local_clustering = neighbor_connections / possible_connections if possible_connections > 0 else 0
                total_clustering += local_clustering
                nodes_with_neighbors += 1
        
        avg_clustering = total_clustering / nodes_with_neighbors if nodes_with_neighbors > 0 else 0
        clustering_coefficients[scale] = avg_clustering
    
    # Global clustering measures
    if clustering_coefficients:
        max_clustering = max(clustering_coefficients.values())
        avg_clustering_all_scales = np.mean(list(clustering_coefficients.values()))
        clustering_scale_dependence = np.var(list(clustering_coefficients.values()))
    else:
        max_clustering = 0.0
        avg_clustering_all_scales = 0.0
        clustering_scale_dependence = 0.0
    
    return {'clustering_by_scale': clustering_coefficients, 'max_clustering': max_clustering,
            'avg_clustering': avg_clustering_all_scales, 'scale_dependence': clustering_scale_dependence}

def _calculate_wtmm_analysis(points):
    """Wavelet Transform Modulus Maxima analysis"""
    n_points = len(points)
    
    # Simplified WTMM analysis for point distributions
    # In full implementation, this would use continuous wavelet transforms
    
    # Calculate local irregularity measures using wavelet-like analysis
    scales = np.logspace(-2, 0, 10)
    wtmm_exponents = []
    
    for i in range(min(50, n_points)):
        point = points[i]
        local_exponents = []
        
        for scale in scales:
            # Local wavelet coefficient approximation
            distances = np.linalg.norm(points - point, axis=1)
            local_points = points[distances <= scale]
            
            if len(local_points) > 2:
                # Calculate local variation (proxy for wavelet coefficient)
                local_variance = np.var(local_points, axis=0)
                local_variation = np.mean(local_variance)
                
                if local_variation > 0:
                    local_exponent = np.log(local_variation) / np.log(scale)
                    local_exponents.append(local_exponent)
        
        if local_exponents:
            avg_exponent = np.mean(local_exponents)
            wtmm_exponents.append(avg_exponent)
    
    # WTMM spectrum characteristics
    if wtmm_exponents:
        wtmm_mean = np.mean(wtmm_exponents)
        wtmm_std = np.std(wtmm_exponents)
        wtmm_range = max(wtmm_exponents) - min(wtmm_exponents)
        
        # Singularity strength distribution
        singularity_histogram, _ = np.histogram(wtmm_exponents, bins=10)
        wtmm_spectrum_width = wtmm_range
    else:
        wtmm_mean = 2.0
        wtmm_std = 0.2
        wtmm_spectrum_width = 0.5
    
    return {'wtmm_exponents': wtmm_exponents, 'wtmm_mean': wtmm_mean, 
            'wtmm_std': wtmm_std, 'spectrum_width': wtmm_spectrum_width}

def _calculate_wavelet_partition_function(points):
    """Calculate wavelet-based partition function"""
    n_points = len(points)
    scales = np.logspace(-2, 0, 8)
    q_values = [-2, -1, 0, 1, 2, 3]
    
    partition_functions = {}
    
    for q in q_values:
        scale_values = []
        
        for scale in scales:
            # Calculate local wavelet measures
            local_measures = []
            
            for i in range(min(100, n_points)):
                point = points[i]
                distances = np.linalg.norm(points - point, axis=1)
                neighbors = points[distances <= scale]
                
                if len(neighbors) > 1:
                    # Local measure approximation
                    local_density = len(neighbors) / (scale ** points.shape[1])
                    local_measures.append(local_density)
            
            # Partition function Z_q(scale)
            if local_measures:
                if q == 0:
                    z_q = len(local_measures)  # Number of boxes with measure > 0
                else:
                    z_q = sum(measure**q for measure in local_measures if measure > 0)
            else:
                z_q = 1.0
            
            scale_values.append(z_q)
        
        partition_functions[q] = scale_values
    
    # Calculate scaling exponents
    scaling_exponents = {}
    for q, values in partition_functions.items():
        if len(values) > 4:
            log_scales = [np.log(s) for s in scales]
            log_values = [np.log(v) for v in values if v > 0]
            
            if len(log_values) > 3:
                tau_q = np.polyfit(log_scales[:len(log_values)], log_values, 1)[0]
                scaling_exponents[q] = tau_q
    
    return {'partition_functions': partition_functions, 'scaling_exponents': scaling_exponents}

def _calculate_wavelet_skeleton_analysis(points):
    """Analyze wavelet transform skeleton"""
    n_points = len(points)
    
    # Skeleton analysis approximation
    scales = np.logspace(-2, 0, 12)
    skeleton_points = []
    
    for scale in scales:
        # Find local maxima in wavelet transform
        scale_maxima = []
        
        for i in range(min(80, n_points)):
            point = points[i]
            distances = np.linalg.norm(points - point, axis=1)
            
            # Local wavelet coefficient approximation
            neighbors = points[distances <= scale]
            if len(neighbors) > 3:
                local_variation = np.var(neighbors - point, axis=0)
                wavelet_coeff = np.mean(local_variation)
                
                # Check if this is a local maximum
                nearby_coeffs = []
                for j in range(len(neighbors)):
                    neighbor_distances = np.linalg.norm(points - neighbors[j], axis=1)
                    neighbor_neighbors = points[neighbor_distances <= scale]
                    if len(neighbor_neighbors) > 3:
                        neighbor_variation = np.var(neighbor_neighbors - neighbors[j], axis=0)
                        nearby_coeffs.append(np.mean(neighbor_variation))
                
                if nearby_coeffs and wavelet_coeff >= np.mean(nearby_coeffs):
                    scale_maxima.append({
                        'position': point.copy(),
                        'coefficient': wavelet_coeff,
                        'scale': scale
                    })
        
        skeleton_points.extend(scale_maxima)
    
    # Analyze skeleton properties
    if skeleton_points:
        skeleton_density = len(skeleton_points) / (len(scales) * min(80, n_points))
        max_coefficients = [sp['coefficient'] for sp in skeleton_points]
        skeleton_strength = np.mean(max_coefficients) if max_coefficients else 0
        coefficient_variance = np.var(max_coefficients) if max_coefficients else 0
    else:
        skeleton_density = 0.0
        skeleton_strength = 0.0
        coefficient_variance = 0.0
    
    return {'skeleton_points': skeleton_points, 'skeleton_density': skeleton_density,
            'skeleton_strength': skeleton_strength, 'coefficient_variance': coefficient_variance}

def _calculate_wavelet_modulus_maxima(points):
    """Calculate wavelet modulus maxima lines"""
    n_points = len(points)
    scales = np.logspace(-2, 0, 10)
    
    # Track modulus maxima across scales
    maxima_lines = []
    
    # Find maxima at each scale
    scale_maxima = {}
    for scale in scales:
        current_maxima = []
        
        for i in range(min(60, n_points)):
            point = points[i]
            distances = np.linalg.norm(points - point, axis=1)
            
            # Calculate wavelet modulus
            neighbors = points[distances <= scale]
            if len(neighbors) > 2:
                gradient_approx = np.var(neighbors - point, axis=0)
                modulus = np.sqrt(np.sum(gradient_approx))
                
                # Check for local maximum
                is_maximum = True
                for j in range(len(neighbors)):
                    neighbor_distances = np.linalg.norm(points - neighbors[j], axis=1)
                    neighbor_neighbors = points[neighbor_distances <= scale]
                    
                    if len(neighbor_neighbors) > 2:
                        neighbor_gradient = np.var(neighbor_neighbors - neighbors[j], axis=0)
                        neighbor_modulus = np.sqrt(np.sum(neighbor_gradient))
                        
                        if neighbor_modulus > modulus:
                            is_maximum = False
                            break
                
                if is_maximum:
                    current_maxima.append({
                        'position': point.copy(),
                        'modulus': modulus,
                        'scale': scale,
                        'point_index': i
                    })
        
        scale_maxima[scale] = current_maxima
    
    # Connect maxima across scales to form lines
    for scale_idx in range(len(scales) - 1):
        current_scale = scales[scale_idx]
        next_scale = scales[scale_idx + 1]
        
        current_max = scale_maxima.get(current_scale, [])
        next_max = scale_maxima.get(next_scale, [])
        
        # Connect nearby maxima
        for curr_max in current_max:
            best_connection = None
            min_distance = float('inf')
            
            for next_max_point in next_max:
                distance = np.linalg.norm(curr_max['position'] - next_max_point['position'])
                if distance < min_distance:
                    min_distance = distance
                    best_connection = next_max_point
            
            if best_connection and min_distance < 0.3:  # Connection threshold
                maxima_lines.append({
                    'start_scale': current_scale,
                    'end_scale': next_scale,
                    'start_position': curr_max['position'],
                    'end_position': best_connection['position'],
                    'start_modulus': curr_max['modulus'],
                    'end_modulus': best_connection['modulus']
                })
    
    # Analyze maxima line properties
    if maxima_lines:
        line_lengths = [np.linalg.norm(ml['end_position'] - ml['start_position']) for ml in maxima_lines]
        avg_line_length = np.mean(line_lengths)
        modulus_changes = [abs(ml['end_modulus'] - ml['start_modulus']) for ml in maxima_lines]
        avg_modulus_change = np.mean(modulus_changes)
    else:
        avg_line_length = 0.0
        avg_modulus_change = 0.0
    
    return {'maxima_lines': maxima_lines, 'n_lines': len(maxima_lines),
            'avg_line_length': avg_line_length, 'avg_modulus_change': avg_modulus_change}

def _calculate_oscillating_singularities(points):
    """Detect and analyze oscillating singularities"""
    n_points = len(points)
    scales = np.logspace(-2, 0, 8)
    
    # Look for oscillating behavior in local scaling
    oscillating_points = []
    
    for i in range(min(40, n_points)):
        point = points[i]
        local_exponents = []
        
        for scale in scales:
            distances = np.linalg.norm(points - point, axis=1)
            neighbors = points[distances <= scale]
            
            if len(neighbors) > 3:
                local_density = len(neighbors) / (scale ** points.shape[1])
                if local_density > 0:
                    exponent = np.log(local_density) / np.log(scale)
                    local_exponents.append(exponent)
        
        # Detect oscillations in scaling exponents
        if len(local_exponents) > 5:
            # Look for sign changes in derivatives
            derivatives = np.diff(local_exponents)
            sign_changes = sum(1 for j in range(len(derivatives)-1) 
                             if derivatives[j] * derivatives[j+1] < 0)
            
            oscillation_strength = sign_changes / len(derivatives) if derivatives else 0
            
            if oscillation_strength > 0.3:  # Threshold for oscillating behavior
                oscillating_points.append({
                    'position': point.copy(),
                    'oscillation_strength': oscillation_strength,
                    'exponent_variance': np.var(local_exponents),
                    'mean_exponent': np.mean(local_exponents)
                })
    
    # Analyze oscillating singularity properties
    if oscillating_points:
        avg_oscillation_strength = np.mean([op['oscillation_strength'] for op in oscillating_points])
        max_oscillation_strength = max([op['oscillation_strength'] for op in oscillating_points])
        oscillation_density = len(oscillating_points) / min(40, n_points)
    else:
        avg_oscillation_strength = 0.0
        max_oscillation_strength = 0.0
        oscillation_density = 0.0
    
    return {'oscillating_points': oscillating_points, 'oscillation_density': oscillation_density,
            'avg_oscillation_strength': avg_oscillation_strength, 'max_oscillation_strength': max_oscillation_strength}

def _calculate_intermittency_analysis(points):
    """Analyze intermittency properties"""
    n_points = len(points)
    
    # Calculate local density variations for intermittency analysis
    scales = [0.1, 0.2, 0.3, 0.5]
    intermittency_measures = {}
    
    for scale in scales:
        local_densities = []
        
        for i in range(min(100, n_points)):
            point = points[i]
            distances = np.linalg.norm(points - point, axis=1)
            neighbors = np.sum(distances <= scale)
            
            volume = (scale ** points.shape[1])
            local_density = neighbors / volume
            local_densities.append(local_density)
        
        if local_densities:
            # Intermittency statistics
            density_mean = np.mean(local_densities)
            density_moments = {}
            
            for moment_order in [2, 3, 4, 6]:
                if density_mean > 0:
                    normalized_moment = np.mean([(d/density_mean)**moment_order for d in local_densities])
                    density_moments[moment_order] = normalized_moment
            
            # Intermittency exponents
            intermittency_exp = {}
            for order in [2, 3, 4, 6]:
                if order in density_moments and density_moments[order] > 0:
                    # Simplified intermittency exponent calculation
                    intermittency_exp[order] = np.log(density_moments[order]) / np.log(scale)
            
            intermittency_measures[scale] = {
                'density_moments': density_moments,
                'intermittency_exponents': intermittency_exp,
                'density_variance': np.var(local_densities),
                'density_skewness': np.mean([(d - density_mean)**3 for d in local_densities]) / (np.var(local_densities)**1.5)
            }
    
    # Global intermittency characterization
    if intermittency_measures:
        all_variances = [im['density_variance'] for im in intermittency_measures.values()]
        all_skewnesses = [im['density_skewness'] for im in intermittency_measures.values()]
        
        avg_intermittency_variance = np.mean(all_variances)
        avg_intermittency_skewness = np.mean(all_skewnesses)
        scale_dependent_intermittency = np.var(all_variances)
    else:
        avg_intermittency_variance = 0.1
        avg_intermittency_skewness = 0.0
        scale_dependent_intermittency = 0.0
    
    return {'intermittency_by_scale': intermittency_measures, 
            'avg_intermittency_variance': avg_intermittency_variance,
            'avg_intermittency_skewness': avg_intermittency_skewness,
            'scale_dependent_intermittency': scale_dependent_intermittency}

def _calculate_comprehensive_multifractal_spectrum(framework, points):
    """Integrate all framework components into final multifractal spectrum"""
    n_points = len(points)
    
    # Extract key results from each analysis framework
    singularity_analysis = framework['singularity_spectrum_analysis']
    moment_analysis = framework['moment_scaling_analysis']
    box_analysis = framework['box_counting_analysis']
    correlation_analysis = framework['correlation_dimension_analysis']
    lacunarity_analysis = framework['lacunarity_analysis']
    wavelet_analysis = framework['wavelet_transform_analysis']
    
    # Comprehensive spectrum characteristics
    spectrum_results = {
        'spectrum_width': singularity_analysis['multifractal_width']['spectrum_width'],
        'heterogeneity': min(1.0, singularity_analysis['multifractal_width']['spectrum_width'] / 2.0),
        'local_density_variation': singularity_analysis['holder_exponents']['exponent_std'],
        
        # Dimension measures
        'capacity_dimension': box_analysis['capacity_dimension']['dimension'],
        'information_dimension': box_analysis['information_dimension']['dimension'],
        'correlation_dimension': correlation_analysis['grassberger_procaccia']['dimension'],
        
        # Singularity spectrum properties
        'holder_exponent_range': singularity_analysis['holder_exponents']['exponent_range'],
        'singularity_strength': singularity_analysis['singularity_strength']['mean_strength'],
        'spectrum_asymmetry': singularity_analysis['left_right_asymmetry']['asymmetry_ratio'],
        
        # Lacunarity measures
        'lacunarity_max': lacunarity_analysis['lacunarity_curves']['max_lacunarity'],
        'lacunarity_range': lacunarity_analysis['lacunarity_curves']['lacunarity_range'],
        'texture_complexity': lacunarity_analysis['texture_analysis']['avg_contrast'],
        
        # Wavelet-based measures
        'wtmm_spectrum_width': wavelet_analysis['wtmm_analysis']['spectrum_width'],
        'intermittency_strength': wavelet_analysis['intermittency_analysis']['avg_intermittency_variance'],
        
        # Higher-order statistics
        'generalized_dimensions': moment_analysis['generalized_dimensions'],
        'mass_exponents': moment_analysis['mass_exponents']['mass_exponents'],
        'scaling_quality': correlation_analysis['grassberger_procaccia']['r_squared'],
        
        # Clustering and spatial organization
        'clustering_coefficient': lacunarity_analysis['clustering_coefficients']['max_clustering'],
        'rotational_invariance': lacunarity_analysis['rotational_invariance']['rotational_stability'],
        
        # Advanced fractal measures
        'finite_size_effects': box_analysis['finite_size_scaling']['finite_size_slope'],
        'noise_sensitivity': correlation_analysis['noise_reduction']['noise_sensitivity'],
        'embedding_dimension': correlation_analysis['embedding_dimension']['optimal_dimension'],
        'convergence_quality': correlation_analysis['convergence_analysis']['capacity_stable']
    }
    
    # Multifractality classification
    if spectrum_results['spectrum_width'] > 0.5:
        multifractal_type = 'strongly_multifractal'
        complexity_measure = 0.8 + 0.2 * min(1.0, spectrum_results['spectrum_width'] - 0.5)
    elif spectrum_results['spectrum_width'] > 0.2:
        multifractal_type = 'weakly_multifractal'
        complexity_measure = 0.4 + 0.4 * (spectrum_results['spectrum_width'] - 0.2) / 0.3
    else:
        multifractal_type = 'monofractal'
        complexity_measure = 0.2 + 0.2 * spectrum_results['spectrum_width'] / 0.2
    
    spectrum_results['multifractal_type'] = multifractal_type
    spectrum_results['complexity_measure'] = complexity_measure
    
    return spectrum_results

def _quantify_multifractal_uncertainty(spectrum_results, framework):
    """Quantify uncertainty in multifractal spectrum analysis"""
    uncertainty_sources = {
        'finite_sample_effects': 0.10,           # 10% uncertainty from finite sampling
        'scale_range_limitations': 0.08,         # 8% uncertainty from limited scale range
        'dimension_estimation_error': 0.15,      # 15% uncertainty in dimension estimates
        'noise_effects': 0.12,                   # 12% uncertainty from measurement noise
        'algorithm_approximations': 0.06,        # 6% uncertainty from algorithmic approximations
        'statistical_fluctuations': 0.09,        # 9% uncertainty from statistical fluctuations
        'embedding_effects': 0.07,               # 7% uncertainty from embedding dimension choice
        'boundary_effects': 0.05                 # 5% uncertainty from finite domain boundaries
    }
    
    # Combine uncertainties
    total_uncertainty = np.sqrt(sum(u**2 for u in uncertainty_sources.values()))
    
    # Uncertainty scaling based on data quality
    n_points_factor = 1.0 + 0.3 * np.exp(-len(spectrum_results.get('holder_exponent_range', [0, 1])) / 100)
    scaling_quality_factor = 2.0 - spectrum_results.get('scaling_quality', 0.5)  # Lower quality = higher uncertainty
    
    scaled_uncertainty = total_uncertainty * n_points_factor * scaling_quality_factor
    
    # Specific uncertainties for key measures
    specific_uncertainties = {
        'spectrum_width_uncertainty': scaled_uncertainty * 0.8,
        'dimension_uncertainty': scaled_uncertainty * 1.2,
        'heterogeneity_uncertainty': scaled_uncertainty * 0.6,
        'complexity_uncertainty': scaled_uncertainty * 0.9
    }
    
    return {'total_uncertainty': scaled_uncertainty, 'uncertainty_sources': uncertainty_sources, 
            'specific_uncertainties': specific_uncertainties}


# ============================================================================
# COMPREHENSIVE HELPER METHODS FOR KINEMATIC ANALYSIS
# ============================================================================

def _extract_comprehensive_fold_geometry(fold) -> Dict:
    """Extract comprehensive fold geometry parameters"""
    base_geometry = getattr(fold, 'geometry', {})
    
    # Enhanced geometric parameters
    wavelength = base_geometry.get('wavelength', 200.0)
    amplitude = base_geometry.get('amplitude', 20.0)
    interlimb_angle = base_geometry.get('interlimb_angle', 60.0)
    
    # Calculate derived parameters
    tightness = _calculate_fold_tightness(interlimb_angle)
    asymmetry = _calculate_fold_asymmetry(fold)
    curvature_profile = _calculate_curvature_profile(wavelength, amplitude)
    
    # Geometric ratios and statistics
    aspect_ratio = amplitude / wavelength
    geometric_complexity = _calculate_geometric_complexity(fold)
    
    return {
        'wavelength': wavelength,
        'amplitude': amplitude,
        'interlimb_angle': interlimb_angle,
        'aspect_ratio': aspect_ratio,
        'tightness': tightness,
        'asymmetry': asymmetry,
        'curvature_profile': curvature_profile,
        'geometric_complexity': geometric_complexity,
        'fold_class': _classify_fold_geometry(tightness, asymmetry),
        'harmonic_coefficients': _calculate_harmonic_coefficients(wavelength, amplitude)
    }


def _calculate_fold_tightness(interlimb_angle: float) -> Dict:
    """Calculate fold tightness classification and parameters"""
    if interlimb_angle > 120:
        classification = 'gentle'
        tightness_factor = 0.2
    elif interlimb_angle > 70:
        classification = 'open'
        tightness_factor = 0.4
    elif interlimb_angle > 30:
        classification = 'close'
        tightness_factor = 0.7
    else:
        classification = 'tight'
        tightness_factor = 0.9
    
    return {
        'classification': classification,
        'tightness_factor': tightness_factor,
        'interlimb_angle': interlimb_angle,
        'angular_deviation': abs(interlimb_angle - 90),
        'compression_index': (180 - interlimb_angle) / 180
    }


def _calculate_fold_asymmetry(fold) -> Dict:
    """Calculate fold asymmetry parameters"""
    profile = getattr(fold, 'profile', None)
    if profile is None:
        return {'asymmetry_factor': 0.0, 'vergence': 'symmetric'}
    
    limb_lengths = _calculate_limb_lengths(profile)
    hinge_position = _calculate_hinge_position(profile)
    
    asymmetry_factor = abs(limb_lengths['left'] - limb_lengths['right']) / max(limb_lengths['left'], limb_lengths['right'])
    vergence = 'left' if limb_lengths['left'] > limb_lengths['right'] else 'right'
    
    return {
        'asymmetry_factor': asymmetry_factor,
        'vergence': vergence,
        'limb_lengths': limb_lengths,
        'hinge_position': hinge_position,
        'symmetry_index': 1.0 - asymmetry_factor
    }


def _calculate_curvature_profile(wavelength: float, amplitude: float) -> Dict:
    """Calculate detailed curvature profile along fold"""
    x = np.linspace(0, wavelength, 101)
    y = amplitude * np.sin(2 * np.pi * x / wavelength)
    
    dx = np.gradient(x)
    dy = np.gradient(y)
    d2x = np.gradient(dx)
    d2y = np.gradient(dy)
    
    curvature = np.abs(dx * d2y - dy * d2x) / (dx**2 + dy**2)**(3/2)
    
    max_curvature = np.max(curvature)
    mean_curvature = np.mean(curvature)
    curvature_variance = np.var(curvature)
    
    hinge_indices = _find_hinge_points(curvature)
    inflection_indices = _find_inflection_points(curvature)
    
    return {
        'curvature_array': curvature,
        'max_curvature': max_curvature,
        'mean_curvature': mean_curvature,
        'curvature_variance': curvature_variance,
        'hinge_positions': hinge_indices,
        'inflection_positions': inflection_indices,
        'curvature_gradient': np.gradient(curvature),
        'fold_complexity': curvature_variance / mean_curvature if mean_curvature > 0 else 0
    }


def _calculate_kinematic_flow_field(fold_geometry: Dict) -> Dict:
    """Calculate comprehensive kinematic flow field"""
    wavelength = fold_geometry['wavelength']
    amplitude = fold_geometry['amplitude']
    
    flow_field = {
        'velocity_field': _calculate_velocity_field(wavelength, amplitude),
        'acceleration_field': _calculate_acceleration_field(wavelength, amplitude),
        'strain_rate_field': _calculate_strain_rate_field(wavelength, amplitude),
        'vorticity_field': _calculate_vorticity_field(wavelength, amplitude),
        'flow_lines': _calculate_flow_lines(wavelength, amplitude),
        'stagnation_points': _identify_stagnation_points(wavelength, amplitude),
        'flow_topology': _analyze_flow_topology_field(wavelength, amplitude)
    }
    
    flow_field['statistics'] = {
        'mean_velocity': np.mean([v for v in flow_field['velocity_field'].values() if isinstance(v, (int, float))]),
        'velocity_variance': np.var([v for v in flow_field['velocity_field'].values() if isinstance(v, (int, float))]),
        'flow_complexity': _calculate_flow_complexity(flow_field),
        'reynolds_number': _estimate_reynolds_number(flow_field),
        'flow_regime': _classify_flow_regime(flow_field)
    }
    
    return flow_field


def _calculate_strain_rate_tensor(fold_geometry: Dict, flow_field: Dict) -> np.ndarray:
    """Calculate comprehensive strain rate tensor"""
    wavelength = fold_geometry['wavelength']
    amplitude = fold_geometry['amplitude']
    
    # Basic strain rate from fold geometry
    shear_rate = 2 * np.pi * amplitude / (wavelength**2) * 1e-15
    
    # Enhanced strain rate tensor with flow field coupling
    velocity_gradient = np.array([
        [0, shear_rate, 0],
        [shear_rate, 0, 0],
        [0, 0, -shear_rate]
    ])
    
    strain_rate = 0.5 * (velocity_gradient + velocity_gradient.T)
    
    # Apply flow field corrections
    flow_correction = _calculate_flow_field_corrections(flow_field)
    corrected_strain_rate = strain_rate * (1 + flow_correction)
    
    return corrected_strain_rate


def _calculate_vorticity_tensor(fold_geometry: Dict, flow_field: Dict) -> np.ndarray:
    """Calculate comprehensive vorticity tensor"""
    wavelength = fold_geometry['wavelength']
    amplitude = fold_geometry['amplitude']
    
    # Basic vorticity from fold geometry  
    shear_rate = 2 * np.pi * amplitude / (wavelength**2) * 1e-15
    
    # Enhanced vorticity tensor
    velocity_gradient = np.array([
        [0, shear_rate, 0],
        [shear_rate, 0, 0],
        [0, 0, -shear_rate]
    ])
    
    vorticity = 0.5 * (velocity_gradient - velocity_gradient.T)
    
    # Apply flow field enhancements
    flow_enhancement = _calculate_vorticity_flow_enhancements(flow_field)
    enhanced_vorticity = vorticity * (1 + flow_enhancement)
    
    return enhanced_vorticity


def _construct_velocity_gradient_tensor(strain_rate: np.ndarray, vorticity: np.ndarray, 
                                       progressive: Dict, rheological: Dict) -> np.ndarray:
    """Construct comprehensive velocity gradient tensor"""
    # Base velocity gradient from strain rate and vorticity
    velocity_gradient = strain_rate + vorticity
    
    # Apply progressive deformation corrections
    progressive_factor = progressive.get('deformation_factor', 1.0)
    velocity_gradient *= progressive_factor
    
    # Apply rheological corrections
    rheological_factor = rheological.get('flow_factor', 1.0)
    velocity_gradient *= rheological_factor
    
    # Add temporal evolution effects
    temporal_correction = _calculate_temporal_velocity_corrections(progressive, rheological)
    velocity_gradient += temporal_correction
    
    return velocity_gradient


