def _calculate_temporal_velocity_corrections(progressive: Dict, rheological: Dict) -> np.ndarray:
    """Calculate temporal velocity corrections"""
    return np.array([[0.01, 0, 0], [0, 0.01, 0], [0, 0, -0.01]])

# Spatial vorticity analysis helper methods
