# Classification helper methods
def _classify_kinematic_vorticity(vorticity: float) -> Dict:
    """Classify kinematic vorticity"""
    if vorticity < 0.2:
        primary_type = 'pure_shear_dominated'
    elif vorticity < 0.5:
        primary_type = 'transpression'
    elif vorticity < 0.8:
        primary_type = 'general_shear'
    else:
        primary_type = 'simple_shear_dominated'
    
    return {
        'primary_type': primary_type,
        'vorticity_number': vorticity,
        'deformation_regime': primary_type
    }

