def _classify_by_curvature(path_analysis: Dict) -> Dict:
    """Classify deformation path by curvature"""
    curvature = path_analysis.get('path_curvature', 0.3)
    if curvature < 0.1:
        classification = 'linear'
        confidence = 0.9
    elif curvature < 0.3:
        classification = 'weakly_curved'
        confidence = 0.8
    elif curvature < 0.6:
        classification = 'moderately_curved'
        confidence = 0.85
    else:
        classification = 'strongly_curved'
        confidence = 0.9
    
    return {
        'curvature_class': classification,
        'confidence': confidence,
        'curvature_magnitude': curvature
    }

def _classify_by_noncoaxiality(path_analysis: Dict) -> Dict:
    """Classify by non-coaxiality characteristics"""
    deviation = path_analysis.get('deviation_from_coaxial', 25.0)
    if deviation < 10:
        classification = 'nearly_coaxial'
    elif deviation < 30:
        classification = 'weakly_non_coaxial'
    elif deviation < 60:
        classification = 'moderately_non_coaxial'
    else:
        classification = 'strongly_non_coaxial'
    
    return {
        'noncoaxiality_class': classification,
        'angular_deviation': deviation,
        'coaxiality_measure': (90 - deviation) / 90
    }

