def _integrate_path_classifications(curvature: Dict, noncoaxiality: Dict, 
                                  temporal: Dict, strain_rate: Dict, stress_path: Dict) -> Dict:
    """Integrate multiple path classifications"""
    # Weighted classification integration
    curvature_weight = 0.3
    noncoaxiality_weight = 0.3
    temporal_weight = 0.2
    strain_rate_weight = 0.1
    stress_path_weight = 0.1
    
    if noncoaxiality['angular_deviation'] < 10:
        primary_classification = 'coaxial'
    elif noncoaxiality['angular_deviation'] < 30:
        primary_classification = 'weakly_non_coaxial'
    else:
        primary_classification = 'strongly_non_coaxial'
    
    return {
        'primary_classification': primary_classification,
        'integrated_confidence': 0.85,
        'classification_weights': {
            'curvature': curvature_weight,
            'noncoaxiality': noncoaxiality_weight,
            'temporal': temporal_weight,
            'strain_rate': strain_rate_weight,
            'stress_path': stress_path_weight
        }
    }

def _model_coaxiality_temporal_evolution(fold, params: Dict) -> Dict:
    """Model temporal evolution of coaxiality"""
    time_steps = np.linspace(0, 100, 101)
    initial_coaxiality = 0.9
    final_coaxiality = 0.3
    
    # Exponential decay model
    coaxiality_evolution = initial_coaxiality * np.exp(-time_steps/50) + final_coaxiality * (1 - np.exp(-time_steps/50))
    
    # Find transition time (50% change)
    transition_time = 50 * np.log(2)
    
    return {
        'time_array': time_steps,
        'coaxiality_evolution': coaxiality_evolution,
        'initial_value': initial_coaxiality,
        'final_value': final_coaxiality,
        'trend': 'decreasing',
        'transition_time': transition_time,
        'variance': np.var(coaxiality_evolution),
        'evolution_rate': -(initial_coaxiality - final_coaxiality) / 100
    }

