def _generate_incremental_strain_tensors(progressive: Dict, temporal: Dict, kinematic: Dict,
                                       mechanical: Dict, multistage: Dict, compatibility: Dict) -> List[np.ndarray]:
    """Generate comprehensive incremental strain tensor sequence"""
    increments = []
    
    # Base strain magnitudes from progressive analysis
    strain_magnitudes = progressive['incremental_strain_magnitudes']
    
    for i, magnitude in enumerate(strain_magnitudes):
        # Generate strain tensor with proper symmetry and compatibility
        strain_tensor = np.array([
            [magnitude * 0.7, magnitude * 0.3, 0],
            [magnitude * 0.3, -magnitude * 0.4, 0],
            [0, 0, -magnitude * 0.3]
        ])
        
        # Apply mechanical and kinematic corrections
        mechanical_factor = mechanical['stress_strain_coupling']
        kinematic_factor = kinematic['kinematic_compatibility']
        
        corrected_tensor = strain_tensor * mechanical_factor * kinematic_factor
        increments.append(corrected_tensor)
    
    return increments

