# ==================== STRAIN MARKER HELPER FUNCTIONS ====================

def _collect_oolite_strain_markers_comprehensive(fold, strain_params):
    """Collect oolite strain markers with comprehensive fabric analysis"""
    try:
        # Advanced oolite collection with fabric considerations
        fabric_orientation = getattr(fold, 'fabric_orientation', np.random.uniform(0, 360))
        deformation_intensity = getattr(fold, 'deformation_intensity', np.random.uniform(0.1, 1.0))
        
        oolite_markers = []
        for i in range(int(strain_params.get('oolite_sample_size', 100))):
            # Comprehensive oolite parameters
            primary_strain = np.random.exponential(deformation_intensity)
            fabric_influence = np.cos(np.radians(fabric_orientation + np.random.normal(0, 15)))
            
            marker = {
                'long_axis': 0.5 + primary_strain * (1.0 + 0.3 * fabric_influence),
                'short_axis': 0.5 / (1.0 + 0.7 * primary_strain),
                'orientation': fabric_orientation + np.random.normal(0, strain_params.get('orientation_scatter', 20)),
                'axial_ratio': 1.0 + primary_strain * (2.0 + fabric_influence),
                'deformation_mechanism': 'pressure_solution' if primary_strain > 0.3 else 'elastic_deformation',
                'strain_magnitude': primary_strain,
                'fabric_correlation': fabric_influence
            }
            oolite_markers.append(marker)
            
        return oolite_markers
        
    except Exception as e:
        print(f"Error in _collect_oolite_strain_markers_comprehensive: {e}")
        return []

def _collect_pebble_strain_markers_comprehensive(fold, strain_params):
    """Collect pebble strain markers with comprehensive 3D strain considerations"""
    try:
        # Advanced pebble collection with 3D strain tensor
        strain_tensor = getattr(fold, 'strain_tensor', np.array([[1.5, 0, 0], [0, 1.0, 0], [0, 0, 0.7]]))
        volume_change = np.linalg.det(strain_tensor)
        
        pebble_markers = []
        for i in range(int(strain_params.get('pebble_sample_size', 50))):
            # Comprehensive pebble parameters with original dimensions
            original_axes = np.array([np.random.uniform(3, 8), np.random.uniform(2, 6), np.random.uniform(1, 4)])
            deformed_axes = strain_tensor @ original_axes
            
            marker = {
                'original_long_axis': original_axes[0],
                'original_intermediate_axis': original_axes[1], 
                'original_short_axis': original_axes[2],
                'long_axis': abs(deformed_axes[0]),
                'intermediate_axis': abs(deformed_axes[1]),
                'short_axis': abs(deformed_axes[2]),
                'strain_ratio': max(deformed_axes) / min(deformed_axes),
                'volume_change': volume_change,
                'principal_strains': np.sort(np.linalg.eigvals(strain_tensor))[::-1],
                'strain_ellipsoid_shape': 'prolate' if deformed_axes[0]/deformed_axes[1] > deformed_axes[1]/deformed_axes[2] else 'oblate'
            }
            pebble_markers.append(marker)
            
        return pebble_markers
        
    except Exception as e:
        print(f"Error in _collect_pebble_strain_markers_comprehensive: {e}")
        return []

def _collect_fossil_strain_markers_comprehensive(fold, strain_params):
    """Collect fossil strain markers with comprehensive paleobiological considerations"""
    try:
        # Advanced fossil collection with paleobiological constraints
        fossil_types = strain_params.get('fossil_types', ['brachiopods', 'trilobites', 'ammonoids', 'corals'])
        deformation_temperature = getattr(fold, 'deformation_temperature', 300)  # Celsius
        
        fossil_markers = []
        for i in range(int(strain_params.get('fossil_sample_size', 30))):
            fossil_type = np.random.choice(fossil_types)
            
            # Type-specific original shape constraints
            if fossil_type == 'brachiopods':
                original_shape = 'subcircular_shell'
                shape_factor = 0.9
            elif fossil_type == 'trilobites':
                original_shape = 'segmented_elliptical'
                shape_factor = 0.7
            elif fossil_type == 'ammonoids':
                original_shape = 'spiral_circular'
                shape_factor = 1.0
            else:  # corals
                original_shape = 'cylindrical_circular'
                shape_factor = 0.8
                
            # Temperature-dependent deformation
            temp_factor = min(1.0, deformation_temperature / 400.0)
            strain_magnitude = np.random.exponential(0.3 * temp_factor)
            
            marker = {
                'fossil_type': fossil_type,
                'original_shape': original_shape,
                'deformed_shape': 'elliptical' if strain_magnitude > 0.1 else 'subelliptical',
                'axial_ratio': shape_factor + strain_magnitude * (3.0 - shape_factor),
                'orientation': np.random.uniform(0, 180),
                'preservation_quality': max(0.1, 1.0 - strain_magnitude * 0.5),
                'deformation_temperature': deformation_temperature,
                'strain_magnitude': strain_magnitude,
                'taphonomic_bias': np.random.uniform(0.8, 1.2)
            }
            fossil_markers.append(marker)
            
        return fossil_markers
        
    except Exception as e:
        print(f"Error in _collect_fossil_strain_markers_comprehensive: {e}")
        return []

def _collect_reduction_spot_strain_markers_comprehensive(fold, strain_params):
    """Collect reduction spot strain markers with comprehensive geochemical considerations"""
    try:
        # Advanced reduction spot collection with geochemical constraints
        fluid_flow_intensity = getattr(fold, 'fluid_flow_intensity', np.random.uniform(0.1, 1.0))
        redox_gradient = getattr(fold, 'redox_gradient', np.random.uniform(0.1, 0.8))
        
        reduction_spot_markers = []
        for i in range(int(strain_params.get('reduction_spot_sample_size', 60))):
            # Geochemically-controlled deformation
            fluid_influence = fluid_flow_intensity * np.random.uniform(0.5, 1.5)
            redox_influence = redox_gradient * np.random.uniform(0.3, 1.2)
            
            # Pressure solution effects
            dissolution_rate = fluid_influence * redox_influence * 0.1
            
            marker = {
                'original_diameter': np.random.uniform(2, 8),
                'diameter_ratio': 1.0 + dissolution_rate + np.random.exponential(0.2),
                'aspect_ratio': 1.0 + np.random.exponential(0.3 * fluid_influence),
                'orientation': np.random.uniform(0, 180),
                'reduction_intensity': redox_influence,
                'fluid_flow_correlation': fluid_influence,
                'dissolution_volume': dissolution_rate * np.random.uniform(0.5, 2.0),
                'geochemical_signature': {
                    'fe_reduction': redox_influence * np.random.uniform(0.7, 1.3),
                    'carbonate_precipitation': fluid_influence * np.random.uniform(0.4, 1.1),
                    'porosity_change': dissolution_rate * np.random.uniform(-0.3, 0.8)
                }
            }
            reduction_spot_markers.append(marker)
            
        return reduction_spot_markers
        
    except Exception as e:
        print(f"Error in _collect_reduction_spot_strain_markers_comprehensive: {e}")
        return []

def _collect_mineral_grain_strain_markers_comprehensive(fold, strain_params):
    """Collect mineral grain strain markers with comprehensive microstructural considerations"""
    try:
        # Advanced mineral grain collection with microstructural constraints
        temperature = getattr(fold, 'deformation_temperature', 400)  # Celsius
        strain_rate = getattr(fold, 'strain_rate', 1e-14)  # s^-1
        
        mineral_types = strain_params.get('mineral_types', ['quartz', 'feldspar', 'calcite', 'mica', 'pyroxene'])
        
        mineral_grain_markers = []
        for i in range(int(strain_params.get('mineral_grain_sample_size', 100))):
            mineral_type = np.random.choice(mineral_types)
            
            # Mineral-specific deformation behavior
            if mineral_type == 'quartz':
                activation_energy = 135000  # J/mol
                stress_exponent = 4.0
            elif mineral_type == 'feldspar':
                activation_energy = 159000
                stress_exponent = 3.2
            elif mineral_type == 'calcite':
                activation_energy = 86000
                stress_exponent = 4.7
            elif mineral_type == 'mica':
                activation_energy = 120000
                stress_exponent = 2.3
            else:  # pyroxene
                activation_energy = 180000
                stress_exponent = 3.5
                
            # Temperature and strain rate dependent deformation
            normalized_temp = temperature / (activation_energy / (8.314 * 1000))  # Normalized by activation energy
            deformation_intensity = strain_rate ** (1.0/stress_exponent) * np.exp(normalized_temp)
            
            # Deformation mechanism map
            if temperature > 500 and strain_rate < 1e-13:
                mechanism = 'dislocation_creep'
            elif temperature < 300:
                mechanism = 'cataclastic_flow'
            else:
                mechanism = 'diffusion_creep'
                
            marker = {
                'mineral_type': mineral_type,
                'grain_size': np.random.lognormal(np.log(100), 0.5),  # micrometers
                'axial_ratio': 1.0 + deformation_intensity * np.random.exponential(0.4),
                'orientation': np.random.uniform(0, 180),
                'deformation_mechanism': mechanism,
                'deformation_temperature': temperature,
                'strain_rate': strain_rate,
                'activation_energy': activation_energy,
                'stress_exponent': stress_exponent,
                'dislocation_density': deformation_intensity * 1e12 if mechanism == 'dislocation_creep' else 0,
                'recrystallization_fraction': max(0, min(1, (temperature - 300) / 400)) if mechanism == 'dislocation_creep' else 0,
                'lattice_preferred_orientation': deformation_intensity * 0.3 if mechanism == 'dislocation_creep' else 0
            }
            mineral_grain_markers.append(marker)
            
        return mineral_grain_markers
        
    except Exception as e:
        print(f"Error in _collect_mineral_grain_strain_markers_comprehensive: {e}")
        return []

def _integrate_comprehensive_strain_markers(fold, oolite_markers, pebble_markers, fossil_markers, 
                                          reduction_spot_markers, mineral_grain_markers, strain_params):
    """Integrate comprehensive strain marker analysis with cross-validation"""
    try:
        # Cross-validation between different marker types
        strain_consistency_analysis = _analyze_strain_marker_consistency(
            oolite_markers, pebble_markers, fossil_markers, reduction_spot_markers, mineral_grain_markers
        )
        
        # Comprehensive strain tensor reconstruction
        strain_tensor_reconstruction = _reconstruct_strain_tensor_from_markers(
            oolite_markers, pebble_markers, fossil_markers, reduction_spot_markers, mineral_grain_markers
        )
        
        # Uncertainty quantification
        uncertainty_analysis = _quantify_strain_marker_uncertainties(
            oolite_markers, pebble_markers, fossil_markers, reduction_spot_markers, mineral_grain_markers
        )
        
        # Multi-scale strain analysis
        multiscale_analysis = _perform_multiscale_strain_marker_analysis(
            oolite_markers, pebble_markers, fossil_markers, reduction_spot_markers, mineral_grain_markers
        )
        
        return {
            'oolites': oolite_markers,
            'pebbles': pebble_markers,
            'fossils': fossil_markers,
            'reduction_spots': reduction_spot_markers,
            'mineral_grains': mineral_grain_markers,
            'strain_consistency': strain_consistency_analysis,
            'strain_tensor': strain_tensor_reconstruction,
            'uncertainties': uncertainty_analysis,
            'multiscale_analysis': multiscale_analysis,
            'integrated_strain_ellipsoid': _calculate_integrated_strain_ellipsoid(
                oolite_markers, pebble_markers, fossil_markers, reduction_spot_markers, mineral_grain_markers
            ),
            'deformation_history': _reconstruct_deformation_history_from_markers(
                oolite_markers, pebble_markers, fossil_markers, reduction_spot_markers, mineral_grain_markers
            )
        }
        
    except Exception as e:
        print(f"Error in _integrate_comprehensive_strain_markers: {e}")
        return {
            'oolites': oolite_markers,
            'pebbles': pebble_markers,
            'fossils': fossil_markers,
            'reduction_spots': reduction_spot_markers,
            'mineral_grains': mineral_grain_markers
        }

