def calculate_rf_phi_strain_comprehensive(fold, strain_markers: Dict, rf_phi_params: Dict = None):
    """Calculate strain using RF/phi method with comprehensive strain tensor analysis"""
    try:
        if rf_phi_params is None:
            rf_phi_params = {}
            
        # Comprehensive RF/phi strain analysis
        marker_quality_assessment = _assess_strain_marker_quality_comprehensive(strain_markers, rf_phi_params)
        rf_phi_data_processing = _process_rf_phi_data_comprehensive(strain_markers, rf_phi_params)
        strain_tensor_calculation = _calculate_strain_tensor_from_rf_phi_comprehensive(rf_phi_data_processing, rf_phi_params)
        statistical_analysis = _perform_rf_phi_statistical_analysis_comprehensive(rf_phi_data_processing, rf_phi_params)
        uncertainty_quantification = _quantify_rf_phi_uncertainties_comprehensive(strain_tensor_calculation, statistical_analysis, rf_phi_params)
        validation_analysis = _validate_rf_phi_results_comprehensive(strain_tensor_calculation, marker_quality_assessment, rf_phi_params)
        
        # Comprehensive RF/phi integration
        comprehensive_rf_phi_analysis = _integrate_comprehensive_rf_phi_analysis(
            fold, marker_quality_assessment, rf_phi_data_processing, strain_tensor_calculation,
            statistical_analysis, uncertainty_quantification, validation_analysis, rf_phi_params
        )
        
        return comprehensive_rf_phi_analysis
        
    except Exception as e:
        print(f"Error in calculate_rf_phi_strain_comprehensive: {e}")
        oolites = strain_markers.get('oolites', [])
        if not oolites:
            return {'method': 'rf_phi', 'strain_ratio': 1.5, 'confidence': 0.3}
        axial_ratios = [m.get('axial_ratio', 1.5) for m in oolites if isinstance(m, dict)]
        orientations = [m.get('orientation', 0) for m in oolites if isinstance(m, dict)]
        return {
            'method': 'rf_phi',
            'strain_ratio': float(np.mean(axial_ratios)) if axial_ratios else 1.5,
            'principal_strain_orientation': float(np.mean(orientations)) if orientations else 0.0,
            'confidence': 0.8,
            'sample_size': len(oolites)
        }

def convert_plunge_bearing_to_vector_comprehensive(plunge: float, bearing: float, conversion_params: Dict = None):
    """Convert plunge and bearing to unit vector with comprehensive geometric analysis"""
    try:
        if conversion_params is None:
            conversion_params = {}
            
        # Comprehensive plunge-bearing conversion analysis
        coordinate_system_analysis = _analyze_coordinate_system_comprehensive(plunge, bearing, conversion_params)
        angular_conversion_analysis = _perform_angular_conversion_analysis_comprehensive(plunge, bearing, conversion_params)
        vector_calculation = _calculate_vector_comprehensive(plunge, bearing, coordinate_system_analysis, conversion_params)
        geometric_validation = _validate_geometric_conversion_comprehensive(vector_calculation, plunge, bearing, conversion_params)
        uncertainty_analysis = _analyze_angular_uncertainties_comprehensive(plunge, bearing, conversion_params)
        reference_frame_analysis = _analyze_reference_frame_transformations_comprehensive(vector_calculation, conversion_params)
        
        # Comprehensive vector integration
        comprehensive_vector_analysis = _integrate_comprehensive_vector_conversion(
            plunge, bearing, coordinate_system_analysis, angular_conversion_analysis, vector_calculation,
            geometric_validation, uncertainty_analysis, reference_frame_analysis, conversion_params
        )
        
        return comprehensive_vector_analysis
        
    except Exception as e:
        print(f"Error in convert_plunge_bearing_to_vector_comprehensive: {e}")
        plunge_rad = np.radians(plunge)
        bearing_rad = np.radians(bearing)
        return np.array([
            np.cos(plunge_rad) * np.sin(bearing_rad),
            np.cos(plunge_rad) * np.cos(bearing_rad),
            -np.sin(plunge_rad)
        ])

def analyze_axis_plane_relationship_comprehensive(axis: np.ndarray, plane_normal: np.ndarray, relationship_params: Dict = None):
    """Analyze geometric relationship between fold axis and axial plane with comprehensive structural analysis"""
    try:
        if relationship_params is None:
            relationship_params = {}
            
        # Comprehensive axis-plane relationship analysis
        geometric_analysis = _perform_axis_plane_geometric_analysis_comprehensive(axis, plane_normal, relationship_params)
        angular_relationship_analysis = _analyze_angular_relationships_comprehensive(axis, plane_normal, relationship_params)
        structural_significance_analysis = _analyze_structural_significance_comprehensive(axis, plane_normal, relationship_params)
        kinematic_interpretation = _interpret_kinematic_implications_comprehensive(axis, plane_normal, relationship_params)
        uncertainty_assessment = _assess_axis_plane_uncertainties_comprehensive(axis, plane_normal, relationship_params)
        classification_analysis = _classify_fold_geometry_comprehensive(geometric_analysis, angular_relationship_analysis, relationship_params)
        
        # Comprehensive relationship integration
        comprehensive_relationship_analysis = _integrate_comprehensive_axis_plane_analysis(
            axis, plane_normal, geometric_analysis, angular_relationship_analysis, structural_significance_analysis,
            kinematic_interpretation, uncertainty_assessment, classification_analysis, relationship_params
        )
        
        return comprehensive_relationship_analysis
        
    except Exception as e:
        print(f"Error in analyze_axis_plane_relationship_comprehensive: {e}")
        dot_product = np.dot(axis, plane_normal)
        angle = np.degrees(np.arccos(np.abs(dot_product)))
        if angle < 10:
            return 'axis_parallel_to_normal'
        elif angle > 80:
            return 'axis_perpendicular_to_normal'
        else:
            return 'oblique_relationship'

