def calculate_weighted_fold_axis_comprehensive(fold, axis_methods: Dict, weighting_params: Dict = None):
    """Calculate weighted average fold axis from multiple methods with comprehensive multi-method integration"""
    try:
        if weighting_params is None:
            weighting_params = {}
            
        # Comprehensive weighted fold axis calculation
        method_reliability_assessment = _assess_axis_method_reliability_comprehensive(axis_methods, weighting_params)
        dynamic_weight_calculation = _calculate_dynamic_method_weights_comprehensive(axis_methods, method_reliability_assessment, weighting_params)
        axis_consistency_analysis = _analyze_axis_method_consistency_comprehensive(axis_methods, weighting_params)
        uncertainty_weighted_integration = _perform_uncertainty_weighted_integration_comprehensive(axis_methods, dynamic_weight_calculation, weighting_params)
        geometric_validation = _validate_weighted_axis_geometry_comprehensive(uncertainty_weighted_integration, axis_methods, weighting_params)
        statistical_analysis = _perform_weighted_axis_statistical_analysis_comprehensive(axis_methods, dynamic_weight_calculation, weighting_params)
        
        # Comprehensive weighted axis integration
        comprehensive_weighted_axis = _integrate_comprehensive_weighted_fold_axis(
            fold, axis_methods, method_reliability_assessment, dynamic_weight_calculation, axis_consistency_analysis,
            uncertainty_weighted_integration, geometric_validation, statistical_analysis, weighting_params
        )
        
        return comprehensive_weighted_axis
        
    except Exception as e:
        print(f"Error in calculate_weighted_fold_axis_comprehensive: {e}")
        weights = {'best_fit_pi_axis': 0.3, 'beta_axis': 0.2, 'cylindrical_best_fit': 0.25, 'hinge_line_analysis': 0.15, 'profile_analysis': 0.1}
        weighted_axis = np.zeros(3)
        total_weight = 0
        for method, axis in axis_methods.items():
            if method in weights:
                weighted_axis += weights[method] * axis
                total_weight += weights[method]
        return weighted_axis / total_weight if total_weight > 0 else np.array([1, 0, 0])

