def calculate_fold_axis_statistics_comprehensive(fold, axis_methods: Dict, statistics_params: Dict = None):
    """Calculate fold axis statistics and uncertainty with comprehensive uncertainty analysis"""
    try:
        if statistics_params is None:
            statistics_params = {}
            
        # Comprehensive fold axis statistics
        descriptive_statistics = _calculate_fold_axis_descriptive_statistics_comprehensive(axis_methods, statistics_params)
        uncertainty_quantification = _quantify_fold_axis_uncertainties_comprehensive(axis_methods, statistics_params)
        distribution_analysis = _analyze_fold_axis_distributions_comprehensive(axis_methods, statistics_params)
        confidence_analysis = _perform_fold_axis_confidence_analysis_comprehensive(axis_methods, statistics_params)
        method_agreement_analysis = _analyze_fold_axis_method_agreement_comprehensive(axis_methods, statistics_params)
        statistical_validation = _validate_fold_axis_statistics_comprehensive(descriptive_statistics, uncertainty_quantification, statistics_params)
        
        # Comprehensive statistics integration
        comprehensive_statistics = _integrate_comprehensive_fold_axis_statistics(
            fold, axis_methods, descriptive_statistics, uncertainty_quantification, distribution_analysis,
            confidence_analysis, method_agreement_analysis, statistical_validation, statistics_params
        )
        
        return comprehensive_statistics
        
    except Exception as e:
        print(f"Error in calculate_fold_axis_statistics_comprehensive: {e}")
        axes = np.array([axis for axis in axis_methods.values()])
        mean_axis = np.mean(axes, axis=0)
        axis_std = np.std(axes, axis=0)
        covariance = np.cov(axes.T)
        eigenvals, eigenvecs = np.linalg.eigh(covariance)
        return {
            'mean_axis': mean_axis.tolist(),
            'standard_deviation': axis_std.tolist(),
            'uncertainty_ellipse': {'semi_major': float(np.sqrt(eigenvals[2])), 'semi_minor': float(np.sqrt(eigenvals[0])), 'orientation': eigenvecs[:, 2].tolist()},
            'overall_confidence': float(1 / (1 + np.mean(eigenvals))),
            'method_agreement': float(1 - np.mean(axis_std))
        }

