def classify_fold_tightness_comprehensive(measurements: Dict, tightness_params: Dict = None):
    """Classify fold tightness using comprehensive multi-criteria analysis"""
    try:
        if tightness_params is None:
            tightness_params = {}
            
        # Comprehensive tightness classification
        interlimb_tightness = _classify_interlimb_tightness_comprehensive(measurements, tightness_params)
        amplitude_wavelength_tightness = _classify_amplitude_wavelength_tightness_comprehensive(measurements, tightness_params)
        hinge_curvature_tightness = _classify_hinge_curvature_tightness_comprehensive(measurements, tightness_params)
        limb_dip_tightness = _classify_limb_dip_tightness_comprehensive(measurements, tightness_params)
        integrated_tightness = _integrate_tightness_classifications_comprehensive(
            interlimb_tightness, amplitude_wavelength_tightness, hinge_curvature_tightness, limb_dip_tightness, tightness_params
        )
        
        return integrated_tightness
        
    except Exception as e:
        print(f"Error in classify_fold_tightness_comprehensive: {e}")
        interlimb_angle = measurements.get('interlimb_angle', 60)
        amplitude = measurements.get('amplitude', 50)
        wavelength = measurements.get('wavelength', 200)
        amplitude_wavelength_ratio = amplitude / wavelength
        tightness_score = (180 - interlimb_angle) / 180 + amplitude_wavelength_ratio
        if tightness_score < 0.3:
            tightness = 'gentle'
        elif tightness_score < 0.6:
            tightness = 'open'
        elif tightness_score < 0.8:
            tightness = 'close'
        else:
            tightness = 'tight'
        return {'tightness_classification': tightness, 'tightness_score': float(tightness_score), 'interlimb_angle_component': interlimb_angle, 'amplitude_wavelength_component': float(amplitude_wavelength_ratio)}

